//  UPPER PRIMARY  (Year 3 – Year 6)
// ============================================================

const UPPER_ENGLISH: MCQ[] = [
  { id: 'up-e-1', q: 'Which word is a verb?', choices: ['Quickly', 'Run', 'Happy', 'Yellow'], answer: 1, explanation: 'Verbs name actions — "run" is something you do.', acCode: 'AC9E3LA03' },
  { id: 'up-e-2', q: 'A synonym for "happy" is:', choices: ['Sad', 'Joyful', 'Tired', 'Angry'], answer: 1, explanation: 'Synonyms have similar meanings. Joyful and happy both describe positive feelings.', acCode: 'AC9E4LA09' },
  { id: 'up-e-3', q: 'Which is a compound word?', choices: ['Running', 'Sunshine', 'Quickly', 'Beautiful'], answer: 1, explanation: 'A compound word joins two whole words — sun + shine.', acCode: 'AC9E3LA08' },
  { id: 'up-e-4', q: 'Which sentence uses a simile?', choices: ['She runs fast.', 'She is a star.', 'She runs like the wind.', 'She is running.'], answer: 2, explanation: 'A simile compares two things using "like" or "as".', acCode: 'AC9E5LE03' },
  { id: 'up-e-5', q: 'What is the plural of "child"?', choices: ['Childs', 'Childes', 'Children', 'Childrens'], answer: 2, explanation: 'Child is an irregular noun — its plural is children.', acCode: 'AC9E3LA08' },
  { id: 'up-e-6', q: 'Which word is an adjective?', choices: ['Sing', 'Loudly', 'Loud', 'Song'], answer: 2, explanation: 'Adjectives describe nouns — "loud" describes how something sounds.', acCode: 'AC9E3LA03' },
  { id: 'up-e-7', q: 'What is the correct contraction for "do not"?', choices: ['Do’nt', 'Don’t', 'Dont’', 'Donot'], answer: 1, explanation: 'The apostrophe replaces the missing "o" — don’t.', acCode: 'AC9E3LY08' },
  { id: 'up-e-8', q: 'Which word means "to make smaller"?', choices: ['Expand', 'Reduce', 'Inflate', 'Magnify'], answer: 1, explanation: 'Reduce means to decrease in size or amount.', acCode: 'AC9E5LA09' },
  { id: 'up-e-9', q: '"The wind whispered through the trees" uses:', choices: ['Simile', 'Metaphor', 'Personification', 'Onomatopoeia'], answer: 2, explanation: 'Personification gives human qualities (whispering) to a non-human thing (wind).', acCode: 'AC9E5LE03' },
  { id: 'up-e-10', q: 'Which is correctly punctuated?', choices: ['"Hello," she said.', '"Hello she said."', 'Hello, she said', '"Hello", she said'], answer: 0, explanation: 'In Australian English, the comma sits inside the quotation marks before the speech tag.', acCode: 'AC9E5LA08' },
  { id: 'up-e-11', q: 'A "stanza" is a part of a:', choices: ['Story', 'Poem', 'Letter', 'Report'], answer: 1, explanation: 'Stanzas are groups of lines in poems, like paragraphs in prose.', acCode: 'AC9E5LE04' },
  { id: 'up-e-12', q: 'The prefix "un-" means:', choices: ['Again', 'Not', 'Before', 'After'], answer: 1, explanation: '"Un-" reverses meaning — happy becomes unhappy, do becomes undo.', acCode: 'AC9E4LA08' },
  { id: 'up-e-13', q: 'Which word is an adverb?', choices: ['Slow', 'Slowly', 'Slowness', 'Sloth'], answer: 1, explanation: 'Adverbs often end in -ly and modify verbs.', acCode: 'AC9E4LA03' },
  { id: 'up-e-14', q: 'In a paragraph, the topic sentence usually:', choices: ['Comes last', 'Comes first and states the main idea', 'Is always a question', 'Is the shortest sentence'], answer: 1, explanation: 'Topic sentences typically open a paragraph and signal what it will cover.', acCode: 'AC9E5LY06' },
  { id: 'up-e-15', q: 'Which is a metaphor?', choices: ['Time is like sand.', 'Time is money.', 'Time runs fast.', 'Time stood still.'], answer: 1, explanation: 'A metaphor says one thing IS another, without using like or as.', acCode: 'AC9E6LE03' },
  { id: 'up-e-16', q: 'Which word is the antonym of "ancient"?', choices: ['Old', 'Modern', 'Antique', 'Historic'], answer: 1, explanation: 'Modern is the opposite of ancient.', acCode: 'AC9E5LA09' },
  { id: 'up-e-17', q: '"Should’ve" is a contraction of:', choices: ['Should be', 'Should have', 'Should of', 'Should not'], answer: 1, explanation: 'Should’ve = should have. "Should of" is a common error.', acCode: 'AC9E4LY08' },
  { id: 'up-e-18', q: 'Which type of writing aims to argue a point?', choices: ['Narrative', 'Recount', 'Persuasive', 'Procedural'], answer: 2, explanation: 'Persuasive texts try to convince readers of a viewpoint.', acCode: 'AC9E6LY06' },
  { id: 'up-e-19', q: 'Onomatopoeia is when a word:', choices: ['Sounds like what it means', 'Has many syllables', 'Means the opposite', 'Is foreign'], answer: 0, explanation: 'Buzz, sizzle and pop all sound like the noise they describe.', acCode: 'AC9E5LE03' },
  { id: 'up-e-20', q: 'In direct speech, what punctuation goes around the spoken words?', choices: ['Brackets', 'Apostrophes', 'Quotation marks', 'Hyphens'], answer: 2, explanation: 'Quotation marks (" ") show the exact words a speaker said.', acCode: 'AC9E4LA08' },
  { id: 'up-e-21', q: 'A character’s "point of view" is:', choices: ['Where they live', 'How they see things', 'Their age', 'Their name'], answer: 1, explanation: 'Point of view is the perspective from which a character experiences events.', acCode: 'AC9E5LE02' },
  { id: 'up-e-22', q: 'Which is a complex sentence?', choices: ['I ran across the playground.', 'I ran fast through the park.', 'I ran because the bus was leaving.', 'Run quickly to the corner now!'], answer: 2, explanation: 'Complex sentences join a main clause with a dependent clause using words like "because".', acCode: 'AC9E5LA04' },
  { id: 'up-e-23', q: 'The "theme" of a story is:', choices: ['Where it happens', 'The main message or idea', 'The first sentence', 'The narrator'], answer: 1, explanation: 'Theme is the big idea or message the author wants readers to take away.', acCode: 'AC9E6LE02' },
  { id: 'up-e-24', q: 'Which word is spelled correctly?', choices: ['Definately', 'Definatly', 'Definitely', 'Definitley'], answer: 2, explanation: 'Definitely is commonly misspelled — note the "ite" in the middle.', acCode: 'AC9E5LY10' },
  { id: 'up-e-25', q: 'A "narrator" is:', choices: ['The illustrator', 'The voice telling the story', 'The publisher', 'The main character’s pet'], answer: 1, explanation: 'The narrator is who tells the story — first-person, third-person or omniscient.', acCode: 'AC9E5LE02' },
];

const UPPER_MATHS: MCQ[] = [
  { id: 'up-m-1', q: '6 × 7 = ?', choices: ['36', '42', '48', '54'], answer: 1, explanation: 'Times tables — six sevens make 42.', acCode: 'AC9M4N06' },
  { id: 'up-m-2', q: 'Which fraction is equivalent to 1/2?', choices: ['2/3', '3/6', '4/9', '5/12'], answer: 1, explanation: '3/6 simplifies to 1/2 because both top and bottom divide by 3.', acCode: 'AC9M5N04' },
  { id: 'up-m-3', q: 'What is 25% of 80?', choices: ['10', '15', '20', '25'], answer: 2, explanation: '25% is one quarter. 80 ÷ 4 = 20.', acCode: 'AC9M6N05' },
  { id: 'up-m-4', q: 'A right angle measures:', choices: ['45°', '90°', '120°', '180°'], answer: 1, explanation: 'A right angle is a quarter turn — exactly 90°.', acCode: 'AC9M5M03' },
  { id: 'up-m-5', q: 'How many minutes in 1.5 hours?', choices: ['60', '75', '90', '120'], answer: 2, explanation: 'One hour = 60 minutes; half an hour = 30 minutes; total 90.', acCode: 'AC9M4M03' },
  { id: 'up-m-6', q: '0.25 as a fraction is:', choices: ['1/2', '1/3', '1/4', '1/5'], answer: 2, explanation: '0.25 = 25/100 = 1/4.', acCode: 'AC9M5N05' },
  { id: 'up-m-7', q: 'The area of a 5cm × 3cm rectangle is:', choices: ['8 cm²', '15 cm²', '16 cm²', '30 cm²'], answer: 1, explanation: 'Area of a rectangle = length × width = 5 × 3 = 15 cm².', acCode: 'AC9M5M02' },
  { id: 'up-m-8', q: 'Which is a prime number?', choices: ['4', '6', '9', '11'], answer: 3, explanation: 'A prime number has exactly two factors: 1 and itself. 11 has only 1 and 11.', acCode: 'AC9M6N02' },
  { id: 'up-m-9', q: 'Next in the pattern: 5, 10, 20, 40, ?', choices: ['50', '60', '70', '80'], answer: 3, explanation: 'Each term doubles — multiply by 2 to get the next.', acCode: 'AC9M5A02' },
  { id: 'up-m-10', q: '3/4 + 1/4 = ?', choices: ['1/2 (halved by mistake)', '4/4 (or 1)', '4/8 (added denominators)', '2/4 (averaged numerators)'], answer: 1, explanation: 'Same denominator: add the numerators. 3+1 = 4. 4/4 = 1 whole.', acCode: 'AC9M5N04' },
  { id: 'up-m-11', q: 'Which has the longest perimeter?', choices: ['4cm square', '3×6cm rectangle', '5cm equilateral triangle', '2×8cm rectangle'], answer: 3, explanation: 'Perimeters: 16, 18, 15, 20. The 2×8 rectangle wins.', acCode: 'AC9M5M02' },
  { id: 'up-m-12', q: 'The mean of 4, 6, 8, 10:', choices: ['6', '7', '8', '9'], answer: 1, explanation: 'Mean = (4+6+8+10) ÷ 4 = 28 ÷ 4 = 7.', acCode: 'AC9M6ST01' },
  { id: 'up-m-13', q: 'How many faces does a triangular prism have?', choices: ['4', '5', '6', '8'], answer: 1, explanation: 'A triangular prism has 2 triangular faces + 3 rectangular faces = 5.', acCode: 'AC9M5SP01' },
  { id: 'up-m-14', q: '125 ÷ 5 = ?', choices: ['15', '20', '25', '30'], answer: 2, explanation: 'Five 25s make 125, so 125 ÷ 5 = 25.', acCode: 'AC9M4N06' },
  { id: 'up-m-15', q: 'A "factor" of 12 is:', choices: ['5', '7', '8', '4'], answer: 3, explanation: 'A factor divides evenly. 12 ÷ 4 = 3, so 4 is a factor.', acCode: 'AC9M6N02' },
  { id: 'up-m-16', q: 'Probability of rolling an even number on a six-sided die:', choices: ['1/6', '1/3', '1/2', '2/3'], answer: 2, explanation: '3 of 6 faces are even (2, 4, 6), so 3/6 = 1/2.', acCode: 'AC9M6P01' },
  { id: 'up-m-17', q: 'Round 347 to the nearest 100:', choices: ['300', '340', '350', '400'], answer: 0, explanation: '347 is closer to 300 than to 400.', acCode: 'AC9M5N02' },
  { id: 'up-m-18', q: 'Convert 3 hours into minutes:', choices: ['120', '150', '180', '240'], answer: 2, explanation: '60 minutes × 3 hours = 180 minutes.', acCode: 'AC9M4M03' },
  { id: 'up-m-19', q: 'The angle on a straight line is:', choices: ['90°', '120°', '180°', '360°'], answer: 2, explanation: 'A straight angle is half a full turn — 180°.', acCode: 'AC9M5M03' },
  { id: 'up-m-20', q: '50% of 60 is the same as:', choices: ['1/4 of 60', '1/3 of 60', '1/2 of 60', '2/3 of 60'], answer: 2, explanation: '50% means one half. 1/2 of 60 = 30.', acCode: 'AC9M6N05' },
  { id: 'up-m-21', q: 'A square has rotational symmetry of order:', choices: ['1', '2', '3', '4'], answer: 3, explanation: 'A square looks the same after 4 quarter-turns around its centre.', acCode: 'AC9M6SP02' },
  { id: 'up-m-22', q: 'The decimal 1.6 means:', choices: ['1 and 6 hundredths', '1 and 6 tenths', '16 hundredths', '16 wholes'], answer: 1, explanation: 'In 1.6, the 6 sits in the tenths column.', acCode: 'AC9M4N03' },
  { id: 'up-m-23', q: 'A "right-angled" triangle has one angle of:', choices: ['60°', '90°', '120°', '180°'], answer: 1, explanation: 'Right-angled triangles always contain one 90° angle.', acCode: 'AC9M5M03' },
  { id: 'up-m-24', q: '3 × 0 = ?', choices: ['0', '3', '30', '1'], answer: 0, explanation: 'Anything multiplied by 0 equals 0.', acCode: 'AC9M4N06' },
  { id: 'up-m-25', q: '1 km = how many metres?', choices: ['10', '100', '1000', '10000'], answer: 2, explanation: 'Kilo- means thousand. 1 km = 1000 m.', acCode: 'AC9M5M01' },
];

const UPPER_HISTORY: MCQ[] = [
  { id: 'up-h-1', q: 'Aboriginal and Torres Strait Islander peoples have lived in Australia for at least:', choices: ['200 years', '2,000 years', '60,000 years', '500 years'], answer: 2, explanation: 'Archaeological evidence places First Nations presence in Australia at 60,000+ years.', acCode: 'AC9HS4K02' },
  { id: 'up-h-2', q: 'Captain James Cook reached Botany Bay in:', choices: ['1492', '1770', '1788', '1901'], answer: 1, explanation: 'Cook charted the east coast in April 1770 and claimed it for Britain.', acCode: 'AC9HS4K01' },
  { id: 'up-h-3', q: 'The First Fleet arrived at Sydney Cove in:', choices: ['1788', '1770', '1800', '1825'], answer: 0, explanation: '11 ships carrying convicts and marines landed in January 1788.', acCode: 'AC9HS5K01' },
  { id: 'up-h-4', q: 'Australia became a federation in:', choices: ['1788', '1850', '1901', '1945'], answer: 2, explanation: 'The six British colonies joined as the Commonwealth of Australia on 1 January 1901.', acCode: 'AC9HS6K01' },
  { id: 'up-h-5', q: 'The Eureka Stockade (1854) was a:', choices: ['Military fort', 'Goldfields uprising', 'Cricket ground', 'Type of ship'], answer: 1, explanation: 'Gold miners at Ballarat rebelled against the licence system — a step toward democracy.', acCode: 'AC9HS5K02' },
  { id: 'up-h-6', q: 'Which ancient civilisation built the pyramids?', choices: ['Romans', 'Greeks', 'Egyptians', 'Chinese'], answer: 2, explanation: 'Ancient Egyptians built the pyramids as tombs for pharaohs starting around 2600 BCE.', acCode: 'AC9HS6K04' },
  { id: 'up-h-7', q: 'The Silk Road was a:', choices: ['Type of cloth', 'Trading route between East and West', 'River in China', 'Famous bridge'], answer: 1, explanation: 'A network of overland routes carried silk, spices and ideas between China and the Mediterranean.', acCode: 'AC9HS6K04' },
  { id: 'up-h-8', q: 'A "primary source" is:', choices: ['A second-hand account', 'A story made up later', 'Original evidence from the time', 'A modern textbook'], answer: 2, explanation: 'Primary sources (diaries, photos, artifacts) come from the period being studied.', acCode: 'AC9HS5S03' },
  { id: 'up-h-9', q: 'Anzac Day commemorates the landing at:', choices: ['Normandy', 'Gallipoli', 'Singapore', 'Tobruk'], answer: 1, explanation: 'Australian and New Zealand troops landed at Gallipoli on 25 April 1915.', acCode: 'AC9HS6K02' },
  { id: 'up-h-10', q: 'Who were the first people to invent writing?', choices: ['Romans', 'Vikings', 'Sumerians', 'Aztecs'], answer: 2, explanation: 'The Sumerians of Mesopotamia developed cuneiform writing about 5,500 years ago.', acCode: 'AC9HS6K04' },
  { id: 'up-h-11', q: 'The 1967 Referendum changed the rules so that:', choices: ['Australia got a new flag', 'Aboriginal people were counted in the census', 'Voting age was lowered', 'States lost their power'], answer: 1, explanation: 'Over 90% of Australians voted YES to count First Nations peoples in the census.', acCode: 'AC9HS6K03' },
  { id: 'up-h-12', q: 'Gold was first discovered in Australia in:', choices: ['1851', '1788', '1901', '1870'], answer: 0, explanation: 'The 1851 gold rushes in NSW and Victoria transformed Australia’s population and economy.', acCode: 'AC9HS5K02' },
  { id: 'up-h-13', q: 'The Stolen Generations refers to:', choices: ['Gold rush thieves', 'Aboriginal children removed from their families', 'Lost colonial documents', 'Convicts who escaped'], answer: 1, explanation: 'Government policies removed Aboriginal and Torres Strait Islander children from families between the 1900s and 1970s.', acCode: 'AC9HS6K03' },
  { id: 'up-h-14', q: 'Australia’s national capital is:', choices: ['Sydney', 'Melbourne', 'Canberra', 'Adelaide'], answer: 2, explanation: 'Canberra was purpose-built as a compromise between Sydney and Melbourne.', acCode: 'AC9HS6K01' },
  { id: 'up-h-15', q: 'The Great Wall of China was built mostly to:', choices: ['Hold water', 'Defend against invaders', 'Mark a trade route', 'Trap animals'], answer: 1, explanation: 'Successive Chinese dynasties built the wall to defend against northern nomads.', acCode: 'AC9HS6K04' },
  { id: 'up-h-16', q: 'Australia became a "Commonwealth" because:', choices: ['It joined the EU', 'The six colonies united as one nation', 'It declared war', 'It became American'], answer: 1, explanation: 'Federation united NSW, Victoria, Queensland, SA, WA and Tasmania under a single federal government.', acCode: 'AC9HS6K01' },
  { id: 'up-h-17', q: 'A "convict" was someone who was:', choices: ['A free settler', 'Sent to Australia as punishment', 'A Royal Navy officer', 'An Aboriginal Elder'], answer: 1, explanation: 'Britain transported around 160,000 convicts to Australia between 1788 and 1868.', acCode: 'AC9HS5K01' },
  { id: 'up-h-18', q: 'The Mabo decision (1992) is significant because it:', choices: ['Created Federation', 'Recognised Native Title', 'Established Canberra', 'Ended convict transportation'], answer: 1, explanation: 'The High Court ruled that Aboriginal and Torres Strait Islander peoples had rights to land predating European arrival.', acCode: 'AC9HS6K03' },
  { id: 'up-h-19', q: 'Who was Captain Arthur Phillip?', choices: ['First Governor of NSW', 'Inventor of the steam engine', 'First Prime Minister', 'A famous convict'], answer: 0, explanation: 'Phillip commanded the First Fleet and became the first Governor of New South Wales.', acCode: 'AC9HS5K01' },
  { id: 'up-h-20', q: 'A "secondary source" is:', choices: ['Direct original evidence created during events', 'Something written about events after they happened', 'Always more accurate than primary sources', 'Photographs alone, with no written sources'], answer: 1, explanation: 'Secondary sources interpret or analyse the past — like textbooks and documentaries.', acCode: 'AC9HS5S03' },
  { id: 'up-h-21', q: 'The first Australian Prime Minister was:', choices: ['Robert Menzies', 'Edmund Barton', 'Henry Lawson', 'Alfred Deakin'], answer: 1, explanation: 'Edmund Barton became Australia’s first PM at Federation in 1901.', acCode: 'AC9HS6K01' },
  { id: 'up-h-22', q: 'Songlines are:', choices: ['Australian pop hits and chart music', 'Aboriginal cultural pathways mapped through song', 'Lines drawn for queuing at busy events', 'Old telephone wires strung between poles'], answer: 1, explanation: 'Songlines link sites, stories and knowledge across Country and have done for tens of thousands of years.', acCode: 'AC9HS4K02' },
  { id: 'up-h-23', q: 'Which ancient civilisation invented democracy?', choices: ['Egypt', 'Persia', 'Athens (Greece)', 'Rome'], answer: 2, explanation: 'Ancient Athens developed direct democracy around 500 BCE.', acCode: 'AC9HS6K04' },
  { id: 'up-h-24', q: 'When did Indigenous Australians get the right to vote in federal elections?', choices: ['1901', '1949', '1962', '1984'], answer: 2, explanation: 'The Commonwealth Electoral Act was changed in 1962 to grant federal voting rights.', acCode: 'AC9HS6K03' },
  { id: 'up-h-25', q: 'The transcontinental railway across Australia was completed in:', choices: ['1901', '1917', '1939', '1962'], answer: 1, explanation: 'The Trans-Australian Railway linking the east and west coasts was completed in 1917.', acCode: 'AC9HS6K01' },
];

const UPPER_GEOGRAPHY: MCQ[] = [
  { id: 'up-g-1', q: 'The capital of Australia is:', choices: ['Sydney', 'Melbourne', 'Canberra', 'Brisbane'], answer: 2, explanation: 'Canberra was chosen as a compromise capital and built in the ACT.', acCode: 'AC9HS4K04' },
  { id: 'up-g-2', q: 'How many states are in Australia?', choices: ['5', '6', '7', '8'], answer: 1, explanation: 'NSW, Victoria, Queensland, SA, WA, Tasmania — plus two territories (NT, ACT).', acCode: 'AC9HS4K04' },
  { id: 'up-g-3', q: 'The longest river in Australia is the:', choices: ['Yarra', 'Murray', 'Swan', 'Brisbane'], answer: 1, explanation: 'The Murray flows about 2,508 km from the Snowy Mountains to the Southern Ocean.', acCode: 'AC9HS5K05' },
  { id: 'up-g-4', q: 'Darwin is the capital of:', choices: ['Queensland', 'Western Australia', 'Northern Territory', 'South Australia'], answer: 2, explanation: 'Darwin sits on the Top End coast and is the NT’s capital.', acCode: 'AC9HS4K04' },
  { id: 'up-g-5', q: 'Which continent is Australia part of?', choices: ['Asia', 'Oceania', 'Africa', 'Europe'], answer: 1, explanation: 'Oceania includes Australia, New Zealand and the Pacific islands.', acCode: 'AC9HS6K06' },
  { id: 'up-g-6', q: 'The Great Barrier Reef lies off the coast of:', choices: ['Tasmania', 'Western Australia', 'Queensland', 'Victoria'], answer: 2, explanation: 'The reef stretches over 2,300 km along the Queensland coast.', acCode: 'AC9HS5K05' },
  { id: 'up-g-7', q: 'A "tropical" climate is:', choices: ['Cold and dry', 'Hot and humid', 'Mild and rainy', 'Snowy'], answer: 1, explanation: 'Tropical climates near the equator are warm year-round with high humidity.', acCode: 'AC9HS5K05' },
  { id: 'up-g-8', q: 'Which is the largest ocean?', choices: ['Atlantic', 'Indian', 'Pacific', 'Arctic'], answer: 2, explanation: 'The Pacific Ocean covers about a third of Earth’s surface.', acCode: 'AC9HS6K06' },
  { id: 'up-g-9', q: 'Mount Everest is in which continent?', choices: ['Africa', 'Asia', 'Europe', 'South America'], answer: 1, explanation: 'Everest sits on the Nepal-China border in the Himalayas of Asia.', acCode: 'AC9HS6K06' },
  { id: 'up-g-10', q: 'Indonesia is to Australia’s:', choices: ['South', 'East', 'North', 'West'], answer: 2, explanation: 'Indonesia is Australia’s closest northern neighbour.', acCode: 'AC9HS6K06' },
  { id: 'up-g-11', q: 'A "climate" is:', choices: ['Today’s weather', 'The long-term pattern of weather in a region', 'A type of mountain', 'A season'], answer: 1, explanation: 'Climate describes weather patterns over decades; weather changes day to day.', acCode: 'AC9HS5K05' },
  { id: 'up-g-12', q: 'A "biome" is:', choices: ['A small farming village or hamlet', 'A community of plants and animals adapted to a region', 'A specific weather event like a storm', 'A new continent recently discovered'], answer: 1, explanation: 'Biomes like tundra, desert and rainforest are shaped by climate and soil.', acCode: 'AC9HS5K05' },
  { id: 'up-g-13', q: 'Which biome covers most of central Australia?', choices: ['Rainforest', 'Desert', 'Wetlands', 'Tundra'], answer: 1, explanation: 'The Outback is dominated by arid and semi-arid desert.', acCode: 'AC9HS5K05' },
  { id: 'up-g-14', q: 'The line of 0° latitude is called the:', choices: ['Prime Meridian', 'Equator', 'Tropic of Cancer', 'Date Line'], answer: 1, explanation: 'The Equator runs east-west around Earth’s middle.', acCode: 'AC9HS6K06' },
  { id: 'up-g-15', q: 'Antarctica is mostly covered by:', choices: ['Tropical forest', 'Sand', 'Ice', 'Grassland'], answer: 2, explanation: 'A massive ice sheet covers around 98% of Antarctica.', acCode: 'AC9HS6K06' },
  { id: 'up-g-16', q: 'The Murray-Darling Basin is important because it:', choices: ['Is Australia’s smallest catchment', 'Provides most of our irrigated food', 'Sits in Tasmania', 'Is artificially built'], answer: 1, explanation: 'The basin grows around 40% of Australian crops and supports many communities.', acCode: 'AC9HS5K05' },
  { id: 'up-g-17', q: 'A "contour line" on a map shows:', choices: ['Roads', 'Lines of equal height', 'Rivers only', 'Country borders'], answer: 1, explanation: 'Contour lines join points of the same elevation, revealing hills and valleys.', acCode: 'AC9HS5S02' },
  { id: 'up-g-18', q: 'Which Australian state has the largest area?', choices: ['Queensland', 'New South Wales', 'Western Australia', 'Victoria'], answer: 2, explanation: 'WA covers about a third of the continent.', acCode: 'AC9HS4K04' },
  { id: 'up-g-19', q: 'The "Top End" refers to:', choices: ['Tasmania', 'The northern Northern Territory', 'Cape York Queensland', 'Western South Australia'], answer: 1, explanation: 'The Top End is the tropical northern strip of the NT.', acCode: 'AC9HS4K04' },
  { id: 'up-g-20', q: 'Sustainable use of resources means:', choices: ['Using them up quickly', 'Using them in ways that last for future generations', 'Selling them', 'Hiding them'], answer: 1, explanation: 'Sustainability balances current needs with long-term ecosystem health.', acCode: 'AC9HS5K06' },
  { id: 'up-g-21', q: 'Which country shares a border with Papua New Guinea?', choices: ['Australia', 'Indonesia', 'New Zealand', 'Japan'], answer: 1, explanation: 'PNG and Indonesia share the island of New Guinea.', acCode: 'AC9HS6K06' },
  { id: 'up-g-22', q: 'The Daintree Rainforest is in:', choices: ['Tasmania', 'Far North Queensland', 'Western Australia', 'Northern Territory'], answer: 1, explanation: 'The Daintree is one of the oldest tropical rainforests in the world, in Far North Queensland.', acCode: 'AC9HS5K05' },
  { id: 'up-g-23', q: 'A "delta" forms where:', choices: ['A river meets a sea or lake', 'Two mountains meet', 'Three roads cross', 'A volcano erupts'], answer: 0, explanation: 'Deltas are flat, fan-shaped landforms made of sediment dropped at a river mouth.', acCode: 'AC9HS5K05' },
  { id: 'up-g-24', q: 'The Indigenous name for Ayers Rock is:', choices: ['Kata Tjuta', 'Uluru', 'Kakadu', 'Karijini'], answer: 1, explanation: 'Uluru is the Anangu name and was officially restored in 2002.', acCode: 'AC9HS4K02' },
  { id: 'up-g-25', q: 'New Zealand lies to Australia’s:', choices: ['North', 'East', 'South', 'West'], answer: 1, explanation: 'NZ sits east across the Tasman Sea.', acCode: 'AC9HS6K06' },
];

const UPPER_SCIENCE: MCQ[] = [
  { id: 'up-s-1', q: 'Which is NOT a state of matter?', choices: ['Solid', 'Liquid', 'Gas', 'Electricity'], answer: 3, explanation: 'The three main states are solid, liquid and gas. Electricity is a form of energy.', acCode: 'AC9S5U02' },
  { id: 'up-s-2', q: 'Plants make their own food through:', choices: ['Respiration', 'Photosynthesis', 'Digestion', 'Evaporation'], answer: 1, explanation: 'Photosynthesis uses sunlight, CO₂ and water to make glucose and oxygen.', acCode: 'AC9S5U01' },
  { id: 'up-s-3', q: 'The Earth orbits:', choices: ['The Moon', 'The Sun', 'Mars', 'A black hole'], answer: 1, explanation: 'Earth completes one orbit around the Sun every 365.25 days.', acCode: 'AC9S5U03' },
  { id: 'up-s-4', q: 'Which gas do humans need to breathe?', choices: ['Carbon dioxide', 'Oxygen', 'Hydrogen', 'Helium'], answer: 1, explanation: 'Our lungs take oxygen from air; we exhale carbon dioxide.', acCode: 'AC9S4U01' },
  { id: 'up-s-5', q: 'Water boils at:', choices: ['50°C', '75°C', '100°C', '120°C'], answer: 2, explanation: 'At sea level, water boils at 100°C and turns to steam.', acCode: 'AC9S5U02' },
  { id: 'up-s-6', q: 'Which simple machine is a "wedge"?', choices: ['Wheel', 'Pulley', 'Axe blade', 'Gear'], answer: 2, explanation: 'A wedge is a triangular tool that splits or holds things in place.', acCode: 'AC9S4U02' },
  { id: 'up-s-7', q: 'The closest planet to the Sun is:', choices: ['Venus', 'Earth', 'Mercury', 'Mars'], answer: 2, explanation: 'Mercury’s average distance from the Sun is about 58 million km.', acCode: 'AC9S5U03' },
  { id: 'up-s-8', q: 'Animals that eat only plants are called:', choices: ['Carnivores', 'Omnivores', 'Herbivores', 'Insectivores'], answer: 2, explanation: 'Herbivores feed on plants — like cows, sheep and kangaroos.', acCode: 'AC9S5U01' },
  { id: 'up-s-9', q: 'A "reversible change" is something like:', choices: ['Burning paper', 'Cooking an egg', 'Melting ice', 'Mixing cement'], answer: 2, explanation: 'Melted ice can refreeze; reversible changes don’t produce new substances.', acCode: 'AC9S6U02' },
  { id: 'up-s-10', q: 'Which is an example of friction?', choices: ['A balloon rising', 'A book sliding to a stop on a table', 'A pendulum swinging', 'Water flowing downhill'], answer: 1, explanation: 'Friction is the resistive force between surfaces — it stops the book.', acCode: 'AC9S4U02' },
  { id: 'up-s-11', q: 'The Sun is a:', choices: ['Planet', 'Star', 'Moon', 'Comet'], answer: 1, explanation: 'The Sun is the closest star to Earth.', acCode: 'AC9S5U03' },
  { id: 'up-s-12', q: 'How many planets are in our Solar System?', choices: ['6', '8', '9', '10'], answer: 1, explanation: '8 since Pluto was reclassified as a dwarf planet in 2006.', acCode: 'AC9S5U03' },
  { id: 'up-s-13', q: 'Which liquid is the best electrical conductor?', choices: ['Pure water', 'Salty water', 'Oil', 'Honey'], answer: 1, explanation: 'Dissolved salt ions carry electric charge through water.', acCode: 'AC9S6U02' },
  { id: 'up-s-14', q: 'The skeleton helps the body by:', choices: ['Storing oxygen for tissue respiration', 'Providing structure and protecting organs', 'Digesting food in the stomach and gut', 'Pumping blood throughout the body'], answer: 1, explanation: 'Bones support the body and protect vital organs like the brain and heart.', acCode: 'AC9S4U01' },
  { id: 'up-s-15', q: 'A magnet most strongly attracts:', choices: ['Plastic', 'Glass', 'Iron', 'Wood'], answer: 2, explanation: 'Ferromagnetic metals like iron, nickel and cobalt respond to magnets.', acCode: 'AC9S4U02' },
  { id: 'up-s-16', q: 'Evaporation is when:', choices: ['Liquid turns to gas', 'Gas turns to liquid', 'Solid turns to liquid', 'Solid turns to gas'], answer: 0, explanation: 'Evaporation moves water from oceans, lakes and puddles into the air as vapour.', acCode: 'AC9S6U02' },
  { id: 'up-s-17', q: 'A food chain shows:', choices: ['How animals breed', 'Who eats what in an ecosystem', 'How plants grow', 'What weather is coming'], answer: 1, explanation: 'Food chains trace energy from the sun through plants, herbivores and carnivores.', acCode: 'AC9S5U01' },
  { id: 'up-s-18', q: 'Which is renewable energy?', choices: ['Coal', 'Oil', 'Solar', 'Natural gas'], answer: 2, explanation: 'Solar power comes from sunlight, which won’t run out on human timescales.', acCode: 'AC9S6U03' },
  { id: 'up-s-19', q: 'The water cycle includes:', choices: ['Rainfall alone, no other processes', 'Evaporation, condensation and precipitation', 'Ocean water alone, no atmosphere involved', 'River flow with no other processes'], answer: 1, explanation: 'Water moves between oceans, atmosphere and land in a continuous cycle.', acCode: 'AC9S4U03' },
  { id: 'up-s-20', q: 'Volcanic rock that has cooled is called:', choices: ['Sedimentary', 'Igneous', 'Metamorphic', 'Limestone'], answer: 1, explanation: 'Igneous rocks form from cooling magma or lava.', acCode: 'AC9S6U03' },
  { id: 'up-s-21', q: 'The heart’s main job is to:', choices: ['Digest food', 'Pump blood around the body', 'Filter air', 'Store fat'], answer: 1, explanation: 'The heart pumps oxygen-rich blood to every cell.', acCode: 'AC9S4U01' },
  { id: 'up-s-22', q: 'A solar eclipse happens when:', choices: ['The Sun sets', 'The Moon blocks the Sun', 'Earth’s shadow covers the Moon', 'It is night'], answer: 1, explanation: 'During a solar eclipse the Moon passes between Earth and the Sun.', acCode: 'AC9S5U03' },
  { id: 'up-s-23', q: 'Adaptations help an animal:', choices: ['Look pretty only', 'Survive in its environment', 'Live forever', 'Speak human'], answer: 1, explanation: 'Adaptations are features that improve survival — camels store fat, polar bears have thick fur.', acCode: 'AC9S5U01' },
  { id: 'up-s-24', q: 'Which Australian animal is a marsupial?', choices: ['Emu', 'Crocodile', 'Kangaroo', 'Goanna'], answer: 2, explanation: 'Marsupials raise young in a pouch — kangaroos are iconic Australian marsupials.', acCode: 'AC9S5U01' },
  { id: 'up-s-25', q: 'Light travels faster than:', choices: ['Sound', 'Other light', 'Rockets', 'Itself'], answer: 0, explanation: 'That’s why you see lightning before you hear thunder.', acCode: 'AC9S5U02' },
];

