const Y10_MATHS: MCQ[] = [
  // -- Topic 1: Surds and Measurement (1–42) --
  { id: 'y10-math-1', q: 'Which of these is an IRRATIONAL number?', choices: ['1/3', '0.5', '√7', '−4'], answer: 2, explanation: 'An irrational number cannot be expressed as a fraction of integers; √7 has a non-terminating, non-repeating decimal.' },
  { id: 'y10-math-2', q: '√16 is best classified as:', choices: ['rational', 'irrational', 'a surd', 'imaginary'], answer: 0, explanation: '√16 = 4, a rational number. NOT every square root is irrational — only those of non-perfect-square positive integers.' },
  { id: 'y10-math-3', q: 'A SURD is best defined as:', choices: ['Any decimal number', 'An irrational root that cannot simplify to a rational number', 'A negative number', 'Any number under a square-root sign'], answer: 1, explanation: 'A surd is specifically an irrational root (like √2, √3). √9 is NOT a surd because it simplifies to 3 (rational).' },
  { id: 'y10-math-4', q: 'The set {1/3, √4, 0.125, −2} consists of:', choices: ['Entirely rational numbers', 'Entirely irrational numbers', 'A mix of rational and irrational', 'No real numbers'], answer: 0, explanation: '1/3 = rational, √4 = 2, 0.125 = 1/8, −2 = rational. All four are rational.' },
  { id: 'y10-math-5', q: '√50 fully simplified is:', choices: ['5√2', '2√5', '10', '√50 (already simplified)'], answer: 0, explanation: '50 = 25 × 2, so √50 = √25 × √2 = 5√2. Pull out the largest square factor.' },
  { id: 'y10-math-6', q: '√72 fully simplified is:', choices: ['8√3', '6√2', '2√18', '9√2'], answer: 1, explanation: '72 = 36 × 2, so √72 = 6√2. The 2√18 form is incomplete — 18 still has a square factor.' },
  { id: 'y10-math-7', q: '√45 fully simplified is:', choices: ['3√5', '5√3', '9√5', '15'], answer: 0, explanation: '45 = 9 × 5, so √45 = 3√5.' },
  { id: 'y10-math-8', q: '√32 fully simplified is:', choices: ['2√8', '4√2', '8√2', '16√2'], answer: 1, explanation: '32 = 16 × 2, so √32 = 4√2. The 2√8 form is incomplete — 8 = 4 × 2.' },
  { id: 'y10-math-9', q: '√18 fully simplified is:', choices: ['2√9', '3√2', '6√3', '9√2'], answer: 1, explanation: '18 = 9 × 2, so √18 = 3√2.' },
  { id: 'y10-math-10', q: '√24 fully simplified is:', choices: ['2√6', '4√3', '√24', '6√2'], answer: 0, explanation: '24 = 4 × 6, so √24 = 2√6. The number 6 has no further square factors.' },
  { id: 'y10-math-11', q: '2√3 + 5√3 simplifies to:', choices: ['7√6', '7√3', '10√3', '7√9'], answer: 1, explanation: 'Like surds: add coefficients (2 + 5 = 7), keep the surd unchanged.' },
  { id: 'y10-math-12', q: '4√5 − √5 simplifies to:', choices: ['3√5', '4', '4√0', '3'], answer: 0, explanation: 'Like surds: 4√5 − 1√5 = 3√5. Common error: dropping the √5.' },
  { id: 'y10-math-13', q: '3√2 + √8 simplifies to:', choices: ['3√10', '4√10', '5√2', '4√2'], answer: 2, explanation: 'Simplify √8 first: √8 = 2√2. Then 3√2 + 2√2 = 5√2. Common error: combining under one radical.' },
  { id: 'y10-math-14', q: 'Which sum CANNOT be combined into a single like-surd term?', choices: ['2√3 + 5√3', '√8 + 3√2', '√20 + √45', '4√7 + 3√11'], answer: 3, explanation: '√7 and √11 are unlike surds and remain separate. The first three all reduce to like surds after simplification.' },
  { id: 'y10-math-15', q: '√3 × √12 simplifies to:', choices: ['√36', '6', '3√4', '√15'], answer: 1, explanation: '√3 × √12 = √36 = 6. The product √a × √b = √(a×b).' },
  { id: 'y10-math-16', q: '√20 ÷ √5 simplifies to:', choices: ['2', '4', '√4', '√15'], answer: 0, explanation: '√20 ÷ √5 = √(20/5) = √4 = 2.' },
  { id: 'y10-math-17', q: '√7 × √7 equals:', choices: ['√14', '14', '7', '√49'], answer: 2, explanation: 'A surd multiplied by itself produces the original radicand: √a × √a = a. So √7 × √7 = 7.' },
  { id: 'y10-math-18', q: 'Expand: √2(√6 + √8)', choices: ['√12 + √16', '√14', '2√3 + 4', '2√12'], answer: 2, explanation: '√2 × √6 = √12 = 2√3; √2 × √8 = √16 = 4. So √2(√6 + √8) = 2√3 + 4.' },
  { id: 'y10-math-19', q: 'To rationalise 1/√3, multiply top and bottom by:', choices: ['1/√3', '√3', '3', 'Nothing, since it is already rational'], answer: 1, explanation: 'Multiplying numerator and denominator by √3 gives √3/3, with a rational denominator.' },
  { id: 'y10-math-20', q: '5/√2 rationalised is:', choices: ['5√2/2', '5/2', '5√2', '√10'], answer: 0, explanation: 'Multiply top and bottom by √2: (5 × √2)/(√2 × √2) = 5√2/2.' },
  { id: 'y10-math-21', q: '6/√3 rationalised and simplified is:', choices: ['2√3', '6√3/3', '6/3', '√18'], answer: 0, explanation: '6/√3 × √3/√3 = 6√3/3 = 2√3.' },
  { id: 'y10-math-22', q: 'A right triangle has legs 6 and 8. The hypotenuse is:', choices: ['10', '14', '√10', '√48'], answer: 0, explanation: '6² + 8² = 36 + 64 = 100. √100 = 10 (the 6-8-10 triple).' },
  { id: 'y10-math-23', q: 'A right triangle has hypotenuse 13 and one leg 5. The other leg is:', choices: ['8', '12', '18', '√194'], answer: 1, explanation: '13² − 5² = 169 − 25 = 144. √144 = 12 (the 5-12-13 triple).' },
  { id: 'y10-math-24', q: 'A right triangle has legs 4 and 5. The hypotenuse, in exact form, is:', choices: ['9', '√9', '√41', '3√5'], answer: 2, explanation: '4² + 5² = 16 + 25 = 41. Since 41 is prime, √41 stays in exact form.' },
  { id: 'y10-math-25', q: 'A rectangular box has dimensions 3 × 4 × 12. The longest internal (space) diagonal is:', choices: ['13', '√13', '√25', '19'], answer: 0, explanation: 'Diagonal² = 3² + 4² + 12² = 9 + 16 + 144 = 169. √169 = 13.' },
  { id: 'y10-math-26', q: 'When applying Pythagoras\' theorem, the HYPOTENUSE is:', choices: ['The shortest side', 'The side opposite the right angle', 'Always horizontal in any diagram', 'Always labelled c by convention'], answer: 1, explanation: 'The hypotenuse is opposite the right angle and is always the longest side. Position and label can vary.' },
  { id: 'y10-math-27', q: 'A rectangle measures 15 cm by 8 cm. Its area is:', choices: ['46 cm²', '120 cm²', '120 cm', '60 cm²'], answer: 1, explanation: 'Area = length × width = 15 × 8 = 120 cm². Units must be squared.' },
  { id: 'y10-math-28', q: 'An L-shape is made by removing a 3 × 3 square from one corner of a 10 × 8 rectangle. Its area is:', choices: ['71 cm²', '80 cm²', '89 cm²', '63 cm²'], answer: 0, explanation: 'Original area 10 × 8 = 80; subtract the removed 3 × 3 = 9; 80 − 9 = 71 cm².' },
  { id: 'y10-math-29', q: 'A circle has radius 7 cm. Its area, to 2 dp, is:', choices: ['43.98 cm²', '153.94 cm²', '21.99 cm²', '49 cm²'], answer: 1, explanation: 'A = πr² = π × 49 ≈ 153.94 cm². Common error: using diameter or computing circumference.' },
  { id: 'y10-math-30', q: 'Perimeter, area and volume use which units respectively?', choices: ['Linear, squared, cubic', 'Linear for all three', 'Squared for all three', 'Cubic, squared, linear'], answer: 0, explanation: 'Perimeter is a length (cm), area is squared (cm²), volume is cubic (cm³). Mixing them up is a common error.' },
  { id: 'y10-math-31', q: 'A cube has edge length 5 cm. Its total surface area is:', choices: ['25 cm²', '125 cm²', '150 cm²', '100 cm²'], answer: 2, explanation: 'A cube has 6 faces, each 5 × 5 = 25 cm². Total = 6 × 25 = 150 cm². The 125 cm² answer is the volume.' },
  { id: 'y10-math-32', q: 'A closed cylinder has radius 3 and height 10. Its total surface area is:', choices: ['60π', '78π', '90π', '30π'], answer: 1, explanation: 'TSA = 2πr² + 2πrh = 18π + 60π = 78π.' },
  { id: 'y10-math-33', q: 'For a cone with base radius 5 and slant height 13, the lateral (curved) surface area is:', choices: ['65π', '25π', '13π', '195π'], answer: 0, explanation: 'Lateral SA of a cone = πrℓ, where ℓ is the slant height. So π × 5 × 13 = 65π. Common error: using vertical height instead of slant.' },
  { id: 'y10-math-34', q: 'The "slant height" of a cone refers to:', choices: ['The vertical height from base centre to apex', 'The distance from apex to any point on the base edge', 'Half the base diameter', 'The base radius itself'], answer: 1, explanation: 'Slant height ℓ is measured along the slope. Vertical height h is straight down from apex to base centre. Pythagoras links them: ℓ² = h² + r².' },
  { id: 'y10-math-35', q: 'A sphere has radius 6. Its surface area is:', choices: ['36π', '144π', '288π', '24π'], answer: 1, explanation: 'SA = 4πr² = 4π × 36 = 144π. Common error: using πr² (the formula for circle area).' },
  { id: 'y10-math-36', q: 'A cylinder has radius 4 and height 10. Its volume is:', choices: ['40π', '80π', '160π', '120π'], answer: 2, explanation: 'V = πr²h = π × 16 × 10 = 160π.' },
  { id: 'y10-math-37', q: 'A cone has radius 6 and vertical height 9. Its volume is:', choices: ['108π', '54π', '162π', '36π'], answer: 0, explanation: 'V = ⅓πr²h = ⅓ × π × 36 × 9 = 108π. The ⅓ factor distinguishes cone from cylinder.' },
  { id: 'y10-math-38', q: 'A sphere has radius 3. Its volume is:', choices: ['36π', '12π', '108π', '27π'], answer: 0, explanation: 'V = (4/3)πr³ = (4/3) × π × 27 = 36π.' },
  { id: 'y10-math-39', q: 'A cone and a cylinder share the same base radius and height. The ratio of cone volume to cylinder volume is:', choices: ['1 : 1', '1 : 2', '1 : 3', '2 : 3'], answer: 2, explanation: 'Cone volume = ⅓ × cylinder volume when base and height match — the ⅓ factor in V = ⅓πr²h.' },
  { id: 'y10-math-40', q: 'An ice-cream is modelled as a cone of vertical height 10 cm topped by a hemisphere, both with radius 3 cm. Its total volume is:', choices: ['30π + 9π', '30π + 18π', '90π + 9π', '90π + 18π'], answer: 1, explanation: 'Cone: ⅓π × 9 × 10 = 30π. Hemisphere: ½ × (4/3)π × 27 = 18π. Total = 48π.' },
  { id: 'y10-math-41', q: '1 m² equals how many cm²?', choices: ['100', '1 000', '10 000', '1 000 000'], answer: 2, explanation: '1 m = 100 cm, so 1 m² = (100)² = 10 000 cm². Simply doubling the linear conversion (100) is a classic error.' },
  { id: 'y10-math-42', q: '1 m³ equals how many cm³?', choices: ['1 000', '10 000', '100 000', '1 000 000'], answer: 3, explanation: '1 m = 100 cm, so 1 m³ = (100)³ = 1 000 000 cm³. Mixing this up with area conversion (10 000) is common.' },

  // -- Topic 2: Algebra, Equations and Linear Relationships (43–84) --
  { id: 'y10-math-43', q: 'Combine like terms: 3a + 5b − a + 2b', choices: ['2a + 7b', '3a + 7b', '4a + 7b', '2a + 3b'], answer: 0, explanation: '3a − a = 2a; 5b + 2b = 7b.' },
  { id: 'y10-math-44', q: 'Expand: −3(2x − 5)', choices: ['−6x − 15', '−6x + 15', '6x − 15', '6x + 15'], answer: 1, explanation: '−3 × 2x = −6x; −3 × (−5) = +15. Mishandling the negative is a common error.' },
  { id: 'y10-math-45', q: 'Factorise: 6x + 9', choices: ['3(2x + 3)', '2(3x + 9)', '6(x + 9)', '3x(2 + 3)'], answer: 0, explanation: 'HCF = 3; 6x + 9 = 3(2x + 3).' },
  { id: 'y10-math-46', q: 'Factorise: 12y² − 8y', choices: ['4y(3y − 2)', '4(3y² − 2y)', '2y(6y − 4)', '8y(y − 1)'], answer: 0, explanation: 'HCF = 4y; 12y² − 8y = 4y(3y − 2). Always pull out the GREATEST common factor.' },
  { id: 'y10-math-47', q: 'Evaluate 2x² + 3x when x = −2', choices: ['−2', '−14', '14', '2'], answer: 3, explanation: '2(−2)² + 3(−2) = 2(4) − 6 = 8 − 6 = 2.' },
  { id: 'y10-math-48', q: 'Substitute h = 5, b = 8 into A = ½bh', choices: ['20', '40', '13', '6.5'], answer: 0, explanation: 'A = ½ × 8 × 5 = 20.' },
  { id: 'y10-math-49', q: 'Solve: 3x + 7 = 22', choices: ['3', '5', '7', '15'], answer: 1, explanation: '3x = 15; x = 5.' },
  { id: 'y10-math-50', q: 'Solve: 2(x − 3) = 14', choices: ['4', '7', '10', '17/2'], answer: 2, explanation: 'Expand: 2x − 6 = 14; 2x = 20; x = 10.' },
  { id: 'y10-math-51', q: 'Solve: 5x − 8 = 2x + 7', choices: ['1/3', '5', '3', '15'], answer: 1, explanation: '3x = 15; x = 5.' },
  { id: 'y10-math-52', q: 'Solve: (x + 4)/3 = 6', choices: ['2', '14', '18', '22'], answer: 1, explanation: 'Multiply both sides by 3: x + 4 = 18; x = 14.' },
  { id: 'y10-math-53', q: 'Solve: x/2 + x/3 = 10', choices: ['10', '12', '15', '6'], answer: 1, explanation: 'Common denominator 6: 3x/6 + 2x/6 = 10 → 5x/6 = 10 → x = 12.' },
  { id: 'y10-math-54', q: 'Solve: 4 − 2x = 10', choices: ['−3', '3', '7', '−7'], answer: 0, explanation: '−2x = 6; x = −3. Mishandling the negative coefficient is common.' },
  { id: 'y10-math-55', q: 'Solve: 5 − 2x > 1', choices: ['x < 2', 'x > 2', 'x < 3', 'x > 3'], answer: 0, explanation: '−2x > −4; divide by −2 and FLIP the inequality: x < 2.' },
  { id: 'y10-math-56', q: 'On a number line, x ≥ −3 is shown by:', choices: ['Open circle at −3, arrow left', 'Open circle at −3, arrow right', 'Closed circle at −3, arrow left', 'Closed circle at −3, arrow right'], answer: 3, explanation: '≥ means "or equal" → closed circle. Greater means arrow to the right.' },
  { id: 'y10-math-57', q: 'Solve: 3x + 5 ≤ 14', choices: ['x ≤ 3', 'x ≥ 3', 'x ≤ 19/3', 'x ≥ 19/3'], answer: 0, explanation: '3x ≤ 9; x ≤ 3. Dividing by positive 3 keeps the inequality direction.' },
  { id: 'y10-math-58', q: 'Solve: 7 − 3x < 1', choices: ['x > 2', 'x < 2', 'x > −2', 'x < −2'], answer: 0, explanation: '−3x < −6; divide by −3 and FLIP: x > 2.' },
  { id: 'y10-math-59', q: 'Simplify: x/4 + x/6', choices: ['x/10', '2x/10', '5x/12', '5x/24'], answer: 2, explanation: 'LCD = 12: 3x/12 + 2x/12 = 5x/12.' },
  { id: 'y10-math-60', q: 'Simplify: 2/x − 1/(2x)', choices: ['1/(2x)', '3/(2x)', '1/x', '1/(2x²)'], answer: 1, explanation: 'LCD = 2x: 4/(2x) − 1/(2x) = 3/(2x).' },
  { id: 'y10-math-61', q: 'Simplify: (3a)/(2b) × (4b)/(9a)', choices: ['12/18', '2/3', '12ab/18ab', '6/9'], answer: 1, explanation: 'Multiply numerators and denominators, then cancel: (12ab)/(18ab) = 2/3.' },
  { id: 'y10-math-62', q: 'The y-intercept of y = 3x − 7 is:', choices: ['3', '−7', '7', '7/3'], answer: 1, explanation: 'In y = mx + c, c is the y-intercept. Here c = −7.' },
  { id: 'y10-math-63', q: 'The gradient of y = −4x + 2 is:', choices: ['−4', '2', '4', '−1/4'], answer: 0, explanation: 'In y = mx + c, m is the gradient. Here m = −4.' },
  { id: 'y10-math-64', q: 'The line through (1, 2) and (4, 8) has gradient:', choices: ['2', '3', '6', '−2'], answer: 0, explanation: 'm = (8 − 2)/(4 − 1) = 6/3 = 2.' },
  { id: 'y10-math-65', q: 'The line through (−1, 5) and (3, −3) has gradient:', choices: ['2', '−2', '1/2', '−1/2'], answer: 1, explanation: 'm = (−3 − 5)/(3 − (−1)) = −8/4 = −2.' },
  { id: 'y10-math-66', q: 'The x-intercept of y = 2x − 6 is at:', choices: ['x = −6', 'x = 3', 'x = 6', 'x = −3'], answer: 1, explanation: 'Set y = 0: 0 = 2x − 6 → x = 3.' },
  { id: 'y10-math-67', q: 'Which equation describes a HORIZONTAL line through (4, 5)?', choices: ['x = 4', 'y = 5', 'y = x', 'y = 4x + 5'], answer: 1, explanation: 'A horizontal line has constant y. Through (4, 5) → y = 5.' },
  { id: 'y10-math-68', q: 'Which equation describes a VERTICAL line through (3, 7)?', choices: ['x = 3', 'y = 7', 'y = 3x + 7', 'x = 7'], answer: 0, explanation: 'A vertical line has constant x. Through (3, 7) → x = 3.' },
  { id: 'y10-math-69', q: 'The midpoint of (2, 4) and (8, 10) is:', choices: ['(10, 14)', '(6, 6)', '(5, 7)', '(3, 3)'], answer: 2, explanation: 'Midpoint = average of coordinates: ((2+8)/2, (4+10)/2) = (5, 7).' },
  { id: 'y10-math-70', q: 'The distance from (1, 2) to (4, 6) is:', choices: ['3', '4', '5', '√17'], answer: 2, explanation: 'd = √((4−1)² + (6−2)²) = √(9 + 16) = √25 = 5.' },
  { id: 'y10-math-71', q: 'The distance between (0, 0) and (6, 8) is:', choices: ['10', '14', '√14', '√100'], answer: 0, explanation: 'd = √(36 + 64) = √100 = 10.' },
  { id: 'y10-math-72', q: 'The lines y = 2x + 3 and y = 2x − 5 are:', choices: ['Parallel', 'Perpendicular', 'Intersecting at one point', 'The same line'], answer: 0, explanation: 'Same gradient (2), different y-intercept → parallel and never meet.' },
  { id: 'y10-math-73', q: 'Which line is PERPENDICULAR to y = (1/3)x + 1?', choices: ['y = (1/3)x − 1', 'y = −(1/3)x + 1', 'y = 3x + 5', 'y = −3x + 5'], answer: 3, explanation: 'Perpendicular gradients multiply to −1. (1/3) × (−3) = −1.' },
  { id: 'y10-math-74', q: 'The lines y = 4x + 1 and y = −4x + 7 are:', choices: ['Parallel and never intersect', 'Perpendicular at exactly one point', 'Intersecting once but not perpendicular', 'Identical (the same line everywhere)'], answer: 2, explanation: 'Different gradients → not parallel. Product of gradients = −16 ≠ −1 → not perpendicular. Just regular intersecting lines.' },
  { id: 'y10-math-75', q: 'A line is parallel to y = 5x − 2 and passes through (0, 7). Its equation is:', choices: ['y = 5x + 7', 'y = 5x − 7', 'y = −5x + 7', 'y = 7x + 5'], answer: 0, explanation: 'Parallel → same gradient (5). y-intercept is 7. So y = 5x + 7.' },
  { id: 'y10-math-76', q: 'Solve simultaneously: y = 2x + 1 and y = x + 4', choices: ['(3, 7)', '(2, 5)', '(1, 3)', '(4, 9)'], answer: 0, explanation: 'Substitute: 2x + 1 = x + 4 → x = 3; y = 7.' },
  { id: 'y10-math-77', q: 'Solve simultaneously: x + y = 10 and x − y = 4', choices: ['(7, 3)', '(5, 5)', '(6, 4)', '(3, 7)'], answer: 0, explanation: 'Add the equations: 2x = 14 → x = 7; then y = 3.' },
  { id: 'y10-math-78', q: 'When solving by elimination, multiplying one equation by a constant is done to:', choices: ['Save time on the arithmetic', 'Match coefficients so a variable cancels when added or subtracted', 'Convert decimals to integers', 'Eliminate the right-hand side'], answer: 1, explanation: 'Elimination requires matching coefficients in one variable so they cancel when combined.' },
  { id: 'y10-math-79', q: 'Two numbers sum to 30 and differ by 8. The SMALLER number is:', choices: ['11', '19', '15', '22'], answer: 0, explanation: 'x + y = 30, x − y = 8 → 2x = 38, x = 19; y = 11. The smaller is 11.' },
  { id: 'y10-math-80', q: 'A line with a NEGATIVE gradient goes:', choices: ['Upward from left to right', 'Downward from left to right', 'Horizontally', 'Vertically'], answer: 1, explanation: 'Negative gradient means y decreases as x increases — the line falls from left to right.' },
  { id: 'y10-math-81', q: 'Gradient is defined as:', choices: ['Run over rise', 'Rise over run', 'Run minus rise', 'Rise plus run'], answer: 1, explanation: 'Gradient = vertical change ÷ horizontal change = rise/run. Inverting the formula is a classic error.' },
  { id: 'y10-math-82', q: 'PARALLEL lines have:', choices: ['Equal gradients', 'Negative reciprocal gradients', 'Opposite y-intercepts', 'Equal y-intercepts'], answer: 0, explanation: 'Parallel → equal gradients. Negative reciprocal applies to perpendicular lines.' },
  { id: 'y10-math-83', q: 'PERPENDICULAR lines have gradients that:', choices: ['Are equal', 'Multiply to give −1 (negative reciprocals)', 'Have equal y-intercepts', 'Differ in sign'], answer: 1, explanation: 'Perpendicular gradients satisfy m₁ × m₂ = −1.' },
  { id: 'y10-math-84', q: 'When dividing both sides of an inequality by −5, the inequality sign:', choices: ['Stays the same', 'Reverses direction', 'Becomes an equation', 'Doubles'], answer: 1, explanation: 'Multiplying or dividing by a negative reverses the inequality direction.' },

  // -- Topic 3: Quadratic Expressions and Equations (85–122) --
  { id: 'y10-math-85', q: 'Expand: (x + 3)(x + 5)', choices: ['x² + 8x + 15', 'x² + 15x + 8', 'x² + 8x + 8', 'x² + 15'], answer: 0, explanation: 'FOIL: x² + 5x + 3x + 15 = x² + 8x + 15.' },
  { id: 'y10-math-86', q: 'Expand: (x − 4)²', choices: ['x² − 16', 'x² + 16', 'x² − 8x + 16', 'x² − 4x − 16'], answer: 2, explanation: '(a − b)² = a² − 2ab + b² = x² − 8x + 16. Forgetting the middle term −8x is a classic error.' },
  { id: 'y10-math-87', q: 'Expand: (2x + 3)(2x − 3)', choices: ['4x² − 9', '4x² + 9', '4x² + 6x − 9', '2x² − 6'], answer: 0, explanation: 'Difference of two squares: (a + b)(a − b) = a² − b². So (2x)² − 3² = 4x² − 9.' },
  { id: 'y10-math-88', q: 'Expand: (3x − 2)²', choices: ['9x² − 4', '9x² + 4', '9x² − 12x + 4', '9x² − 6x + 4'], answer: 2, explanation: '(3x)² − 2(3x)(2) + 2² = 9x² − 12x + 4.' },
  { id: 'y10-math-89', q: 'Expand: (x + 7)(x − 2)', choices: ['x² + 5x − 14', 'x² − 5x − 14', 'x² + 9x − 14', 'x² + 14'], answer: 0, explanation: 'x² − 2x + 7x − 14 = x² + 5x − 14.' },
  { id: 'y10-math-90', q: 'The correct expansion of (a + b)² is:', choices: ['a² + b²', 'a² + ab + b²', 'a² + 2ab + b²', 'a² + 2b'], answer: 2, explanation: 'The middle term 2ab is essential. Treating (a+b)² as a² + b² is a very common error.' },
  { id: 'y10-math-91', q: 'Factorise: x² + 7x + 12', choices: ['(x + 3)(x + 4)', '(x + 2)(x + 6)', '(x + 1)(x + 12)', '(x − 3)(x − 4)'], answer: 0, explanation: 'Two numbers multiplying to 12 and summing to 7: 3 and 4.' },
  { id: 'y10-math-92', q: 'Factorise: x² − 5x + 6', choices: ['(x − 1)(x − 6)', '(x − 2)(x − 3)', '(x + 2)(x + 3)', '(x − 1)(x + 6)'], answer: 1, explanation: 'Two numbers multiplying to +6 and summing to −5: −2 and −3.' },
  { id: 'y10-math-93', q: 'Factorise: x² + x − 12', choices: ['(x + 4)(x − 3)', '(x − 4)(x + 3)', '(x − 6)(x + 2)', '(x + 6)(x − 2)'], answer: 0, explanation: 'Product −12, sum +1: +4 and −3.' },
  { id: 'y10-math-94', q: 'Factorise: x² − 9', choices: ['(x − 3)(x − 3)', '(x + 3)(x + 3)', '(x − 3)(x + 3)', 'Cannot factor over integers'], answer: 2, explanation: 'Difference of two squares: x² − a² = (x − a)(x + a).' },
  { id: 'y10-math-95', q: 'Factorise: 4x² − 25', choices: ['(2x − 5)²', '(4x − 5)(x + 5)', '(2x − 5)(2x + 5)', 'Cannot factor over integers'], answer: 2, explanation: 'Difference of two squares: (2x)² − 5² = (2x − 5)(2x + 5).' },
  { id: 'y10-math-96', q: 'Factorise: 2x² + 6x', choices: ['2(x² + 3)', 'x(2x + 6)', '2x(x + 3)', '(2x)(x + 6)'], answer: 2, explanation: 'HCF = 2x; 2x² + 6x = 2x(x + 3). Always take out the greatest common factor.' },
  { id: 'y10-math-97', q: 'Factorise: 6x² − 11x − 10', choices: ['(2x + 1)(3x − 10)', '(3x + 2)(2x − 5)', '(6x − 1)(x + 10)', '(2x − 5)(3x − 2)'], answer: 1, explanation: 'Find factors of 6 × (−10) = −60 summing to −11: 4 and −15. Split: 6x² + 4x − 15x − 10, then group.' },
  { id: 'y10-math-98', q: 'Factorise: 3x² + 10x + 8', choices: ['(x + 2)(3x + 4)', '(3x + 2)(x + 4)', '(x + 8)(3x + 1)', '(3x − 2)(x − 4)'], answer: 0, explanation: 'Product 24, sum 10: 4 and 6. 3x² + 4x + 6x + 8 = x(3x + 4) + 2(3x + 4) = (x + 2)(3x + 4).' },
  { id: 'y10-math-99', q: 'Factorise by grouping: 2x² + 6x + 3xy + 9y', choices: ['(2x + 3y)(x + 3)', '(2x + 3)(x + y)', '(2x + 3y)(x − 3)', '(2x − 3y)(x + 3)'], answer: 0, explanation: 'Group: 2x(x + 3) + 3y(x + 3) = (x + 3)(2x + 3y).' },
  { id: 'y10-math-100', q: 'To complete the square on x² + 8x, you must add:', choices: ['4', '8', '16', '64'], answer: 2, explanation: 'Half of 8 is 4, squared is 16. Then x² + 8x + 16 = (x + 4)².' },
  { id: 'y10-math-101', q: 'Complete the square: x² − 6x + 2', choices: ['(x − 3)² − 7', '(x − 3)² + 11', '(x + 3)² − 7', '(x − 6)² + 2'], answer: 0, explanation: 'x² − 6x = (x − 3)² − 9, so x² − 6x + 2 = (x − 3)² − 7.' },
  { id: 'y10-math-102', q: 'Which quadratic CANNOT be factorised over the integers?', choices: ['x² + 4', 'x² − 4', 'x² + 4x', 'x² + 4x + 4'], answer: 0, explanation: 'x² + 4 is a SUM of squares with no real roots. The others factor as (x − 2)(x + 2), x(x + 4), and (x + 2)² respectively.' },
  { id: 'y10-math-103', q: 'The Null Factor Law states that if a × b = 0, then:', choices: ['Both a and b must equal zero', 'At least one of a or b equals zero', 'a − b = 0', 'Both must be non-zero'], answer: 1, explanation: 'At least one factor must be zero. Both being zero is also possible but not required.' },
  { id: 'y10-math-104', q: 'Solve: (x − 3)(x + 5) = 0', choices: ['x = 3 or x = 5', 'x = −3 or x = 5', 'x = 3 or x = −5', 'x = −3 or x = −5'], answer: 2, explanation: 'Apply Null Factor Law: x − 3 = 0 → x = 3; or x + 5 = 0 → x = −5.' },
  { id: 'y10-math-105', q: 'Solve: x² − 5x + 6 = 0', choices: ['x = 2 or x = 3', 'x = −2 or x = −3', 'x = 1 or x = 6', 'x = 5 or x = 6'], answer: 0, explanation: 'Factor: (x − 2)(x − 3) = 0; x = 2 or x = 3.' },
  { id: 'y10-math-106', q: 'The DISCRIMINANT of ax² + bx + c is:', choices: ['b² + 4ac', 'b² − 4ac', '−b ± 4ac', '(b² − 4ac)/(2a)'], answer: 1, explanation: 'Discriminant Δ = b² − 4ac — the part under the square root in the quadratic formula.' },
  { id: 'y10-math-107', q: 'If the discriminant is POSITIVE, the quadratic has:', choices: ['No real solutions', 'One real solution', 'Two distinct real solutions', 'Complex solutions only'], answer: 2, explanation: 'Δ > 0 → two distinct real roots.' },
  { id: 'y10-math-108', q: 'If the discriminant is ZERO, the quadratic has:', choices: ['No real solutions', 'One real solution (repeated)', 'Two distinct real solutions', 'Infinitely many solutions'], answer: 1, explanation: 'Δ = 0 → one repeated real root (a perfect-square trinomial).' },
  { id: 'y10-math-109', q: 'If the discriminant is NEGATIVE, the quadratic has:', choices: ['Two distinct real solutions', 'One real solution', 'No real solutions', 'A negative root'], answer: 2, explanation: 'Δ < 0 → no real solutions (complex roots in Y10/10A is extension).' },
  { id: 'y10-math-110', q: 'Solve using the quadratic formula: x² + 3x − 4 = 0', choices: ['x = 1 or x = −4', 'x = −1 or x = 4', 'x = 4 or x = −1', 'x = 1 or x = 4'], answer: 0, explanation: 'a=1, b=3, c=−4. Δ = 9 + 16 = 25. x = (−3 ± 5)/2 = 1 or −4.' },
  { id: 'y10-math-111', q: 'Solve: 2x² + 5x − 3 = 0', choices: ['x = 3 or x = −1/2', 'x = −3 or x = 1/2', 'x = 1 or x = −3', 'x = −1 or x = 3/2'], answer: 1, explanation: 'Factor (2x − 1)(x + 3) = 0 → x = 1/2 or x = −3.' },
  { id: 'y10-math-112', q: 'A rectangle has area 24 m² with length 2 m greater than width. The width w satisfies:', choices: ['w² + 2w = 24', 'w² − 2w + 24 = 0', 'w(w + 2) = 12', '2w² = 24'], answer: 0, explanation: 'Length = w + 2; area = w(w + 2) = w² + 2w = 24.' },
  { id: 'y10-math-113', q: 'A ball thrown upward has height h = 20t − 5t². It returns to the ground (h = 0) at t =', choices: ['0 only', '4', '0 and 4', '5'], answer: 2, explanation: 'Factor: 5t(4 − t) = 0 → t = 0 (launch) or t = 4 seconds (landing). Both are mathematical solutions.' },
  { id: 'y10-math-114', q: 'In a quadratic length problem, a negative root is typically:', choices: ['Accepted as a valid length', 'Doubled to make it positive', 'Rejected because lengths cannot be negative', 'Added to the positive root'], answer: 2, explanation: 'Contextual rejection: physical lengths must be positive, so negative algebraic solutions are excluded.' },
  { id: 'y10-math-115', q: 'Solve: x² = 16', choices: ['x = 4', 'x = ±4', 'x = ±2', 'x = 8'], answer: 1, explanation: 'Two square roots: x = ±√16 = ±4. Forgetting the negative root is common.' },
  { id: 'y10-math-116', q: 'Solve: (x + 1)² = 25', choices: ['x = 4', 'x = −4 or x = 6', 'x = 4 or x = −6', 'x = ±5'], answer: 2, explanation: 'x + 1 = ±5; x = 4 or x = −6.' },
  { id: 'y10-math-117', q: 'Before applying the Null Factor Law, the equation must be:', choices: ['In standard form (ax² + bx + c)', 'Set equal to zero on one side', 'Solved by the quadratic formula', 'Divided by x'], answer: 1, explanation: 'NFL requires a product equal to zero. Applying it to ab = c (c ≠ 0) is invalid.' },
  { id: 'y10-math-118', q: 'When expanding a binomial square (a + b)², the result is:', choices: ['a² + b²', 'a² + 2ab + b²', 'a² + ab + b²', '(a + b) × 2'], answer: 1, explanation: 'Do NOT forget the middle term 2ab. The "(a+b)² = a² + b²" error is among the most common in algebra.' },
  { id: 'y10-math-119', q: 'Before factorising x² + 6x + 9, you should:', choices: ['Check for a common factor first', 'Apply the quadratic formula immediately', 'Move everything to one side', 'Take the square root of both sides'], answer: 0, explanation: 'HCF first (here HCF = 1). Then recognise (x + 3)².' },
  { id: 'y10-math-120', q: 'A quadratic equation has solutions x = 2 and x = −5. Its factorised form is:', choices: ['(x − 2)(x + 5) = 0', '(x + 2)(x − 5) = 0', '(x − 2)(x − 5) = 0', '(x + 2)(x + 5) = 0'], answer: 0, explanation: 'Roots r → factors (x − r). So (x − 2)(x − (−5)) = (x − 2)(x + 5).' },
  { id: 'y10-math-121', q: 'For x² − 4x + k to have EXACTLY ONE real solution, k =', choices: ['0', '2', '4', '16'], answer: 2, explanation: 'Δ = 16 − 4k = 0 → k = 4. Then x² − 4x + 4 = (x − 2)².' },
  { id: 'y10-math-122', q: 'For x² + bx + 9 to have TWO real solutions, b must satisfy:', choices: ['b² > 36', 'b² < 36', 'b > 6', 'b < 0'], answer: 0, explanation: 'Δ = b² − 36 > 0 → b² > 36, i.e. b > 6 or b < −6.' },

  // -- Topic 4: Probability and Counting Techniques (123–150) --
  { id: 'y10-math-123', q: 'The probability of a CERTAIN event is:', choices: ['0', '1', '∞', 'Any value between 0 and 1'], answer: 1, explanation: 'Certain → P = 1; impossible → P = 0; all probabilities are between 0 and 1 inclusive.' },
  { id: 'y10-math-124', q: 'For MUTUALLY EXCLUSIVE events A and B, P(A or B) equals:', choices: ['P(A) + P(B)', 'P(A) × P(B)', 'P(A) + P(B) − P(A and B)', 'P(A) − P(B)'], answer: 0, explanation: 'Mutually exclusive → no overlap → P(A ∩ B) = 0, so P(A ∪ B) = P(A) + P(B).' },
  { id: 'y10-math-125', q: 'For events that CAN overlap, P(A or B) equals:', choices: ['P(A) + P(B)', 'P(A) + P(B) − P(A and B)', 'P(A) × P(B)', 'P(A) − P(B)'], answer: 1, explanation: 'The addition rule subtracts the overlap to avoid double-counting.' },
  { id: 'y10-math-126', q: 'In a Venn diagram, A ∩ B represents:', choices: ['Everything in A', 'Everything in B', 'Elements in BOTH A and B', 'Elements not in A'], answer: 2, explanation: 'Intersection = overlap = elements common to both sets.' },
  { id: 'y10-math-127', q: 'The complement of event A (written A′) means:', choices: ['The same as A', 'Everything not in A', 'A ∩ B', 'A ∪ B'], answer: 1, explanation: 'P(A′) = 1 − P(A); the complement is everything outside A in the sample space.' },
  { id: 'y10-math-128', q: 'In a two-way table, the column totals must equal:', choices: ['Zero', 'The grand total', 'The row totals individually', 'The probabilities directly'], answer: 1, explanation: 'Column totals and row totals both sum to the grand total — same data, partitioned differently.' },
  { id: 'y10-math-129', q: 'P(A | B) reads as:', choices: ['A intersect B', 'Probability of A given B', 'A and B together', 'A unioned with B'], answer: 1, explanation: 'The vertical bar means "given that". Conditional probability restricts the sample space to B.' },
  { id: 'y10-math-130', q: 'P(A | B) is calculated by:', choices: ['P(A) × P(B)', 'P(A ∩ B) / P(B)', 'P(A) − P(B)', 'P(A) + P(B)'], answer: 1, explanation: 'Condition on B → restrict the sample space to B, so divide the joint probability by P(B).' },
  { id: 'y10-math-131', q: 'A bag has 3 red and 5 blue marbles. P(red) is:', choices: ['3/5', '3/8', '5/8', '1/3'], answer: 1, explanation: 'Favourable/total = 3/(3+5) = 3/8.' },
  { id: 'y10-math-132', q: 'A fair coin is tossed twice. P(two heads) is:', choices: ['1/2', '1/4', '1/3', '2/4'], answer: 1, explanation: 'Independent: P(H) × P(H) = 1/2 × 1/2 = 1/4.' },
  { id: 'y10-math-133', q: 'A fair die is rolled. P(number greater than 4) is:', choices: ['1/3', '1/6', '2/6', '4/6'], answer: 0, explanation: 'Numbers > 4 are {5, 6}; 2/6 = 1/3.' },
  { id: 'y10-math-134', q: 'Two events are INDEPENDENT if:', choices: ['One occurring affects the probability of the other', 'One occurring does NOT affect the probability of the other', 'They have equal probability', 'They are mutually exclusive'], answer: 1, explanation: 'Independent → P(A ∩ B) = P(A) × P(B); knowing one event gives no info about the other.' },
  { id: 'y10-math-135', q: 'Drawing two cards WITHOUT replacement makes the two draws:', choices: ['Independent', 'Dependent', 'Mutually exclusive', 'Equally likely'], answer: 1, explanation: 'The first card removed changes the second-draw sample space, creating dependence.' },
  { id: 'y10-math-136', q: 'Drawing two cards WITH replacement makes the two draws:', choices: ['Independent', 'Dependent', 'Mutually exclusive', 'Always the same value'], answer: 0, explanation: 'Replacing restores the original sample space; subsequent draws are independent.' },
  { id: 'y10-math-137', q: 'From 100 surveyed: 60 like maths, 40 like science, 25 like both. P(maths or science) is:', choices: ['1.00', '0.75', '0.50', '0.85'], answer: 1, explanation: '60 + 40 − 25 = 75 like at least one; P = 75/100 = 0.75. The overlap must be subtracted.' },
  { id: 'y10-math-138', q: 'A bag has 4 red and 6 blue. Two drawn WITHOUT replacement. P(two red) is:', choices: ['16/100', '12/90', '12/100', '4/10'], answer: 1, explanation: 'P(red then red) = (4/10) × (3/9) = 12/90 = 2/15.' },
  { id: 'y10-math-139', q: 'A bag has 4 red and 6 blue. Two drawn WITH replacement. P(two red) is:', choices: ['16/100', '12/90', '16/90', '8/100'], answer: 0, explanation: 'With replacement: (4/10) × (4/10) = 16/100 = 4/25.' },
  { id: 'y10-math-140', q: 'A tree diagram is most useful for:', choices: ['Single events', 'Sequential probability experiments', 'Continuous data', 'Independent surveys'], answer: 1, explanation: 'Tree diagrams expand sequential outcomes branch by branch (two-step or three-step experiments).' },
  { id: 'y10-math-141', q: 'Two coins flipped. The sample space contains how many outcomes?', choices: ['2', '3', '4', '6'], answer: 2, explanation: '{HH, HT, TH, TT} = 4 outcomes.' },
  { id: 'y10-math-142', q: 'P(at least one head) when two coins are flipped is:', choices: ['1/4', '1/2', '3/4', '1'], answer: 2, explanation: 'P(at least one H) = 1 − P(no H) = 1 − P(TT) = 1 − 1/4 = 3/4.' },
  { id: 'y10-math-143', q: 'A class has 12 boys and 18 girls. P(boy) is:', choices: ['12/18', '12/30', '18/30', '12/100'], answer: 1, explanation: 'Total = 30; P(boy) = 12/30 = 2/5.' },
  { id: 'y10-math-144', q: 'In a deck of 52, P(heart OR king) is:', choices: ['13/52', '4/52', '16/52', '17/52'], answer: 2, explanation: '13 hearts + 4 kings − 1 king of hearts (overlap) = 16. P = 16/52 = 4/13.' },
  { id: 'y10-math-145', q: '"Given that A occurred" tells you to:', choices: ['Use the full sample space', 'Restrict the sample space to A', 'Multiply by P(A)', 'Ignore A entirely'], answer: 1, explanation: 'Conditional probability restricts the sample space to the conditioning event.' },
  { id: 'y10-math-146', q: 'Two events A and B with P(A ∩ B) ≠ P(A) × P(B) are:', choices: ['Independent', 'Dependent', 'Mutually exclusive', 'Equally likely'], answer: 1, explanation: 'Independence requires P(A ∩ B) = P(A) × P(B). Failure of equality means dependence.' },
  { id: 'y10-math-147', q: 'Confusing AND with OR leads students to compute:', choices: ['P(A) + P(B) for joint events instead of P(A) × P(B)', 'P(A) − P(B) instead of P(A)', 'The complement instead of the event', 'The conditional instead of the joint'], answer: 0, explanation: 'AND = intersection (multiply for independent); OR = union (add with overlap correction).' },
  { id: 'y10-math-148', q: 'A meal has 3 entree choices and 4 main choices. Total meal combinations:', choices: ['7', '12', '34', '64'], answer: 1, explanation: 'Multiplication principle: 3 × 4 = 12 for independent choices.' },
  { id: 'y10-math-149', q: 'The number of ways to arrange 5 distinct books on a shelf is:', choices: ['5', '25', '120', '5! / 2!'], answer: 2, explanation: '5! = 5 × 4 × 3 × 2 × 1 = 120.' },
  { id: 'y10-math-150', q: 'Adding probabilities of overlapping events without subtracting the overlap leads to:', choices: ['Probabilities less than 0', 'Probabilities greater than 1', 'No effect', 'A correct answer'], answer: 1, explanation: 'Double-counting the overlap inflates the total above 1, which signals the error.' },

  // -- Topic 5: Parabolas and Rates of Change (151–182) --
  { id: 'y10-math-151', q: 'The graph of y = x² is called a:', choices: ['Line', 'Parabola', 'Circle', 'Hyperbola'], answer: 1, explanation: 'y = ax² + bx + c (a ≠ 0) graphs as a parabola.' },
  { id: 'y10-math-152', q: 'In y = (x − 2)² + 3, the turning point is:', choices: ['(2, 3)', '(−2, 3)', '(2, −3)', '(−2, −3)'], answer: 0, explanation: 'Turning-point form y = (x − h)² + k has vertex (h, k).' },
  { id: 'y10-math-153', q: 'The axis of symmetry of y = (x + 4)² − 1 is:', choices: ['x = 4', 'x = −4', 'x = 1', 'x = −1'], answer: 1, explanation: 'The axis passes through the turning point at x = h. Here h = −4.' },
  { id: 'y10-math-154', q: 'The y-intercept of y = x² − 6x + 5 is:', choices: ['1', '5', '−5', '−6'], answer: 1, explanation: 'Set x = 0: y = 5.' },
  { id: 'y10-math-155', q: 'The x-intercepts of y = (x − 2)(x + 5) are:', choices: ['x = 2 and x = 5', 'x = −2 and x = 5', 'x = 2 and x = −5', 'x = −2 and x = −5'], answer: 2, explanation: 'Set y = 0; each factor equals zero at x = 2 and x = −5.' },
  { id: 'y10-math-156', q: 'A negative coefficient of x² makes a parabola:', choices: ['Wider', 'Narrower', 'Concave up (opens upward)', 'Concave down (opens downward)'], answer: 3, explanation: 'a < 0 → the parabola opens downward.' },
  { id: 'y10-math-157', q: 'In y = 2(x − 1)² + 4, the turning point is:', choices: ['(1, 4)', '(−1, 4)', '(2, 4)', '(1, −4)'], answer: 0, explanation: 'Vertex form (h, k) = (1, 4). The 2 is the dilation factor.' },
  { id: 'y10-math-158', q: 'The parabola y = x² − 4 has x-intercepts at:', choices: ['x = 0 only', 'x = ±2', 'x = ±4', 'No x-intercepts'], answer: 1, explanation: '0 = x² − 4 → x² = 4 → x = ±2.' },
  { id: 'y10-math-159', q: 'The number of x-intercepts of y = x² + 1 is:', choices: ['0', '1', '2', 'Cannot determine'], answer: 0, explanation: 'Discriminant = 0 − 4 = −4 < 0, so no real roots.' },
  { id: 'y10-math-160', q: 'The number of x-intercepts of y = x² − 6x + 9 is:', choices: ['0', '1 (a repeated root)', '2', 'Infinite'], answer: 1, explanation: 'y = (x − 3)² touches the x-axis at x = 3 only. Δ = 0.' },
  { id: 'y10-math-161', q: 'The parabola y = (x − 3)² has:', choices: ['Two x-intercepts', 'No x-intercepts', 'One x-intercept (a touch point)', 'Three x-intercepts'], answer: 2, explanation: 'Vertex at (3, 0); the parabola touches the x-axis at exactly one point.' },
  { id: 'y10-math-162', q: 'To translate y = x² UP 3 units and RIGHT 2 units, the equation becomes:', choices: ['y = (x − 2)² + 3', 'y = (x + 2)² + 3', 'y = (x − 3)² + 2', 'y = (x + 3)² + 2'], answer: 0, explanation: 'Right shift → (x − h); up shift → + k.' },
  { id: 'y10-math-163', q: 'Reflecting y = x² in the x-axis gives:', choices: ['y = −x²', 'y = x² + 1', 'y = (−x)²', 'y = x³'], answer: 0, explanation: 'Reflection in the x-axis multiplies y by −1.' },
  { id: 'y10-math-164', q: 'The dilation factor in y = 3(x − 1)² is:', choices: ['1', '3', '−1', '0'], answer: 1, explanation: 'The coefficient of (x − 1)² is the vertical dilation. |a| > 1 → narrower.' },
  { id: 'y10-math-165', q: 'Find the turning point of y = x² − 8x + 11 by completing the square:', choices: ['(4, −5)', '(−4, −5)', '(4, 5)', '(8, 11)'], answer: 0, explanation: 'y = (x − 4)² + 11 − 16 = (x − 4)² − 5. Vertex (4, −5).' },
  { id: 'y10-math-166', q: 'The x-intercepts of y = x² + 5x + 6 are:', choices: ['x = 2 and x = 3', 'x = −2 and x = −3', 'x = 2 and x = −3', 'x = −2 and x = 3'], answer: 1, explanation: 'Factor: (x + 2)(x + 3); roots at −2 and −3.' },
  { id: 'y10-math-167', q: 'A line y = mx + c can intersect a parabola at:', choices: ['Always twice', '0, 1, or 2 points', 'Always once', 'Always 3 points'], answer: 1, explanation: 'Substituting and solving gives a quadratic. Δ determines the count: 2 / 1 (tangent) / 0.' },
  { id: 'y10-math-168', q: 'The line y = 3 intersects y = x² at:', choices: ['No points', 'One point', 'Two points', 'Three points'], answer: 2, explanation: 'x² = 3 → x = ±√3 → two intersection points.' },
  { id: 'y10-math-169', q: 'The line y = −4 intersects y = x² at:', choices: ['No points', 'One point', 'Two points', 'Three points'], answer: 0, explanation: 'x² = −4 has no real solution.' },
  { id: 'y10-math-170', q: 'Rate of change is best interpreted as:', choices: ['A constant value across the graph', 'The gradient of the graph', 'The y-intercept', 'The vertex location'], answer: 1, explanation: 'Rate of change = slope of the graph at the point of interest.' },
  { id: 'y10-math-171', q: 'On a distance-time graph, a steeper slope indicates:', choices: ['Less time elapsed', 'Greater speed', 'Less speed', 'A change in direction'], answer: 1, explanation: 'Steeper slope = larger rate of change of distance over time = greater speed.' },
  { id: 'y10-math-172', q: 'A horizontal segment on a distance-time graph means the object is:', choices: ['Moving fastest', 'Stopped', 'Reversing', 'Accelerating'], answer: 1, explanation: 'Zero gradient = no change in distance with time = stopped.' },
  { id: 'y10-math-173', q: 'Average rate of change of a function between two points is:', choices: ['The instantaneous slope at one point', 'The slope of the secant line through both points', 'Always zero', 'The y-intercept of the secant'], answer: 1, explanation: 'Average ROC = Δy / Δx — the secant slope.' },
  { id: 'y10-math-174', q: 'Instantaneous rate of change at a point is:', choices: ['Average ROC over a long interval', 'The slope of the tangent at that point', 'Always larger than average ROC', 'The same as average ROC'], answer: 1, explanation: 'Instantaneous ROC corresponds to the tangent line at the point.' },
  { id: 'y10-math-175', q: 'A distance-time graph that goes UP then DOWN represents an object that:', choices: ['Moves up and down vertically', 'Moves forward, then returns to the start', 'Stops and starts repeatedly', 'Speeds up then slows'], answer: 1, explanation: 'The y-axis is distance FROM START. Up = moving away; down = returning. NOT a picture of the path.' },
  { id: 'y10-math-176', q: 'A parabolic projectile reaches its maximum height when its (instantaneous) rate of change of height is:', choices: ['Maximum', 'Zero', 'Negative', 'Constant'], answer: 1, explanation: 'At the vertex (max height), the tangent is horizontal — instantaneous ROC of height is 0.' },
  { id: 'y10-math-177', q: 'y = −(x − 3)² + 5 has:', choices: ['Minimum value 5 at x = 3', 'Maximum value 5 at x = 3', 'Minimum value 3 at x = 5', 'Maximum value 3 at x = 5'], answer: 1, explanation: 'a < 0 → opens downward → vertex is a maximum at (3, 5).' },
  { id: 'y10-math-178', q: 'The graph of y = (x + 1)(x − 5) opens:', choices: ['Upward', 'Downward', 'Sideways', 'Cannot determine'], answer: 0, explanation: 'Expanded: y = x² − 4x − 5. Coefficient of x² is 1 > 0 → opens upward.' },
  { id: 'y10-math-179', q: 'A parabola with x-intercepts at 1 and 7 has axis of symmetry at:', choices: ['x = 1', 'x = 4', 'x = 7', 'x = 8'], answer: 1, explanation: 'The axis is the midpoint of the x-intercepts: (1 + 7)/2 = 4.' },
  { id: 'y10-math-180', q: 'The x-intercept of a graph is where:', choices: ['x equals 0', 'y equals 0', 'Both x and y are zero', 'Either x or y is 1'], answer: 1, explanation: 'x-intercept = where the graph crosses the x-axis = where y = 0.' },
  { id: 'y10-math-181', q: 'For y = x² − 6x + 8, the y-coordinate of the turning point is:', choices: ['−1', '0', '8', '−6'], answer: 0, explanation: 'Complete the square: y = (x − 3)² − 1. Vertex y = −1.' },
  { id: 'y10-math-182', q: 'For h(t) = −5t² + 20t modelling a ball\'s height, maximum height occurs at t =', choices: ['1', '2', '4', '5'], answer: 1, explanation: 'Vertex at t = −b/(2a) = −20/(−10) = 2. Maximum height at t = 2 seconds.' },

  // -- Topic 6: Statistics (183–214) --
  { id: 'y10-math-183', q: 'The MEDIAN of an ordered data set is the:', choices: ['Mean of all values', 'Middle value', 'Most common value', 'Difference between max and min'], answer: 1, explanation: 'Median = middle value once data is sorted.' },
  { id: 'y10-math-184', q: 'The MODE is the:', choices: ['Arithmetic mean of all values', 'Middle value of sorted data', 'Most frequently occurring value', 'Difference between max and min'], answer: 2, explanation: 'Mode = highest-frequency value (or values). The other options describe mean, median and range respectively.' },
  { id: 'y10-math-185', q: 'The RANGE of {3, 7, 12, 4, 9} is:', choices: ['9', '7', '12', '5'], answer: 0, explanation: 'Max (12) − min (3) = 9.' },
  { id: 'y10-math-186', q: 'The five-number summary contains:', choices: ['Mean, mode, median, max, min', 'Min, Q1, median, Q3, max', 'Min, mean, mode, median, max', 'Q1, median, Q3, range, IQR'], answer: 1, explanation: 'Five-number summary = minimum, lower quartile (Q1), median, upper quartile (Q3), maximum.' },
  { id: 'y10-math-187', q: 'The interquartile range (IQR) is:', choices: ['Q3 − Q1', 'Q3 + Q1', 'max − min', 'median − mode'], answer: 0, explanation: 'IQR = Q3 − Q1; measures spread of the middle 50%.' },
  { id: 'y10-math-188', q: 'For ordered data {2, 4, 6, 8, 10}, the median is:', choices: ['5', '6', '7', '8'], answer: 1, explanation: 'Middle of 5 values is the 3rd = 6.' },
  { id: 'y10-math-189', q: 'For ordered data {1, 3, 5, 7, 9, 11, 13, 15}, Q1 is:', choices: ['3', '4', '5', '6'], answer: 1, explanation: 'Lower half is {1, 3, 5, 7}; median of lower half = (3 + 5)/2 = 4.' },
  { id: 'y10-math-190', q: 'A box plot displays:', choices: ['Mean, mode, and range', 'The five-number summary', 'The standard deviation by itself', 'A frequency table'], answer: 1, explanation: 'Box = Q1 to Q3; line inside = median; whiskers reach min and max (excluding outliers).' },
  { id: 'y10-math-191', q: 'The middle box of a box plot represents:', choices: ['The mean and range', 'The lower 25% of data', 'The middle 50% of data', 'The total range'], answer: 2, explanation: 'Box covers Q1 to Q3 = middle 50% = the IQR.' },
  { id: 'y10-math-192', q: 'A standard outlier is defined as a value:', choices: ['Larger than the mean', 'More than 1.5 × IQR below Q1 or above Q3', 'Equal to the median', 'Smaller than Q1'], answer: 1, explanation: 'Standard rule: outliers fall outside [Q1 − 1.5×IQR, Q3 + 1.5×IQR].' },
  { id: 'y10-math-193', q: 'Comparing two data sets, a LARGER IQR means:', choices: ['More data values', 'Less spread', 'More spread in the middle 50%', 'A higher mean'], answer: 2, explanation: 'A wider IQR → the middle 50% of the data is more spread out.' },
  { id: 'y10-math-194', q: 'Standard deviation measures:', choices: ['The mean of the data', 'Average spread of data about the mean', 'The median', 'The mode'], answer: 1, explanation: 'SD is a measure of spread; small SD → data clustered tightly near the mean.' },
  { id: 'y10-math-195', q: 'A SMALL standard deviation indicates:', choices: ['Data tightly clustered about the mean', 'Data spread far from the mean', 'A small mean value', 'A small range only'], answer: 0, explanation: 'Small SD → low variability → data near the mean.' },
  { id: 'y10-math-196', q: 'A SMALL SD does NOT necessarily indicate:', choices: ['Data clusters tightly about the mean', 'A small mean', 'Low variability', 'Consistent values'], answer: 1, explanation: 'SD describes spread, not magnitude. Data could cluster tightly around any mean.' },
  { id: 'y10-math-197', q: 'The mean of {4, 6, 8, 12, 20} is:', choices: ['8', '10', '12', '14'], answer: 1, explanation: 'Sum = 50; ÷ 5 = 10.' },
  { id: 'y10-math-198', q: 'BIVARIATE data involves:', choices: ['One variable', 'Two variables measured for each observation', 'Three or more variables', 'A frequency table'], answer: 1, explanation: 'Bivariate = two variables (x and y) per observation.' },
  { id: 'y10-math-199', q: 'A scatter plot is used to:', choices: ['Display single-variable data', 'Display bivariate data', 'Show probability outcomes', 'Sort data'], answer: 1, explanation: 'Scatter plots show each observation as an (x, y) point — bivariate data.' },
  { id: 'y10-math-200', q: 'A strong POSITIVE correlation between X and Y means:', choices: ['As X increases, Y increases', 'As X increases, Y decreases', 'X and Y are unrelated', 'X equals Y'], answer: 0, explanation: 'Positive correlation → both rise together. Strong → tight scatter about a line.' },
  { id: 'y10-math-201', q: 'A correlation coefficient near 0 indicates:', choices: ['Strong positive correlation', 'Strong negative correlation', 'Weak or no LINEAR correlation', 'Perfect correlation'], answer: 2, explanation: 'Near 0 = no clear linear pattern. Could still have a non-linear relationship.' },
  { id: 'y10-math-202', q: 'Three features describing a correlation are:', choices: ['Strength, direction, linearity', 'Mean, median, mode', 'Range, IQR, SD', 'Max, min, sample size'], answer: 0, explanation: 'Description requires strength (strong/weak), direction (positive/negative), and linearity.' },
  { id: 'y10-math-203', q: 'A line of best fit is used to:', choices: ['Connect the first and last data points', 'Model the trend of bivariate data', 'Mark every data point', 'Replace the scatter plot'], answer: 1, explanation: 'A line of best fit models the linear trend, minimising residual error.' },
  { id: 'y10-math-204', q: 'Using a line of best fit to predict WITHIN the data range is called:', choices: ['Interpolation', 'Extrapolation', 'Inference', 'Estimation'], answer: 0, explanation: 'Interpolation: predictions inside the data range are generally more reliable.' },
  { id: 'y10-math-205', q: 'Using a line of best fit to predict OUTSIDE the data range is called:', choices: ['Interpolation', 'Extrapolation', 'Substitution', 'Reflection'], answer: 1, explanation: 'Extrapolation: less reliable because the linear model may not hold beyond the data.' },
  { id: 'y10-math-206', q: 'Strong correlation between X and Y proves:', choices: ['X causes Y', 'X and Y are independent', 'X and Y are related, but causation is not proven', 'X equals Y'], answer: 2, explanation: 'Correlation ≠ causation. Confounding variables may explain the link.' },
  { id: 'y10-math-207', q: 'An outlier on a scatter plot:', choices: ['Should always be removed', 'May indicate an error or a special case worth investigating', 'Means the entire data set is unusable', 'Has no effect on the line of best fit'], answer: 1, explanation: 'Outliers can be legitimate or errors — investigate first. They DO affect the line of best fit.' },
  { id: 'y10-math-208', q: 'A taller box on a box plot means:', choices: ['There is more data overall', 'Data is more spread in the middle 50%', 'The mean is larger', 'There are more outliers'], answer: 1, explanation: 'Box height/width reflects IQR — middle 50% spread, NOT the count.' },
  { id: 'y10-math-209', q: 'Quartiles are calculated:', choices: ['Before sorting the data', 'After sorting the data', 'From the mode', 'From the mean'], answer: 1, explanation: 'Quartiles require ordered data. Computing from unsorted data is a classic error.' },
  { id: 'y10-math-210', q: 'For data {2, 5, 5, 7, 8, 9, 12, 15, 18, 22}, the median is:', choices: ['7', '8', '8.5', '9'], answer: 2, explanation: 'Even count of 10: median = (5th + 6th)/2 = (8 + 9)/2 = 8.5.' },
  { id: 'y10-math-211', q: 'The IQR for {2, 5, 5, 7, 8, 9, 12, 15, 18, 22} is:', choices: ['10', '7.5', '20', '9'], answer: 0, explanation: 'Q1 = 5 (lower half median), Q3 = 15 (upper half median). IQR = 15 − 5 = 10.' },
  { id: 'y10-math-212', q: 'The MEAN is more affected by outliers than the:', choices: ['Range', 'IQR', 'Standard deviation', 'Maximum'], answer: 1, explanation: 'IQR uses only the middle 50% of data → resistant to outliers. Mean uses all values → sensitive.' },
  { id: 'y10-math-213', q: 'A statistical claim is most reliable when:', choices: ['It is based on a small sample', 'The sample is representative and methodology is transparent', 'It supports the desired conclusion', 'It uses only mean values'], answer: 1, explanation: 'Representative sampling + clear methodology → defensible claims. Sample size and bias matter.' },
  { id: 'y10-math-214', q: 'Two-way tables for CATEGORICAL data show:', choices: ['Continuous trends', 'Counts in each combination of categories', 'Time series', 'Lines of best fit'], answer: 1, explanation: 'Two-way tables cross-tabulate categories with counts in each cell.' },

  // -- Topic 7: Indices, Exponentials and Logarithms (215–246) --
  { id: 'y10-math-215', q: 'Index law: aᵐ × aⁿ =', choices: ['aᵐ⁺ⁿ', 'aᵐⁿ', 'aᵐ⁻ⁿ', '2aᵐ⁺ⁿ'], answer: 0, explanation: 'Same base, multiplying → add exponents.' },
  { id: 'y10-math-216', q: 'Index law: aᵐ ÷ aⁿ =', choices: ['aᵐ⁺ⁿ', 'aᵐ⁻ⁿ', 'aᵐⁿ', 'a^(m/n)'], answer: 1, explanation: 'Same base, dividing → subtract exponents.' },
  { id: 'y10-math-217', q: '(aᵐ)ⁿ =', choices: ['aᵐ⁺ⁿ', 'aᵐ⁻ⁿ', 'aᵐⁿ', 'aᵐ/aⁿ'], answer: 2, explanation: 'Power of a power → multiply exponents.' },
  { id: 'y10-math-218', q: 'For any non-zero base a, a⁰ =', choices: ['0', '1', 'a', 'Undefined'], answer: 1, explanation: 'Any non-zero base to the power 0 equals 1.' },
  { id: 'y10-math-219', q: 'a⁻ⁿ equals:', choices: ['−aⁿ', '1/aⁿ', '−1/aⁿ', 'a × (−n)'], answer: 1, explanation: 'A negative exponent represents the reciprocal of the positive power.' },
  { id: 'y10-math-220', q: '3² × 3⁴ =', choices: ['3⁶', '3⁸', '9⁶', '6²'], answer: 0, explanation: 'Same base 3, add exponents: 2 + 4 = 6.' },
  { id: 'y10-math-221', q: '2⁻³ =', choices: ['−8', '1/8', '−1/8', '−6'], answer: 1, explanation: '2⁻³ = 1/2³ = 1/8. A negative index → reciprocal, not negation.' },
  { id: 'y10-math-222', q: 'a^(1/2) is equivalent to:', choices: ['√a', 'a/2', '1/a', '2a'], answer: 0, explanation: 'A fractional index 1/n represents the nth root. Specifically 1/2 → square root.' },
  { id: 'y10-math-223', q: '8^(1/3) =', choices: ['8/3', '2', '4', '24'], answer: 1, explanation: 'Cube root of 8 = 2.' },
  { id: 'y10-math-224', q: '4^(3/2) =', choices: ['6', '8', '12', '64'], answer: 1, explanation: '(4^(1/2))³ = 2³ = 8.' },
  { id: 'y10-math-225', q: 'Solve: 2ˣ = 16', choices: ['x = 2', 'x = 4', 'x = 8', 'x = 16'], answer: 1, explanation: '16 = 2⁴ → x = 4.' },
  { id: 'y10-math-226', q: 'Solve: 3ˣ = 81', choices: ['x = 3', 'x = 4', 'x = 9', 'x = 27'], answer: 1, explanation: '81 = 3⁴ → x = 4.' },
  { id: 'y10-math-227', q: 'The graph of y = 2ˣ has:', choices: ['A horizontal asymptote at y = 0', 'A vertical asymptote at x = 0', 'A maximum at x = 0', 'No asymptote'], answer: 0, explanation: 'As x → −∞, y → 0. The line y = 0 is the horizontal asymptote.' },
  { id: 'y10-math-228', q: 'y = 2ˣ exhibits exponential:', choices: ['Growth', 'Decay', 'Linear behaviour', 'A constant value'], answer: 0, explanation: 'Base > 1 → growth. Base between 0 and 1 → decay.' },
  { id: 'y10-math-229', q: 'y = (1/2)ˣ exhibits exponential:', choices: ['Growth', 'Decay', 'A constant value', 'Linear behaviour'], answer: 1, explanation: 'Base 1/2 < 1 → decay (values shrink as x grows).' },
  { id: 'y10-math-230', q: 'The compound interest formula is:', choices: ['A = P × n × r', 'A = P + r × n', 'A = P(1 + r)ⁿ', 'A = P × (1 − r)ⁿ'], answer: 2, explanation: 'A = P(1 + r)ⁿ for compound interest at rate r per period over n periods.' },
  { id: 'y10-math-231', q: '$1000 invested at 5% pa compounded annually for 3 years grows to approximately:', choices: ['$1150', '$1157.63', '$1015', '$1500'], answer: 1, explanation: '1000 × (1.05)³ ≈ 1157.63.' },
  { id: 'y10-math-232', q: 'log₂ 8 =', choices: ['1', '2', '3', '4'], answer: 2, explanation: '2³ = 8, so log₂ 8 = 3.' },
  { id: 'y10-math-233', q: 'log₁₀ 100 =', choices: ['1', '2', '10', '100'], answer: 1, explanation: '10² = 100.' },
  { id: 'y10-math-234', q: 'For any positive base a, log_a 1 =', choices: ['0', '1', 'a', 'Undefined'], answer: 0, explanation: 'a⁰ = 1, so log_a 1 = 0 (for any positive base).' },
  { id: 'y10-math-235', q: 'log_a (xy) =', choices: ['log_a x × log_a y', 'log_a x + log_a y', 'log_a x − log_a y', '(log_a x)(log_a y)'], answer: 1, explanation: 'Log of a product = sum of the logs.' },
  { id: 'y10-math-236', q: 'log_a (x/y) =', choices: ['log_a x + log_a y', 'log_a x − log_a y', 'log_a x ÷ log_a y', 'log_a x × y'], answer: 1, explanation: 'Log of a quotient = difference of the logs.' },
  { id: 'y10-math-237', q: 'log_a (xⁿ) =', choices: ['n × log_a x', '(log_a x)ⁿ', 'log_a x + n', 'log_a (n × x)'], answer: 0, explanation: 'Log of a power: exponent moves out as a multiplier.' },
  { id: 'y10-math-238', q: 'The inverse of y = aˣ is:', choices: ['y = x^a', 'y = log_a x', 'y = √x', 'y = −aˣ'], answer: 1, explanation: 'Exponential and logarithm are inverse functions.' },
  { id: 'y10-math-239', q: 'To solve 2ˣ = 10, taking log₁₀ of both sides gives x =', choices: ['x = 10/2 by direct division', 'x = log₁₀ 10 ÷ log₁₀ 2', 'x = log₁₀ 5, since 10/2 = 5', 'x = 5 by inspection alone'], answer: 1, explanation: 'x × log₁₀ 2 = log₁₀ 10, so x = log₁₀ 10 / log₁₀ 2 ≈ 3.32.' },
  { id: 'y10-math-240', q: 'The Richter scale for earthquakes is:', choices: ['Linear', 'Logarithmic', 'Exponential', 'Quadratic'], answer: 1, explanation: 'Each Richter unit represents a 10× increase — a log scale.' },
  { id: 'y10-math-241', q: 'The pH scale is:', choices: ['Linear', 'Logarithmic', 'Exponential', 'Quadratic'], answer: 1, explanation: 'pH = −log₁₀[H⁺]. pH 5 has 10× the [H⁺] of pH 6.' },
  { id: 'y10-math-242', q: 'A negative index means:', choices: ['The number itself is negative', 'The number takes its reciprocal', 'Subtract from the base', 'The result is zero'], answer: 1, explanation: 'a⁻ⁿ = 1/aⁿ; negative index → reciprocal, NOT negation.' },
  { id: 'y10-math-243', q: 'x^(1/2) is the same as:', choices: ['x/2', '1/x²', '√x', '2x'], answer: 2, explanation: 'Fractional indices represent roots; 1/2 = square root.' },
  { id: 'y10-math-244', q: 'The logarithm of a NEGATIVE number is:', choices: ['Negative', 'Zero', 'The opposite', 'Undefined in the real numbers'], answer: 3, explanation: 'log of a negative number is not defined in the real numbers (since aˣ > 0 for positive base a).' },
  { id: 'y10-math-245', q: 'Solve log_a x = 0 (for a > 0, a ≠ 1):', choices: ['x = 0', 'x = 1', 'x = a', 'x = a²'], answer: 1, explanation: 'log_a 1 = 0 for any valid base a.' },
  { id: 'y10-math-246', q: 'A population grows by P = 100(1.05)ⁿ each year. After 10 years P is approximately:', choices: ['100', '105', '163', '1500'], answer: 2, explanation: '100 × (1.05)¹⁰ ≈ 163.' },

  // -- Topic 8: Polynomials, Functions and Graphs (247–274) --
  { id: 'y10-math-247', q: 'A function maps each input to:', choices: ['Many outputs', 'Exactly one output', 'No output', 'Two outputs'], answer: 1, explanation: 'A defining property of functions: each x in the domain has exactly one y.' },
  { id: 'y10-math-248', q: 'If f(x) = 2x + 1, then f(3) =', choices: ['5', '7', '6', '4'], answer: 1, explanation: 'f(3) = 2(3) + 1 = 7.' },
  { id: 'y10-math-249', q: 'If f(x) = x² − 4, then f(−2) =', choices: ['0', '−8', '8', '4'], answer: 0, explanation: 'f(−2) = (−2)² − 4 = 4 − 4 = 0.' },
  { id: 'y10-math-250', q: 'A polynomial of degree 3 is called:', choices: ['Linear', 'Quadratic', 'Cubic', 'Quartic'], answer: 2, explanation: 'Degree 3 → cubic. Degree 1 = linear, 2 = quadratic, 4 = quartic.' },
  { id: 'y10-math-251', q: 'The degree of p(x) = 2x⁴ − 5x² + 3 is:', choices: ['1', '2', '3', '4'], answer: 3, explanation: 'Highest exponent = 4.' },
  { id: 'y10-math-252', q: 'The leading coefficient of p(x) = −3x⁵ + x² − 7 is:', choices: ['−3', '5', '−7', '1'], answer: 0, explanation: 'Coefficient of the highest-degree term = −3.' },
  { id: 'y10-math-253', q: 'The constant term of p(x) = 4x³ − 2x + 9 is:', choices: ['4', '−2', '9', '0'], answer: 2, explanation: 'Constant = the term with no variable = 9.' },
  { id: 'y10-math-254', q: '(x² + 5x + 6) + (x² − 3x + 1) =', choices: ['2x² + 2x + 7', '2x² + 8x + 7', '2x² + 2x + 5', '2x² + 2x'], answer: 0, explanation: 'Add like terms: 2x² + (5 − 3)x + (6 + 1) = 2x² + 2x + 7.' },
  { id: 'y10-math-255', q: 'Dividing p(x) = x³ + 3x² − x − 3 by (x + 1) leaves a remainder of:', choices: ['0', '−3', '3', '−1'], answer: 0, explanation: 'By the remainder theorem: p(−1) = −1 + 3 + 1 − 3 = 0. So (x + 1) is a factor.' },
  { id: 'y10-math-256', q: 'By the remainder theorem, dividing p(x) by (x − a) leaves a remainder of:', choices: ['p(0)', 'p(a)', 'p(−a)', 'p(1)'], answer: 1, explanation: 'The remainder when p(x) is divided by (x − a) is p(a).' },
  { id: 'y10-math-257', q: 'By the factor theorem, (x − a) is a factor of p(x) when:', choices: ['p(0) = 0', 'p(a) = 0', 'p(a) = a', 'p(−a) = 0'], answer: 1, explanation: 'Factor theorem: p(a) = 0 ↔ (x − a) is a factor.' },
  { id: 'y10-math-258', q: 'Is (x − 2) a factor of p(x) = x³ − 8?', choices: ['Yes', 'No', 'Sometimes, depending on the coefficients', 'Cannot determine'], answer: 0, explanation: 'p(2) = 8 − 8 = 0 → yes, (x − 2) IS a factor.' },
  { id: 'y10-math-259', q: 'Solve x³ − x = 0', choices: ['x = 0 only', 'x = 1 only', 'x = 0, 1, −1', 'x = ±1'], answer: 2, explanation: 'Factor: x(x² − 1) = x(x − 1)(x + 1) = 0 → x = 0, 1, −1.' },
  { id: 'y10-math-260', q: 'A cubic equation can have at most how many real roots?', choices: ['1', '2', '3', '4'], answer: 2, explanation: 'Degree = the maximum number of real roots.' },
  { id: 'y10-math-261', q: 'The graph of y = x³ passes through the origin with shape:', choices: ['Upward parabola', 'Downward parabola', 'S-curve through the origin', 'Straight line'], answer: 2, explanation: 'y = x³ has point symmetry through the origin and an inflection point there.' },
  { id: 'y10-math-262', q: 'The graph of y = 1/x is called a:', choices: ['Parabola', 'Cubic', 'Hyperbola', 'Exponential'], answer: 2, explanation: 'y = 1/x is the standard rectangular hyperbola.' },
  { id: 'y10-math-263', q: 'The asymptotes of y = 1/x are:', choices: ['x = 0 and y = 0', 'x = 1 and y = 1', 'x = ±1', 'No asymptotes'], answer: 0, explanation: 'Vertical asymptote at x = 0; horizontal asymptote at y = 0.' },
  { id: 'y10-math-264', q: 'The graph of y = 1/(x − 2) has a VERTICAL asymptote at:', choices: ['x = 0', 'x = 2', 'x = −2', 'y = 2'], answer: 1, explanation: 'The denominator equals zero at x = 2.' },
  { id: 'y10-math-265', q: 'The domain of f(x) = 3x − 5 is:', choices: ['All real numbers (x ∈ ℝ)', 'Non-negative reals (x ≥ 0)', 'All reals except zero (x ≠ 0)', 'Reals greater than 5 (x > 5)'], answer: 0, explanation: 'Linear functions are defined for all real x.' },
  { id: 'y10-math-266', q: 'The domain of f(x) = 1/x is:', choices: ['All real numbers', 'x ≥ 0', 'x ≠ 0', 'x > 0'], answer: 2, explanation: 'Division by zero is undefined; x = 0 must be excluded.' },
  { id: 'y10-math-267', q: 'The graph y = (x − 2)³ + 1 is y = x³ translated:', choices: ['Right 2, up 1', 'Left 2, up 1', 'Right 2, down 1', 'Left 2, down 1'], answer: 0, explanation: '(x − h) → right h; +k → up k.' },
  { id: 'y10-math-268', q: 'f(x) is read as:', choices: ['f times x', 'f of x (the function f evaluated at x)', 'f divided by x', 'f to the power of x'], answer: 1, explanation: 'Function notation, NOT multiplication. f(x) means "the value of f at input x".' },
  { id: 'y10-math-269', q: 'For a polynomial p(x), a ROOT means:', choices: ['Where the graph turns', 'Where p(x) = 0', 'The constant term', 'The leading coefficient'], answer: 1, explanation: 'A root is a solution to p(x) = 0 — i.e. an x-intercept.' },
  { id: 'y10-math-270', q: 'A QUARTIC polynomial has degree:', choices: ['2', '3', '4', '5'], answer: 2, explanation: 'Quartic = degree 4.' },
  { id: 'y10-math-271', q: 'Multiplying (x + 2) by (x² − x + 1) gives:', choices: ['x³ + 1', 'x³ + 3x² + 2x − 2', 'x³ + x² − x + 2', 'x³ + x − 2'], answer: 2, explanation: '(x + 2)(x² − x + 1) = x³ − x² + x + 2x² − 2x + 2 = x³ + x² − x + 2.' },
  { id: 'y10-math-272', q: 'How many x-intercepts does y = x³ + 3x² − x − 3 have?', choices: ['0', '1', '2', '3'], answer: 3, explanation: 'Factor: (x + 1)(x − 1)(x + 3); three distinct real roots.' },
  { id: 'y10-math-273', q: 'The horizontal asymptote of y = 1/(x + 4) is:', choices: ['x = −4', 'y = 0', 'y = 4', 'y = −4'], answer: 1, explanation: 'As x → ±∞, 1/(x + 4) → 0.' },
  { id: 'y10-math-274', q: 'y = (x − 2)(x + 1)(x − 3) has roots at:', choices: ['x = 2, −1, 3', 'x = −2, 1, −3', 'x = 2', 'x = 0, 1, −2'], answer: 0, explanation: 'Each factor equals zero: x = 2, x = −1, x = 3.' },

  // -- Topic 9: Trigonometry (275–302) --
  { id: 'y10-math-275', q: 'sin θ equals:', choices: ['opposite / adjacent', 'opposite / hypotenuse', 'adjacent / hypotenuse', 'hypotenuse / opposite'], answer: 1, explanation: 'SOH: sin = opposite / hypotenuse.' },
  { id: 'y10-math-276', q: 'cos θ equals:', choices: ['opposite / adjacent', 'opposite / hypotenuse', 'adjacent / hypotenuse', 'hypotenuse / adjacent'], answer: 2, explanation: 'CAH: cos = adjacent / hypotenuse.' },
  { id: 'y10-math-277', q: 'tan θ equals:', choices: ['opposite / hypotenuse', 'adjacent / hypotenuse', 'opposite / adjacent', 'hypotenuse / opposite'], answer: 2, explanation: 'TOA: tan = opposite / adjacent.' },
  { id: 'y10-math-278', q: 'In a right triangle, the HYPOTENUSE is:', choices: ['The shortest side', 'The side opposite the right angle', 'Adjacent to the reference angle', 'Always vertical'], answer: 1, explanation: 'Hypotenuse is opposite the right angle — the longest side.' },
  { id: 'y10-math-279', q: 'The OPPOSITE side relative to angle θ is:', choices: ['Closest to θ', 'Across from θ', 'The hypotenuse', 'Always horizontal'], answer: 1, explanation: 'Opposite = the side directly across from the chosen angle.' },
  { id: 'y10-math-280', q: 'The ADJACENT side relative to angle θ in a right triangle is:', choices: ['Located across from the angle θ', 'The hypotenuse of the triangle', 'Adjacent to θ and not the hypotenuse', 'Twice the length of the opposite side'], answer: 2, explanation: 'Adjacent is next to θ and is NOT the hypotenuse.' },
  { id: 'y10-math-281', q: 'In a right triangle with hypotenuse 10 and angle 30°, the OPPOSITE side equals:', choices: ['5', '8.66', '10', '20'], answer: 0, explanation: 'sin 30° = 0.5 → opposite = 10 × 0.5 = 5.' },
  { id: 'y10-math-282', q: 'In a right triangle with hypotenuse 10 and angle 60°, the ADJACENT side equals:', choices: ['5', '8.66', '10', '15'], answer: 0, explanation: 'cos 60° = 0.5 → adjacent = 10 × 0.5 = 5.' },
  { id: 'y10-math-283', q: 'tan 45° equals exactly:', choices: ['1', '√2', '√3', '0.5'], answer: 0, explanation: 'In an isosceles right triangle, opposite = adjacent → tan = 1.' },
  { id: 'y10-math-284', q: 'sin 90° equals:', choices: ['0', '0.5', '1', 'Undefined'], answer: 2, explanation: 'At 90°, the "opposite" coincides with the hypotenuse → ratio = 1.' },
  { id: 'y10-math-285', q: 'cos 0° equals:', choices: ['0', '0.5', '1', 'Undefined'], answer: 2, explanation: 'At 0°, adjacent coincides with the hypotenuse → ratio = 1.' },
  { id: 'y10-math-286', q: 'To find an unknown ANGLE given two sides, you use:', choices: ['Pythagoras\' theorem', 'Inverse trig functions (sin⁻¹, cos⁻¹, tan⁻¹)', 'The quadratic formula', 'The cosine rule'], answer: 1, explanation: 'Forward trig finds sides; inverse trig finds angles.' },
  { id: 'y10-math-287', q: 'Given sin θ = 0.5, the acute angle θ is:', choices: ['30°', '45°', '60°', '90°'], answer: 0, explanation: 'sin⁻¹(0.5) = 30°.' },
  { id: 'y10-math-288', q: 'Given cos θ = 0.5, the acute angle θ is:', choices: ['30°', '45°', '60°', '90°'], answer: 2, explanation: 'cos⁻¹(0.5) = 60°.' },
  { id: 'y10-math-289', q: 'Bearings are measured from:', choices: ['East', 'South', 'North', 'The vertical line through observer'], answer: 2, explanation: 'Compass bearings are angles measured clockwise from North.' },
  { id: 'y10-math-290', q: 'A bearing of 090° corresponds to:', choices: ['North', 'East', 'South', 'West'], answer: 1, explanation: '90° clockwise from North = East.' },
  { id: 'y10-math-291', q: 'A bearing of 180° corresponds to:', choices: ['North', 'East', 'South', 'West'], answer: 2, explanation: '180° clockwise from North = South.' },
  { id: 'y10-math-292', q: 'A bearing of 270° corresponds to:', choices: ['North', 'East', 'South', 'West'], answer: 3, explanation: '270° clockwise from North = West.' },
  { id: 'y10-math-293', q: 'A ship sails on bearing 045° for 50 km. Its eastward displacement is approximately:', choices: ['25 km', '35.4 km', '50 km', '0 km'], answer: 1, explanation: 'East component = 50 × sin 45° ≈ 35.4 km.' },
  { id: 'y10-math-294', q: 'An angle of ELEVATION is measured:', choices: ['Down from the horizontal', 'Up from the horizontal', 'From the vertical', 'From the line of sight'], answer: 1, explanation: 'Elevation: the line of sight rises ABOVE horizontal toward the object.' },
  { id: 'y10-math-295', q: 'An angle of DEPRESSION is measured:', choices: ['Up from the horizontal', 'Down from the horizontal', 'From the vertical', 'From the building wall'], answer: 1, explanation: 'Depression: the line of sight falls BELOW horizontal toward the object.' },
  { id: 'y10-math-296', q: 'Tom stands 30 m from a tower. Angle of elevation to the top is 40°. The tower height is approximately:', choices: ['25.2 m', '30 m', '35.7 m', '46.6 m'], answer: 0, explanation: 'tan 40° = height / 30 → height = 30 × tan 40° ≈ 25.2 m.' },
  { id: 'y10-math-297', q: 'In 3D, a right-angled triangle inside a cuboid is formed by:', choices: ['Two adjacent faces meeting at a right angle', 'A space diagonal, an edge, and a face diagonal', 'Three perpendicular edges', 'Any three vertices'], answer: 1, explanation: 'A common 3D right triangle uses the space diagonal as hypotenuse, with an edge and a face diagonal as legs.' },
  { id: 'y10-math-298', q: 'To find the angle a space diagonal makes with the floor of a rectangular box, you use:', choices: ['cos⁻¹ of (vertical edge / space diagonal)', 'tan⁻¹ of (vertical edge / floor diagonal)', 'sin⁻¹ of (width / length)', 'Pythagoras only'], answer: 1, explanation: 'The angle is between space diagonal and floor: tan = opposite (height) / adjacent (floor diagonal).' },
  { id: 'y10-math-299', q: 'When finding an unknown ANGLE given two sides, a common student error is to:', choices: ['Use sin instead of sin⁻¹', 'Use Pythagoras\' theorem first', 'Label sides correctly', 'Use degrees mode on the calculator'], answer: 0, explanation: 'To find an angle, the INVERSE trig function (sin⁻¹) is required. Using sin without the inverse is a classic mistake.' },
  { id: 'y10-math-300', q: 'Labelling opposite and adjacent depends on:', choices: ['The orientation of the triangle in the page', 'Which acute angle is the reference angle θ', 'The hypotenuse length', 'The triangle size'], answer: 1, explanation: 'Labels are relative to the chosen reference angle — they swap when you change which acute angle you reference.' },
  { id: 'y10-math-301', q: 'The compass-bearing notation N30°E means:', choices: ['30° east of north', '30° north of east', '60° east of north', 'A bearing of 060°'], answer: 0, explanation: 'N30°E means "from North, rotate 30° toward East". This equals bearing 030°.' },
  { id: 'y10-math-302', q: 'Looking UP from observer to a kite, the relevant angle is the:', choices: ['Angle of depression', 'Angle of elevation', 'Bearing', 'Vertical interior angle'], answer: 1, explanation: 'Looking UP from horizontal → angle of elevation. Looking DOWN → angle of depression.' },
];

// ============================================================
//  Year 7 Humanities — HRS-anchored (checkpoint batch: Deep Time
//  History, y7-hum-1..44). Remaining 8 units follow after Jack's
//  calibration review. Source: HRS Canvas unit pages 2026.
// ============================================================
const Y7_HUMANITIES: MCQ[] = [
  // -- Deep Time History 1: Investigating human evolution (1–11) --
  { id: 'y7-hum-1', q: 'In the BCE/CE dating system, CE stands for:', choices: ['Common Era', 'Century Era', 'Central Era', 'Counted Era'], answer: 0, explanation: 'CE = Common Era, BCE = Before Common Era — the same years as AD/BC with non-religious labels.' },
  { id: 'y7-hum-2', q: 'Which of these dates is the OLDEST?', choices: ['100 CE', '500 BCE', '200 BCE', '2000 CE'], answer: 1, explanation: 'BCE dates count backwards — the bigger the BCE number, the earlier the date.' },
  { id: 'y7-hum-3', q: 'The year 350 BCE is the same year as:', choices: ['350 AD', '350 CE', '350 BC', '1350 BP'], answer: 2, explanation: 'BCE/CE and BC/AD use identical numbering — only the labels differ.' },
  { id: 'y7-hum-4', q: 'The Out of Africa theory explains:', choices: ['How farming first began in Africa', 'How Africa split from other continents', 'How deserts formed across Africa', 'How modern humans spread from Africa'], answer: 3, explanation: 'It describes Homo sapiens migrating out of Africa and gradually populating other continents.' },
  { id: 'y7-hum-5', q: 'A likely reason early humans migrated out of Africa was:', choices: ['Following food sources and changing climates', 'Escaping overcrowded ancient cities', 'Searching for gold and precious metals', 'Setting up trade routes between empires'], answer: 0, explanation: 'Cities, trade routes and metalwork came much later — early migration tracked food and climate.' },
  { id: 'y7-hum-6', q: 'Walking upright on two legs is called:', choices: ['Chronology', 'Bipedalism', 'Migration', 'Evolution'], answer: 1, explanation: 'Bipedalism is one of the key traits that developed during human evolution, along with larger brains, tools and language.' },
  { id: 'y7-hum-7', q: 'Which statement about human evolution is most accurate?', choices: ['Humans evolved directly from modern chimpanzees', 'Humans appeared at the same time as the dinosaurs', 'Humans and modern apes share a common ancestor', 'Humans evolved separately on every continent'], answer: 2, explanation: 'Humans did not descend from any living ape species — both descend from a shared ancestor.' },
  { id: 'y7-hum-8', q: 'An archaeologist mainly studies the past through:', choices: ['Written government records in libraries', 'Interviews with living politicians', 'Predictions about the future', 'Physical remains such as bones, tools and buildings'], answer: 3, explanation: 'Archaeologists focus on physical remains; historians work mainly with written and oral sources.' },
  { id: 'y7-hum-9', q: 'A "hominid" is best described as:', choices: ['A human or a close human ancestor', 'An ancient sea creature', 'A type of stone tool', 'A kind of early village'], answer: 0, explanation: 'Hominids are humans and their close evolutionary ancestors and relatives.' },
  { id: 'y7-hum-10', q: 'Chronology is the skill of:', choices: ['Drawing maps of ancient cities', 'Arranging events in the order they happened', 'Translating hieroglyphics', 'Measuring rainfall'], answer: 1, explanation: 'Chronology means placing events in time order — a foundational history skill.' },
  { id: 'y7-hum-11', q: 'Which is the best example of a PRIMARY source about early humans?', choices: ['A 2024 documentary about evolution', 'A modern museum website', 'A stone tool made by early humans', 'A recent school textbook'], answer: 2, explanation: 'A primary source comes from the time studied; the tool is primary, while the other three were made recently.' },
  // -- Deep Time History 2: First Nations arrival & Deep Time units (12–24) --
  { id: 'y7-hum-12', q: '"Deep Time" history refers to:', choices: ['The history of deep ocean trenches', 'The far future of the planet', 'The history of space exploration', 'The very ancient human history of Australia'], answer: 3, explanation: 'Deep Time describes the tens of thousands of years of First Nations history in Australia.' },
  { id: 'y7-hum-13', q: 'Sahul was:', choices: ['A single landmass linking Australia, Tasmania and New Guinea', 'A famous ancient Egyptian city', 'A large river in ancient China', 'A method of dating rock layers'], answer: 0, explanation: 'When sea levels were lower, Australia, Tasmania and New Guinea joined into one landmass called Sahul.' },
  { id: 'y7-hum-14', q: 'The unit "kilo annum (ka)" means:', choices: ['One million years', 'One thousand years', 'One hundred years', 'One billion years'], answer: 1, explanation: 'Kilo annum (ka) means a thousand years; mega annum (ma) means a million years.' },
  { id: 'y7-hum-15', q: 'The unit "mega annum (ma)" means:', choices: ['One thousand years', 'One dozen years', 'One million years', 'One hundred years'], answer: 2, explanation: 'Mega annum (ma) means a million years — a thousand times larger than a kilo annum.' },
  { id: 'y7-hum-16', q: 'Radiocarbon dating works best on:', choices: ['Hard rocks such as solid granite', 'Flowing sea and river water', 'Modern factory-made plastics', 'Once-living things like bone or wood'], answer: 3, explanation: 'Radiocarbon dating measures once-living (organic) material; other methods date sediments and rock layers.' },
  { id: 'y7-hum-17', q: 'Relative dating tells us:', choices: ['Whether one thing is older or younger than another', 'The exact calendar year of an object', 'The weight of an object', 'The colour of an object'], answer: 0, explanation: 'Relative dating gives an order (older/younger); absolute dating gives an actual age or date.' },
  { id: 'y7-hum-18', q: 'Studying layers of rock and soil to order events is called:', choices: ['Geography', 'Stratigraphy', 'Biography', 'Photography'], answer: 1, explanation: 'Stratigraphy reads layers (strata) — deeper layers are usually older than those above.' },
  { id: 'y7-hum-19', q: 'The two Deep Time periods studied in the unit are the:', choices: ['Jurassic and Triassic', 'Regal and Imperial', 'Pleistocene and Holocene', 'Old and New Kingdoms'], answer: 2, explanation: 'The Pleistocene (ice age) came before the warmer Holocene of roughly the last 10,000 years.' },
  { id: 'y7-hum-20', q: 'The Holocene period covers approximately the:', choices: ['Last 100 years', 'Age of the dinosaurs', 'Next 10,000 years', 'Last 10,000 years'], answer: 3, explanation: 'The Holocene is the warm period after the last ice age — about the past 10,000 years.' },
  { id: 'y7-hum-21', q: 'What does "BP" mean in Deep Time dating?', choices: ['Before present', 'Before pyramids', 'British period', 'Beyond Pleistocene'], answer: 0, explanation: '"BP" means "before present", counting years back from the recent era in scientific dating.' },
  { id: 'y7-hum-22', q: 'Around 18,000 years ago, sea levels rose mainly because:', choices: ['The land slowly sank', 'Polar ice caps melted as the climate warmed', 'Rivers stopped flowing', 'Underwater volcanoes erupted'], answer: 1, explanation: 'Warming at the end of the ice age melted polar ice, raising the sea and flooding low-lying land.' },
  { id: 'y7-hum-23', q: 'The rising seas after the ice age caused Australia to:', choices: ['Join with Antarctica', 'Double in size', 'Lose about a quarter of its landmass', 'Split into two halves'], answer: 2, explanation: 'The inundation submerged roughly a quarter of the continent, reshaping coastlines people had lived on.' },
  { id: 'y7-hum-24', q: 'Otzi the Iceman is used in the unit as an example of:', choices: ['An ancient Egyptian pharaoh', 'A First Nations Elder', 'A modern archaeologist', 'How preserved remains reveal information about the past'], answer: 3, explanation: 'Otzi, a naturally preserved ancient body, shows how physical remains act as evidence about the past.' },
  // -- Deep Time History 3: Responses to environmental processes (25–32) --
  { id: 'y7-hum-25', q: 'How were memories of the ancient sea-level rise passed down by First Nations peoples?', choices: ['Through oral histories', 'Through printed newspapers', 'Through television', 'Through photographs'], answer: 0, explanation: 'Oral histories preserved accounts of the rising seas, later matched with scientific evidence.' },
  { id: 'y7-hum-26', q: '"Megafauna" means:', choices: ['Tiny insects', 'Giant animals of the past', 'Ancient farming tools', 'A style of rock art'], answer: 1, explanation: 'Megafauna were large animals — giant ancestors of some native species — that lived alongside early First Nations peoples.' },
  { id: 'y7-hum-27', q: 'Rock art is valuable evidence because it can show:', choices: ['The exact population of modern cities', 'How to build the pyramids', 'People living alongside now-extinct megafauna', 'The price of ancient goods'], answer: 2, explanation: 'Rock art records animals and events, including cohabitation of people with megafauna.' },
  { id: 'y7-hum-28', q: 'The Budj Bim cultural landscape shows First Nations peoples:', choices: ['Never stayed in one place', 'Did not manage the land', 'Hunted animals but grew no food', 'Built systems to farm and trap eels'], answer: 3, explanation: 'Budj Bim contains ancient aquaculture channels for trapping eels — evidence of careful land and water management.' },
  { id: 'y7-hum-29', q: 'In 2019, Budj Bim was added to the:', choices: ['UNESCO World Heritage List', 'Olympic Games program', 'Seven Wonders of the World', 'Australian film register'], answer: 0, explanation: 'Budj Bim was World Heritage listed in July 2019 — recognised, in a world first, for both natural and cultural significance.' },
  { id: 'y7-hum-30', q: 'Which statement about First Nations land use is accurate?', choices: ['They ignored the environment', 'They managed land and water sustainably over thousands of years', 'They built large factories', 'They imported all their food'], answer: 1, explanation: 'First Nations peoples developed deep knowledge of sustainable land and water management.' },
  { id: 'y7-hum-31', q: 'Scientists confirmed First Nations oral histories of the sea-level rise by:', choices: ['Ignoring the science', 'Asking overseas tourists', 'Comparing them with geological evidence', 'Guessing the dates'], answer: 2, explanation: 'Researchers matched details in the oral histories with geological evidence of ancient coastlines.' },
  { id: 'y7-hum-32', q: 'Why did the environment change so much between the Pleistocene and Holocene?', choices: ['The Sun stopped shining', 'The continents stopped moving', 'People built too many cities', 'The climate warmed, melting ice and raising seas'], answer: 3, explanation: 'Warming ended the ice age, melting ice, raising seas and reshaping Australia’s plants, animals and coastlines.' },
  // -- Deep Time History 4: Social organisation & cultural practices (33–39) --
  { id: 'y7-hum-33', q: 'A "kinship" system is best described as:', choices: ['A set of rules organising families, roles and relationships', 'A type of weapon', 'A method of dating rocks', 'A style of pottery'], answer: 0, explanation: 'Kinship organises family and social life, setting out roles and responsibilities to others.' },
  { id: 'y7-hum-34', q: 'In First Nations cultures, a "totem" is:', choices: ['A kind of house lived in by families', 'A being or symbol linking a person to Country', 'A coin used for trading goods', 'A written book of community laws'], answer: 1, explanation: 'A totem connects a person or group to a plant, animal or natural feature, carrying identity and responsibilities.' },
  { id: 'y7-hum-35', q: 'A "moiety" divides a community into:', choices: ['Ten equal trading groups', 'Age-based sports teams', 'Two complementary halves with roles and responsibilities', 'Random daily rosters'], answer: 2, explanation: 'A moiety splits a society into two halves that shape relationships, marriage and responsibilities.' },
  { id: 'y7-hum-36', q: 'The word "Country", as used by Aboriginal and Torres Strait Islander peoples, means:', choices: ['A nation with a flag and parliament', 'Farmland only', 'A capital city', 'Land, waters and everything a people is spiritually connected to'], answer: 3, explanation: 'Country includes land, waters, sky and the spiritual and cultural connections a people hold with it.' },
  { id: 'y7-hum-37', q: 'The Dreaming is best understood as:', choices: ['Creation stories and ongoing knowledge, beliefs and practices', 'Dreams people have while asleep', 'A single written book of laws', 'A yearly harvest festival'], answer: 0, explanation: 'The Dreaming refers to Creation stories and the living knowledge, beliefs and practices that shape life and Country.' },
  { id: 'y7-hum-38', q: 'Respected knowledge-holders who guide a First Nations community are called:', choices: ['Tourists', 'Elders', 'Settlers', 'Merchants'], answer: 1, explanation: 'Elders hold and pass on knowledge, lore and cultural responsibilities within the community.' },
  { id: 'y7-hum-39', q: 'Which statement about First Nations peoples is accurate?', choices: ['They were one nation with a single language', 'They arrived only 500 years ago', 'They were many diverse nations with different languages', 'They left no cultural evidence'], answer: 2, explanation: 'Aboriginal and Torres Strait Islander peoples formed hundreds of distinct nations, each with its own language and Country.' },
  // -- Deep Time History 5: Cultural heritage & preservation (40–44) --
  { id: 'y7-hum-40', q: 'The ancient remains found at Lake Mungo are important because they:', choices: ['Prove humans first lived in Europe', 'Are made of solid gold', 'Belonged to an Egyptian king', 'Are among the oldest human remains found in Australia'], answer: 3, explanation: 'Lake Mungo, in the Willandra Lakes region, revealed some of the oldest human remains in Australia.' },
  { id: 'y7-hum-41', q: 'The Willandra Lakes region was World Heritage listed in:', choices: ['1981', '2019', '1788', '1901'], answer: 0, explanation: 'The Willandra Lakes region (including Lake Mungo) has been World Heritage listed since 1981.' },
  { id: 'y7-hum-42', q: 'Returning Mungo Man’s remains to his ancestral land is called:', choices: ['Immigration', 'Repatriation', 'Federation', 'Excavation'], answer: 1, explanation: 'Repatriation is the return of ancestral remains to Country — an important matter of cultural respect.' },
  { id: 'y7-hum-43', q: 'Cultural heritage is best described as:', choices: ['Money saved in a bank', 'Technology invented this year', 'Traditions, beliefs and objects passed down through generations', 'A form of government'], answer: 2, explanation: 'Cultural heritage is the customs, knowledge, beliefs and artefacts passed from generation to generation.' },
  { id: 'y7-hum-44', q: 'Why is consulting First Nations communities important when caring for heritage sites?', choices: ['They own every museum', 'They set school timetables', 'They control the weather', 'They hold the cultural knowledge and connection to those places'], answer: 3, explanation: 'Consultation respects the cultural protocols and knowledge of the people connected to a site.' },
  // ── History Skills (y7-hum-45 to y7-hum-66) ──
  { id: 'y7-hum-45', q: 'Putting historical events in time order, from earliest to latest, is known as:', choices: ['Chronology', 'Geography', 'Democracy', 'Biology'], answer: 0, explanation: 'Chronology is the skill of ordering events in time — a foundation of historical thinking.' },
  { id: 'y7-hum-46', q: 'What is the main purpose of a timeline?', choices: ['To list the rules of a country', 'To show events in the order they happened', 'To measure the size of buildings', 'To record the weather each day'], answer: 1, explanation: 'Timelines display events in sequence, helping historians see continuity, change, cause and consequence.' },
  { id: 'y7-hum-47', q: 'Historians use a set of key concepts to investigate the past. Which is one of them?', choices: ['Multiplication and division', 'Evaporation and rainfall', 'Continuity and change', 'Supply and demand'], answer: 2, explanation: 'Continuity and change is one of the historical concepts — noticing what stayed the same and what changed over time.' },
  { id: 'y7-hum-48', q: 'The concept of "cause and consequence" helps historians explain:', choices: ['How to draw an accurate map', 'The chemical make-up of rocks', 'How to measure a coastline', 'Why events happened and what resulted from them'], answer: 3, explanation: 'Cause and consequence links why something happened to the effects it produced.' },
  { id: 'y7-hum-49', q: 'In history, "significance" refers to:', choices: ['The importance given to an event, person or site', 'The exact size of an object', 'The number of people in a city', 'The temperature of a place'], answer: 0, explanation: 'Historical significance is about how important an event, person or site is judged to be.' },
  { id: 'y7-hum-50', q: 'A historical "perspective" is:', choices: ['A type of ancient map', 'The point of view of a person from the past', 'A method of dating rocks', 'A tool for measuring angles'], answer: 1, explanation: 'Perspective is the viewpoint of people in the past, shaped by their time, culture and situation.' },
  { id: 'y7-hum-51', q: 'A primary source is best described as something:', choices: ['Written by a historian last year', 'Printed in a modern textbook', 'Made or used during the time being studied', 'Explained on a recent website'], answer: 2, explanation: 'Primary sources come from the period studied; secondary sources are made later by people studying it.' },
  { id: 'y7-hum-52', q: 'A secondary source is best described as something:', choices: ['Left behind during the event itself', 'Dug up from an ancient site', 'Written by an eyewitness at the time', 'Made later by someone studying the past'], answer: 3, explanation: 'Secondary sources interpret the past after the event; primary sources come from the time itself.' },
  { id: 'y7-hum-53', q: 'The "origin" of a source means:', choices: ['Who made it, and when and where', 'How heavy the object is', 'How many copies exist today', 'What colour the object is'], answer: 0, explanation: 'Identifying a source’s origin — its maker, date and place — helps judge how useful it is as evidence.' },
  { id: 'y7-hum-54', q: 'The "purpose" of a source means:', choices: ['The price it would sell for', 'The reason it was made', 'The material it is made from', 'The museum that stores it'], answer: 1, explanation: 'A source’s purpose — why it was created — affects what it can reliably tell us.' },
  { id: 'y7-hum-55', q: 'Why might a primary source still be unreliable?', choices: ['It is always too old to read', 'It was made after the event', 'Its creator may have been biased', 'It cannot be a written document'], answer: 2, explanation: 'Primary sources can carry bias or a particular viewpoint, so historians weigh their origin and purpose.' },
  { id: 'y7-hum-56', q: 'Which of these is a PRIMARY source about ancient Rome?', choices: ['A 2023 documentary about Rome', 'A modern history textbook', 'A recent encyclopedia entry', 'A Roman coin minted in 100 CE'], answer: 3, explanation: 'The Roman coin was made at the time; the others were produced recently and are secondary.' },
  { id: 'y7-hum-57', q: 'Which of these is a SECONDARY source?', choices: ['A biography of Julius Caesar written in 2020', 'A letter written by a Roman soldier', 'A statue carved in ancient Rome', 'A mosaic from a Roman villa'], answer: 0, explanation: 'The modern biography interprets the past; the other three are primary remains from the time.' },
  { id: 'y7-hum-58', q: 'COMA is a method historians use to:', choices: ['Draw a timeline', 'Analyse a source', 'Measure a map', 'Date a rock layer'], answer: 1, explanation: 'COMA is a source-analysis method for questioning where a source came from and why.' },
  { id: 'y7-hum-59', q: 'TEEAL is a structure used to:', choices: ['Date ancient bones', 'Read a compass bearing', 'Write a well-organised paragraph', 'Measure a river’s length'], answer: 2, explanation: 'TEEAL guides students to build a clear paragraph with a point, evidence and analysis.' },
  { id: 'y7-hum-60', q: 'Which source would best help a historian study daily life in ancient Egypt?', choices: ['A modern cartoon about Egypt', 'A recent tourist brochure', 'A present-day map of Africa', 'A tomb painting showing farming and cooking'], answer: 3, explanation: 'A tomb painting is a primary source from the time, showing real details of daily life.' },
  { id: 'y7-hum-61', q: 'Two historians can reach different conclusions from the same evidence. This idea is called:', choices: ['Contestability', 'Chronology', 'Evaporation', 'Federation'], answer: 0, explanation: 'Contestability recognises that historians can interpret the same sources in different ways.' },
  { id: 'y7-hum-62', q: 'A personal diary written during a war is best classified as a:', choices: ['Secondary source', 'Primary source', 'Modern textbook', 'Museum leaflet'], answer: 1, explanation: 'A diary written at the time is a primary source created by someone who lived through the events.' },
  { id: 'y7-hum-63', q: 'Historians use evidence from sources mainly to:', choices: ['Predict tomorrow’s weather', 'Decide school subjects', 'Support their conclusions about the past', 'Set the price of goods'], answer: 2, explanation: 'Evidence drawn from sources backs up a historian’s interpretations and inquiry questions.' },
  { id: 'y7-hum-64', q: 'Why do historians identify a source’s origin and purpose before using it?', choices: ['To decide how much it weighs', 'To find out its exact colour', 'To count how many exist', 'To judge how useful and reliable it is'], answer: 3, explanation: 'Knowing who made a source and why helps historians judge its usefulness and any bias.' },
  { id: 'y7-hum-65', q: 'The concept of "empathy" in history means:', choices: ['Understanding how people in the past thought and felt', 'Feeling sorry for old buildings', 'Memorising a list of dates', 'Copying a source word for word'], answer: 0, explanation: 'Historical empathy is understanding past people’s beliefs, values and feelings in their own context.' },
  { id: 'y7-hum-66', q: 'A good inquiry question for a historian is one that:', choices: ['Can only be answered with a guess', 'Can be investigated using evidence from sources', 'Has nothing to do with the past', 'Asks about next year’s events'], answer: 1, explanation: 'Historians frame questions that sources and evidence can actually help answer.' },
  // ── Ancient Egypt (y7-hum-67 to y7-hum-110) ──
  { id: 'y7-hum-67', q: 'A "civilisation" usually has features such as:', choices: ['A few tents and campfires', 'A single family living alone', 'Cities, government, writing and social classes', 'No rules or leaders at all'], answer: 2, explanation: 'Early civilisations shared features like cities, organised government, writing and social structure.' },
  { id: 'y7-hum-68', q: 'The historian Herodotus called Egypt "the gift of the Nile" because the river:', choices: ['Was full of gold nuggets', 'Flowed uphill to the sea', 'Never changed its water level', 'Made farming possible in a desert land'], answer: 3, explanation: 'The Nile’s water and fertile silt made farming possible in an otherwise dry desert.' },
  { id: 'y7-hum-69', q: 'The yearly flooding of the Nile was important because it:', choices: ['Left behind fertile silt for growing crops', 'Destroyed all the farmland', 'Washed away the pyramids', 'Brought freezing cold weather'], answer: 0, explanation: 'The inundation deposited rich silt on the banks, making the soil fertile for farming.' },
  { id: 'y7-hum-70', q: 'The three main periods of ancient Egyptian history were the:', choices: ['Regal, Republican and Imperial periods', 'Old, Middle and New Kingdoms', 'Pleistocene and Holocene', 'Bronze and Iron Ages'], answer: 1, explanation: 'Egyptian history is divided into the Old, Middle and New Kingdoms.' },
  { id: 'y7-hum-71', q: 'The fertile, fan-shaped area where the Nile meets the sea is called the:', choices: ['Cataract', 'Desert', 'Delta', 'Oasis'], answer: 2, explanation: 'The Nile Delta is the fertile region where the river branches out into the Mediterranean.' },
  { id: 'y7-hum-72', q: 'Ancient Egyptians made an early kind of paper from a river plant called:', choices: ['Bamboo', 'Cotton', 'Palm bark', 'Papyrus'], answer: 3, explanation: 'Papyrus reeds growing along the Nile were used to make a writing material of the same name.' },
  { id: 'y7-hum-73', q: 'At the top of ancient Egypt’s social pyramid was the:', choices: ['Pharaoh', 'Scribe', 'Artisan', 'Farmer'], answer: 0, explanation: 'The pharaoh sat at the apex of Egyptian society, above nobles, priests, scribes and workers.' },
  { id: 'y7-hum-74', q: 'A "scribe" in ancient Egypt was someone who:', choices: ['Led armies into battle', 'Could read and write records', 'Built pyramids by hand', 'Ruled as a god-king'], answer: 1, explanation: 'Scribes were trained to read and write, keeping records — a respected and powerful role.' },
  { id: 'y7-hum-75', q: 'Ancient Egyptian picture-writing is known as:', choices: ['Cuneiform', 'The alphabet', 'Hieroglyphics', 'Braille'], answer: 2, explanation: 'Hieroglyphics used pictures and symbols to represent sounds and meanings.' },
  { id: 'y7-hum-76', q: 'The Rosetta Stone was important because it helped people to:', choices: ['Build the first pyramid', 'Win the Battle of Kadesh', 'Map the whole Nile', 'Decode Egyptian hieroglyphics'], answer: 3, explanation: 'The Rosetta Stone carried the same text in several scripts, allowing hieroglyphics to be deciphered.' },
  { id: 'y7-hum-77', q: 'How much social mobility did most people in ancient Egypt have?', choices: ['Limited, but possible through roles like scribe or soldier', 'None at all, ever', 'Complete freedom to change class daily', 'Everyone was equal with no classes'], answer: 0, explanation: 'Movement between classes was limited but possible, for example through scribal training or military service.' },
  { id: 'y7-hum-78', q: 'Roughly how many gods and goddesses did ancient Egyptians worship?', choices: ['Exactly one', 'Over two thousand', 'About ten', 'None'], answer: 1, explanation: 'The Egyptian pantheon contained over 2,000 deities connected to everyday and spiritual life.' },
  { id: 'y7-hum-79', q: 'Egyptians preserved bodies through mummification mainly to:', choices: ['Make the body lighter to carry', 'Turn the body into stone', 'Prepare the person for the afterlife', 'Keep the body warm'], answer: 2, explanation: 'Mummification preserved the body so its owner could live on in the afterlife.' },
  { id: 'y7-hum-80', q: 'During mummification, certain organs were stored in:', choices: ['Papyrus scrolls', 'Clay bricks', 'Bronze shields', 'Canopic jars'], answer: 3, explanation: 'Canopic jars held organs such as the lungs, liver, stomach and intestines.' },
  { id: 'y7-hum-81', q: 'The Egyptian "Book of the Dead" was a collection of:', choices: ['Spells to help the dead reach the afterlife', 'Laws for running the country', 'Recipes for Egyptian food', 'Plans for building pyramids'], answer: 0, explanation: 'The Book of the Dead contained spells and guidance for the journey into the afterlife.' },
  { id: 'y7-hum-82', q: 'The Egyptians built pyramids mainly as:', choices: ['Palaces for pharaohs to live in', 'Tombs for pharaohs and their treasures', 'Markets for trading goods', 'Forts to defend the border'], answer: 1, explanation: 'Pyramids were monumental tombs built to house and protect a pharaoh for the afterlife.' },
  { id: 'y7-hum-83', q: 'Egyptians believed the pharaoh was:', choices: ['An ordinary elected leader', 'A foreign ambassador', 'Both a king and a living god', 'A common farmer'], answer: 2, explanation: 'Pharaohs were seen as god-kings with complete power and a duty to honour the gods and keep order.' },
  { id: 'y7-hum-84', q: 'A fast, wheeled vehicle used by Egyptians in battle was the:', choices: ['Trireme', 'Longboat', 'Catapult', 'Chariot'], answer: 3, explanation: 'War chariots gave Egyptian armies speed and mobility on the battlefield.' },
  { id: 'y7-hum-85', q: 'The Treaty of Kadesh is famous as:', choices: ['One of the world’s first known peace treaties', 'The first pyramid ever built', 'The oldest Egyptian recipe', 'A map of the Nile'], answer: 0, explanation: 'The treaty between Egypt and the Hittites after the Battle of Kadesh is among the earliest known peace treaties.' },
  { id: 'y7-hum-86', q: 'Ramses II fought a famous battle at Kadesh against the:', choices: ['Romans', 'Hittites', 'Greeks', 'Persians'], answer: 1, explanation: 'Ramses II campaigned against the Hittites, and the Battle of Kadesh led to the famous peace treaty.' },
  { id: 'y7-hum-87', q: 'Ramses II ruled Egypt for about:', choices: ['6 months', '5 years', '66 years', '150 years'], answer: 2, explanation: 'Ramses II ruled for roughly 66 years (about 1279–1213 BCE), an unusually long reign.' },
  { id: 'y7-hum-88', q: 'Hatshepsut is remembered as:', choices: ['The builder of the Colosseum', 'A Greek philosopher', 'A Roman general', 'A woman who ruled as pharaoh'], answer: 3, explanation: 'Hatshepsut was one of the few women to rule Egypt as pharaoh in her own right.' },
  { id: 'y7-hum-89', q: 'Tutankhamun is especially famous today because:', choices: ['His tomb was found almost intact', 'He conquered ancient Rome', 'He invented hieroglyphics', 'He built the Great Sphinx'], answer: 0, explanation: 'Tutankhamun is famous mainly because his nearly intact tomb was discovered, full of treasures.' },
  { id: 'y7-hum-90', q: 'Imhotep is credited with designing:', choices: ['The Rosetta Stone', 'The first pyramid (the Step Pyramid)', 'The Treaty of Kadesh', 'The city of Rome'], answer: 1, explanation: 'Imhotep is traditionally credited with designing Egypt’s first pyramid, the Step Pyramid.' },
  { id: 'y7-hum-91', q: 'Which best describes the roles of most women in ancient Egypt?', choices: ['They were never allowed outside the home', 'They ruled every household by law', 'They had more rights than women in many ancient societies', 'They could not own anything'], answer: 2, explanation: 'Egyptian women could own property and hold some legal rights, more than in many other ancient societies.' },
  { id: 'y7-hum-92', q: 'A pharaoh’s power was often shown through:', choices: ['Small handwritten notes', 'Simple mud huts', 'Ordinary clay pots', 'Huge monuments like temples and statues'], answer: 3, explanation: 'Pharaohs displayed their power by building grand temples, statues and monuments.' },
  { id: 'y7-hum-93', q: 'Egyptian temples were mainly places for:', choices: ['Worshipping the gods and performing rituals', 'Holding sporting contests', 'Storing the army’s weapons', 'Teaching farming skills'], answer: 0, explanation: 'Temples were centres of worship where priests performed rituals to honour the gods.' },
  { id: 'y7-hum-94', q: 'The desert around the Nile valley helped ancient Egypt by:', choices: ['Providing rich farmland', 'Protecting it from many invaders', 'Supplying fresh drinking water', 'Making travel by boat easy'], answer: 1, explanation: 'The surrounding deserts acted as natural barriers that protected Egypt from attack.' },
  { id: 'y7-hum-95', q: 'A "cataract" on the Nile is a:', choices: ['Type of Egyptian god', 'Royal crown', 'Stretch of rocky rapids', 'Farming tool'], answer: 2, explanation: 'Cataracts are shallow, rocky rapids that made parts of the Nile hard to sail.' },
  { id: 'y7-hum-96', q: 'The god Horus was often linked to:', choices: ['The invention of writing', 'The flooding of Greece', 'Roman law', 'Kingship and protection'], answer: 3, explanation: 'Horus, often shown as a falcon, was associated with kingship, the sky and protection.' },
  { id: 'y7-hum-97', q: 'Which group in Egyptian society advised the pharaoh and helped run the government?', choices: ['Viziers and nobles', 'Foreign tourists', 'Enslaved labourers', 'Young children'], answer: 0, explanation: 'High officials such as the vizier and nobles helped the pharaoh govern Egypt.' },
  { id: 'y7-hum-98', q: 'Why did Egyptians write the name of the pharaoh inside an oval shape (a cartouche)?', choices: ['To show it was a spelling mistake', 'To mark it as a royal name', 'To hide it from the gods', 'To mean the pharaoh had died'], answer: 1, explanation: 'A cartouche was an oval loop drawn around a royal name to show its importance.' },
  { id: 'y7-hum-99', q: 'The pharaoh Thutmose III is linked to the Battle of:', choices: ['Kadesh', 'Marathon', 'Megiddo', 'Hastings'], answer: 2, explanation: 'Thutmose III won the Battle of Megiddo, expanding Egyptian power.' },
  { id: 'y7-hum-100', q: 'Ramses II ordered the building of the great temples at:', choices: ['the Colosseum', 'the Parthenon', 'Stonehenge', 'Abu Simbel'], answer: 3, explanation: 'Ramses II built the massive rock temples at Abu Simbel to display his power.' },
  { id: 'y7-hum-101', q: 'Why is only part of the population thought to have been fully mummified?', choices: ['Elaborate mummification was expensive', 'It was against Egyptian law', 'Nobody believed in the afterlife', 'The Nile flooded too often'], answer: 0, explanation: 'Full mummification was costly, so the most elaborate forms were mainly for the wealthy and powerful.' },
  { id: 'y7-hum-102', q: 'Which statement about hieroglyphics is accurate?', choices: ['They are a modern invention', 'They use signs for both sounds and meanings', 'They only ever show numbers', 'They are the same as the English alphabet'], answer: 1, explanation: 'Hieroglyphics combine signs that stand for sounds with signs that stand for meanings.' },
  { id: 'y7-hum-103', q: 'The main reason pharaohs led armies into battle was to:', choices: ['Collect seashells', 'Practise their farming', 'Protect and expand Egypt’s borders', 'Learn to read and write'], answer: 2, explanation: 'Pharaohs led military campaigns to defend Egypt and extend its territory and influence.' },
  { id: 'y7-hum-104', q: 'A "khopesh" carried by Egyptian soldiers was a type of:', choices: ['Sailing boat', 'Musical instrument', 'Writing tool', 'Curved sword'], answer: 3, explanation: 'The khopesh was a curved sword used as a weapon in ancient Egypt.' },
  { id: 'y7-hum-105', q: 'Nefertiti is best known as:', choices: ['A powerful Egyptian queen', 'A Greek goddess', 'A Roman senator', 'A Chinese emperor'], answer: 0, explanation: 'Nefertiti was a famous and powerful queen of ancient Egypt.' },
  { id: 'y7-hum-106', q: 'The New Kingdom is generally seen as the period when Egypt was:', choices: ['First settled by farmers', 'At the height of its power and empire', 'Ruled by the Romans', 'Completely abandoned'], answer: 1, explanation: 'The New Kingdom was Egypt’s era of greatest power, wealth and territory.' },
  { id: 'y7-hum-107', q: 'Which of these best shows why the Nile was called Egypt’s "lifeline"?', choices: ['It was full of gold and silver', 'It kept the pyramids cool', 'It gave water, food, transport and fertile soil', 'It stopped the sun from shining'], answer: 2, explanation: 'The Nile supplied water, fertile silt for crops, fish and a transport route — the basis of Egyptian life.' },
  { id: 'y7-hum-108', q: 'The debate over whether Ramses II was "a great ruler or a great bragger" shows historians using:', choices: ['A single fixed answer', 'A single dating method', 'A map-reading skill', 'Different perspectives and interpretation'], answer: 3, explanation: 'Judging Ramses II involves weighing evidence and perspectives — historians can interpret it differently.' },
  { id: 'y7-hum-109', q: 'Warfare in ancient Egypt was closely linked to:', choices: ['Religion and the gods', 'Modern democracy', 'The Roman Senate', 'Ocean surfing'], answer: 0, explanation: 'Egyptians connected warfare to religion, with gods like Horus symbolising victory and protection.' },
  { id: 'y7-hum-110', q: 'One reason cultural heritage sites like Abu Simbel are protected today is to:', choices: ['Make room for new shopping centres', 'Preserve important history for future generations', 'Hide them from all visitors', 'Prove they never existed'], answer: 1, explanation: 'Heritage protection preserves significant sites so future generations can learn from them.' },
  // ── Ancient Greece (y7-hum-111 to y7-hum-148) ──
  { id: 'y7-hum-111', q: 'Ancient Greece was made up of many independent:', choices: ['Empires', 'Farms', 'City-states', 'Kingdoms ruled by one king'], answer: 2, explanation: 'Greece was not one country but many independent city-states, each with its own government.' },
  { id: 'y7-hum-112', q: 'Greece’s many mountains affected the ancient Greeks by:', choices: ['Providing rich farmland everywhere', 'Keeping the whole country warm', 'Joining the city-states together', 'Making land travel and unity difficult'], answer: 3, explanation: 'Mountainous land separated communities, encouraging independent city-states and hindering travel.' },
  { id: 'y7-hum-113', q: 'Ancient Greece was surrounded by which seas?', choices: ['The Aegean and Mediterranean', 'The Atlantic and Pacific', 'The Red and Black', 'The Arctic and Southern'], answer: 0, explanation: 'Greece sits in south-eastern Europe, surrounded by the Aegean and Mediterranean seas.' },
  { id: 'y7-hum-114', q: 'A Greek "city-state" included:', choices: ['A single house on its own', 'A city and the land around it, with its own government', 'The whole continent of Europe', 'A floating island'], answer: 1, explanation: 'A city-state (polis) was a city plus its surrounding territory, self-governing and independent.' },
  { id: 'y7-hum-115', q: 'The word "democracy", which began in ancient Greece, means rule by:', choices: ['A single king', 'The army', 'The people', 'The priests'], answer: 2, explanation: 'Democracy comes from Greek words meaning "rule by the people".' },
  { id: 'y7-hum-116', q: 'In Athenian democracy, who was actually allowed to vote?', choices: ['Everyone including women and slaves', 'Children under ten', 'Foreign residents', 'Male citizens only'], answer: 3, explanation: 'In Athens, free male citizens could vote; women, foreigners and enslaved people were excluded.' },
  { id: 'y7-hum-117', q: 'In ancient Greek society, women were generally considered:', choices: ['Non-citizens with few rights', 'The main political leaders', 'Army commanders', 'Equal voters with men'], answer: 0, explanation: 'Greek women were non-citizens, expected to run the household and without political rights.' },
  { id: 'y7-hum-118', q: 'A Greek foot soldier who fought in armour was called a:', choices: ['Pharaoh', 'Hoplite', 'Scribe', 'Senator'], answer: 1, explanation: 'Hoplites were heavily armed Greek foot soldiers who fought in tight formations.' },
  { id: 'y7-hum-119', q: 'The "phalanx" was a:', choices: ['Type of Greek warship', 'Greek god of war', 'Tight rectangular formation of soldiers', 'Kind of farming tool'], answer: 2, explanation: 'The phalanx was a close formation of hoplites with overlapping shields and long spears.' },
  { id: 'y7-hum-120', q: 'A "trireme" in ancient Greece was a:', choices: ['Land chariot', 'Temple to the gods', 'City wall', 'Warship powered by rows of oars'], answer: 3, explanation: 'A trireme was a fast Greek warship rowed by three banks of oars.' },
  { id: 'y7-hum-121', q: 'The heroic ideals of Greek warriors are shown in the famous poem the:', choices: ['Iliad', 'Book of the Dead', 'Rosetta Stone', 'Domesday Book'], answer: 0, explanation: 'The Iliad tells of the Trojan War and reflects Greek ideals of heroism and honour.' },
  { id: 'y7-hum-122', q: 'The Peloponnesian Wars were fought mainly between:', choices: ['Greece and ancient Egypt', 'Greek city-states such as Athens and Sparta', 'Rome and China', 'Greece and Australia'], answer: 1, explanation: 'The Peloponnesian Wars were long conflicts between Greek city-states, chiefly Athens and Sparta.' },
  { id: 'y7-hum-123', q: 'Greek city-states sometimes united to fight off which foreign enemy?', choices: ['The Egyptians', 'The Chinese', 'The Persians', 'The British'], answer: 2, explanation: 'Rival city-states banded together against outside threats such as the Persian invasions.' },
  { id: 'y7-hum-124', q: 'Leonidas is remembered as a brave leader from which city-state?', choices: ['Athens', 'Rome', 'Cairo', 'Sparta'], answer: 3, explanation: 'Leonidas was a Spartan king famous for his stand against the Persians.' },
  { id: 'y7-hum-125', q: 'Pericles was an important leader linked to which city-state?', choices: ['Athens', 'Sparta', 'Rome', 'Memphis'], answer: 0, explanation: 'Pericles was a leading Athenian statesman during the city’s golden age.' },
  { id: 'y7-hum-126', q: 'At the top of the Greek social structure were the:', choices: ['Enslaved people', 'Aristocrats', 'Foreigners', 'Farm animals'], answer: 1, explanation: 'Aristocrats — wealthy landowning families — held the highest social position.' },
  { id: 'y7-hum-127', q: 'In ancient Greece, foreigners and enslaved people were classed as:', choices: ['Kings', 'Aristocrats', 'Non-citizens', 'Voting citizens'], answer: 2, explanation: 'Non-citizens included women, foreigners and enslaved people, who could not take part in government.' },
  { id: 'y7-hum-128', q: 'The concept of "significance" would help a historian decide:', choices: ['How deep the Aegean Sea is', 'What Greeks ate for breakfast every day', 'The exact weight of a trireme', 'Why Pericles is worth studying'], answer: 3, explanation: 'Significance is about judging why a person or event, like Pericles, matters historically.' },
  { id: 'y7-hum-129', q: 'Greek city-states shared a common:', choices: ['Language and religion', 'King and army', 'Single government', 'Set of city walls'], answer: 0, explanation: 'Though independent, the city-states shared the Greek language, gods and culture.' },
  { id: 'y7-hum-130', q: 'The surrounding seas were useful to the Greeks mainly for:', choices: ['Growing wheat', 'Trade and travel by ship', 'Building pyramids', 'Mining gold'], answer: 1, explanation: 'The seas allowed the Greeks to trade and travel widely across the Mediterranean.' },
  { id: 'y7-hum-131', q: 'A "battering ram" was used in Greek warfare to:', choices: ['Row a warship faster', 'Signal the gods', 'Break down gates and walls', 'Plough a field'], answer: 2, explanation: 'A battering ram was a heavy beam used to smash through enemy gates or walls.' },
  { id: 'y7-hum-132', q: 'Which statement about ancient Greece is accurate?', choices: ['It was ruled by a single emperor', 'It had no contact with the sea', 'It banned all forms of writing', 'It was many city-states, not one united nation'], answer: 3, explanation: 'Ancient Greece was a collection of independent, often rival, city-states.' },
  { id: 'y7-hum-133', q: 'Everyday matters of the Greek household were usually run by:', choices: ['Women', 'The army', 'Foreign traders', 'The city council'], answer: 0, explanation: 'Greek women managed the household and family, even though they had no political rights.' },
  { id: 'y7-hum-134', q: 'Which ancient Greek pairing is correct?', choices: ['Trireme — land chariot', 'Hoplite — foot soldier', 'Phalanx — Greek god', 'Aegean — a type of coin'], answer: 1, explanation: 'A hoplite was a foot soldier; the others are mismatched.' },
  { id: 'y7-hum-135', q: 'Greek topography (mountains and seas) also acted as:', choices: ['A single wide highway', 'Rich gold mines', 'Natural defence for city-states', 'A cause of endless flooding'], answer: 2, explanation: 'Mountains and surrounding seas provided natural barriers that helped defend the city-states.' },
  { id: 'y7-hum-136', q: 'Ancient Greece is often described as a birthplace of:', choices: ['Pyramids and mummies', 'The Great Wall', 'Gunpowder', 'Democracy and philosophy'], answer: 3, explanation: 'Greece is famous for early democracy, philosophy, mathematics, drama and sport.' },
  { id: 'y7-hum-137', q: 'To research a significant Greek individual, a student should include:', choices: ['Primary sources as evidence', 'Their personal opinion', 'No sources at all', 'A weather report'], answer: 0, explanation: 'Using primary sources provides evidence of a figure’s historical significance.' },
  { id: 'y7-hum-138', q: 'The Greek warship the trireme got its name from its:', choices: ['Three sails', 'Three rows of oars', 'Three captains', 'Three anchors'], answer: 1, explanation: '"Trireme" refers to the three banks (rows) of oars that powered it.' },
  { id: 'y7-hum-139', q: 'Why did the mountainous land make one united Greek government hard to form?', choices: ['It made everyone speak different languages', 'It flooded the cities each year', 'It separated communities and slowed travel', 'It attracted too many tourists'], answer: 2, explanation: 'Mountains isolated communities, so independent city-states developed instead of one nation.' },
  { id: 'y7-hum-140', q: 'Which of these was a Greek city-state?', choices: ['Cairo', 'Rome', 'Beijing', 'Sparta'], answer: 3, explanation: 'Sparta was a famous Greek city-state; the others belong to Egypt, Rome and China.' },
  { id: 'y7-hum-141', q: 'Spartan society was especially known for its focus on:', choices: ['Military training and discipline', 'Painting and poetry above all', 'Sea trading only', 'Farming competitions'], answer: 0, explanation: 'Sparta was famous for its strict military training and disciplined soldiers.' },
  { id: 'y7-hum-142', q: 'Athens is especially remembered for developing:', choices: ['The first pyramids', 'Early democracy', 'The Great Wall', 'Roman law'], answer: 1, explanation: 'Athens is remembered as an early home of democracy and learning.' },
  { id: 'y7-hum-143', q: 'The Greek gods were believed to:', choices: ['Have never been worshipped', 'Be ordinary Athenian citizens', 'Influence nature and human life', 'Rule the Roman Senate'], answer: 2, explanation: 'The Greeks believed their gods influenced the natural world and human affairs.' },
  { id: 'y7-hum-144', q: 'A historian studying warfare "beliefs and values" in Greece would look at:', choices: ['The price of modern oil', 'Australian rainfall data', 'A shopping receipt', 'Heroic ideals in the Iliad'], answer: 3, explanation: 'The Iliad reveals Greek values around heroism, honour and warfare.' },
  { id: 'y7-hum-145', q: 'Which correctly matches a Greek term with its meaning?', choices: ['Polis — city-state', 'Hoplite — warship', 'Trireme — foot soldier', 'Phalanx — coin'], answer: 0, explanation: 'A polis was a city-state; the other pairings are wrong.' },
  { id: 'y7-hum-146', q: 'One reason the Greek city-states could resist Persia was that they:', choices: ['Had a single all-powerful king', 'Sometimes united against a common enemy', 'Never trained any soldiers', 'Had no ships at all'], answer: 1, explanation: 'Though usually rivals, city-states sometimes joined forces against outside threats like Persia.' },
  { id: 'y7-hum-147', q: 'Which of these best shows "continuity and change" from ancient Greece to today?', choices: ['Everyone in Greece spoke English', 'Greeks used mobile phones', 'Democracy began then and still exists now, in a changed form', 'City-states still rule Australia'], answer: 2, explanation: 'Democracy is an idea that continues today, though it has changed a great deal since ancient Greece.' },
  { id: 'y7-hum-148', q: 'The famous Greek poem the Iliad is set during the:', choices: ['Peloponnesian War', 'Persian War', 'Punic War', 'Trojan War'], answer: 3, explanation: 'The Iliad is set during the Trojan War and reflects Greek heroic ideals.' },
  // ── Ancient Rome (y7-hum-149 to y7-hum-186) ──
  { id: 'y7-hum-149', q: 'The three main periods of ancient Roman history were the:', choices: ['Regal, Republican and Imperial periods', 'Old, Middle and New Kingdoms', 'Bronze, Iron and Stone Ages', 'Pleistocene and Holocene'], answer: 0, explanation: 'Rome moved through the regal (kings), republican and imperial periods.' },
  { id: 'y7-hum-150', q: 'According to the course, the city of Rome was originally founded by the:', choices: ['Egyptians', 'Etruscans', 'Greeks', 'Hittites'], answer: 1, explanation: 'The course text describes Rome as founded by the Etruscans before growing into a huge empire.' },
  { id: 'y7-hum-151', q: 'Which river was important to the growth of ancient Rome?', choices: ['The Nile', 'The Amazon', 'The Tiber', 'The Yellow River'], answer: 2, explanation: 'The Tiber River gave Rome fresh water and a transport link to the sea.' },
  { id: 'y7-hum-152', q: 'The fertile land around Rome (Latium) helped it by allowing:', choices: ['The building of pyramids', 'Year-round snow sports', 'Easy gold mining', 'Surplus farming that supported trade'], answer: 3, explanation: 'Fertile soil produced surplus food, which supported population growth and trade.' },
  { id: 'y7-hum-153', q: 'The wealthy, upper-class families of Rome were called the:', choices: ['Patricians', 'Plebeians', 'Pharaohs', 'Hoplites'], answer: 0, explanation: 'Patricians were the aristocratic families at the top of Roman society.' },
  { id: 'y7-hum-154', q: 'Ordinary common citizens of Rome were called the:', choices: ['Patricians', 'Plebeians', 'Scribes', 'Aristocrats'], answer: 1, explanation: 'Plebeians were the common people — free citizens, but below the patricians.' },
  { id: 'y7-hum-155', q: 'Roman women were:', choices: ['Never considered citizens', 'The main army generals', 'Technically citizens but with few rights', 'Barred from all family life'], answer: 2, explanation: 'Roman women were technically citizens but had far fewer rights than men.' },
  { id: 'y7-hum-156', q: 'A large unit of the Roman army was called a:', choices: ['Phalanx', 'Cataract', 'Cartouche', 'Legion'], answer: 3, explanation: 'The Roman army was organised into large units called legions.' },
  { id: 'y7-hum-157', q: '"Via Romana", the Roman way, refers to Roman:', choices: ['Values and customs', 'A single famous road', 'A type of coin', 'A war chariot'], answer: 0, explanation: 'Via Romana meant the Roman way of life — its shared values and customs.' },
  { id: 'y7-hum-158', q: 'The Roman army was especially known for its:', choices: ['Refusal to train', 'Discipline and organisation', 'Lack of any weapons', 'Tiny size'], answer: 1, explanation: 'Disciplined training and clever tactics made the Roman army highly effective.' },
  { id: 'y7-hum-159', q: 'How did the Romans usually treat the religions of peoples they conquered?', choices: ['They banned all other religions', 'They ignored religion entirely', 'They often tolerated and adopted their gods', 'They forced everyone to stop believing'], answer: 2, explanation: 'Romans were generally tolerant, often adopting the gods and customs of conquered peoples.' },
  { id: 'y7-hum-160', q: 'Some Roman leaders, such as Julius Caesar, were:', choices: ['Made pharaohs of Egypt', 'Elected kings of Greece', 'Turned into Egyptian mummies', 'Declared gods after their deaths'], answer: 3, explanation: 'Certain Roman leaders were declared gods after death, mixing religion with politics.' },
  { id: 'y7-hum-161', q: 'By the 2nd century CE, the Roman Empire stretched roughly from:', choices: ['Britain to Azerbaijan', 'China to Japan', 'Australia to Antarctica', 'Egypt to Ireland only'], answer: 0, explanation: 'At its height the empire reached from Britain in the west to around Azerbaijan in the east.' },
  { id: 'y7-hum-162', q: 'Roman society lasted for approximately:', choices: ['50 years', '1,300 years', '10,000 years', '6 months'], answer: 1, explanation: 'Roman society lasted around 1,300 years, from a small city to a vast empire and its decline.' },
  { id: 'y7-hum-163', q: 'Which statement about Julius Caesar is accurate?', choices: ['He was the first emperor of Rome', 'He was an Egyptian pharaoh', 'He was a Roman leader who was never crowned emperor', 'He founded the city of Athens'], answer: 2, explanation: 'Julius Caesar was a powerful Roman leader but never held the title of emperor; Augustus was the first emperor.' },
  { id: 'y7-hum-164', q: 'The first emperor of Rome was:', choices: ['Julius Caesar', 'Leonidas', 'Ramses II', 'Augustus'], answer: 3, explanation: 'Augustus became the first Roman emperor, beginning the imperial period.' },
  { id: 'y7-hum-165', q: '"Siege warfare" means:', choices: ['Surrounding and attacking a fortified place', 'Fighting only at sea', 'Racing chariots for sport', 'Trading goods peacefully'], answer: 0, explanation: 'Siege warfare involved surrounding a walled town or fort to capture it.' },
  { id: 'y7-hum-166', q: 'Which ancient Roman pairing is correct?', choices: ['Plebeians — enslaved people', 'Patricians — wealthy upper class', 'Legion — a single soldier', 'Via Romana — a war chariot'], answer: 1, explanation: 'Patricians were the wealthy upper class; the other pairings are wrong.' },
  { id: 'y7-hum-167', q: 'Marcus Aurelius and Augustus are both examples of significant:', choices: ['Greek city-states', 'Egyptian gods', 'Roman individuals', 'Chinese dynasties'], answer: 2, explanation: 'Both were significant figures in Roman history.' },
  { id: 'y7-hum-168', q: 'The main role of upper-class Roman women was usually to:', choices: ['Command the legions', 'Serve in the Senate', 'Lead religious wars', 'Raise children and run the household'], answer: 3, explanation: 'Higher-class Roman women mainly managed the household and raised children.' },
  { id: 'y7-hum-169', q: 'Access to the Mediterranean Sea helped Rome by supporting:', choices: ['Trade and movement across the empire', 'Snow skiing', 'Pyramid building', 'Ice fishing'], answer: 0, explanation: 'The Mediterranean gave Rome sea routes for trade and moving armies and goods.' },
  { id: 'y7-hum-170', q: 'Roman values and beliefs were often a mix of:', choices: ['Recent Australian ideas', 'Their own traditions and those of conquered peoples', 'Beliefs invented last century', 'Nothing at all'], answer: 1, explanation: 'Roman customs blended inherited traditions with ideas adopted from societies they conquered.' },
  { id: 'y7-hum-171', q: 'Which of these best shows Rome’s political change over time?', choices: ['From emperors, to kings, to farmers', 'It never changed its government', 'From rule by kings, to a republic, to emperors', 'It was always ruled by Greece'], answer: 2, explanation: 'Rome shifted from kings (regal) to the republic and finally to rule by emperors.' },
  { id: 'y7-hum-172', q: 'The Roman "republic" meant that Rome was:', choices: ['Ruled by a single god-king', 'Controlled by ancient Egypt', 'Without any government', 'Governed by elected officials rather than a king'], answer: 3, explanation: 'In the republic, Rome was governed by elected officials instead of a monarch.' },
  { id: 'y7-hum-173', q: 'Compared with Greek women, Roman women were:', choices: ['Counted as citizens, though with limited rights', 'Given no status at all', 'Made army commanders', 'The only people allowed to vote'], answer: 0, explanation: 'Unlike Greek women (non-citizens), Roman women were technically citizens, though with limited rights.' },
  { id: 'y7-hum-174', q: 'A key reason the Roman army could expand its territory was its:', choices: ['Refusal to fight', 'Disciplined training and tactics', 'Lack of any leaders', 'Very small size'], answer: 1, explanation: 'Discipline, training and organisation allowed the Roman army to conquer and hold new lands.' },
  { id: 'y7-hum-175', q: 'Which of these was a significant Roman individual studied in the unit?', choices: ['Hatshepsut', 'Pericles', 'Agrippina the Younger', 'Qin Shi Huang'], answer: 2, explanation: 'Agrippina the Younger is a significant Roman figure; the others belong to Egypt, Greece and China.' },
  { id: 'y7-hum-176', q: 'The historical concept of "continuity and change" could compare Roman society with:', choices: ['The weather tomorrow', 'A maths equation', 'A shopping list', 'Society today'], answer: 3, explanation: 'Continuity and change compares how life in ancient Rome is similar to and different from today.' },
  { id: 'y7-hum-177', q: 'Rome grew from a collection of villages into a:', choices: ['Large and powerful empire', 'Single small farm', 'Floating island', 'Greek city-state'], answer: 0, explanation: 'Rome expanded from small villages into one of the ancient world’s greatest empires.' },
  { id: 'y7-hum-178', q: 'The Tiber and Po river regions were valued for their:', choices: ['Gold and diamonds', 'Fertile soil and fresh water', 'Snow and ice', 'Salt deserts'], answer: 1, explanation: 'These fertile river regions supported farming, surplus production and trade.' },
  { id: 'y7-hum-179', q: 'Which statement about Roman religion is accurate?', choices: ['Romans worshipped only one god', 'Romans had no religion', 'Romans worshipped many gods and adopted new ones', 'Romans banned all temples'], answer: 2, explanation: 'Romans were polytheistic and often added gods from the peoples they conquered.' },
  { id: 'y7-hum-180', q: 'A research task on a significant Roman should include at least three:', choices: ['Made-up stories', 'Modern song lyrics', 'Blank pages', 'Primary sources as evidence'], answer: 3, explanation: 'Using primary sources provides evidence of the figure’s historical significance.' },
  { id: 'y7-hum-181', q: 'Which correctly orders Rome’s political periods from earliest to latest?', choices: ['Regal, Republican, Imperial', 'Imperial, Republican, Regal', 'Republican, Regal, Imperial', 'Imperial, Regal, Republican'], answer: 0, explanation: 'Rome began with kings (regal), then the republic, then the empire (imperial).' },
  { id: 'y7-hum-182', q: 'The Roman social system clearly separated:', choices: ['Left-handed from right-handed people', 'Free people from enslaved people, and rich from poor', 'Farmers from other farmers', 'Nobody at all'], answer: 1, explanation: 'Roman society had clear divisions between free and enslaved, wealthy and poor, citizen and non-citizen.' },
  { id: 'y7-hum-183', q: 'Which of these is a common misconception about ancient Rome?', choices: ['That Rome had a large army', 'That the Tiber ran through Rome', 'That Rome was always ruled by emperors', 'That Rome traded across the Mediterranean'], answer: 2, explanation: 'Rome was not always ruled by emperors — it had kings and then a republic first.' },
  { id: 'y7-hum-184', q: 'The Roman army spread Roman culture because soldiers:', choices: ['Refused to leave Rome', 'Never met other peoples', 'Stayed at home in Rome', 'Took Roman customs to conquered lands'], answer: 3, explanation: 'As the army conquered new territory, it carried Roman language, customs and ideas with it.' },
  { id: 'y7-hum-185', q: 'Julius Caesar being declared a god after death shows how Romans linked:', choices: ['Politics and religion', 'Farming and fishing', 'Maths and music', 'Sea and desert'], answer: 0, explanation: 'Declaring leaders gods after death shows how closely Roman politics and religion were tied.' },
  { id: 'y7-hum-186', q: 'The geography of Italy helped Rome mainly by providing:', choices: ['Constant snowstorms', 'Fertile land, rivers and sea access', 'A ring of active volcanoes around every city', 'No water at all'], answer: 1, explanation: 'Fertile land, the Tiber and Mediterranean access supported farming, trade and growth.' },
  // ── Ancient China (y7-hum-187 to y7-hum-224) ──
  { id: 'y7-hum-187', q: 'Ancient China’s history is often organised into ruling family lines called:', choices: ['City-states', 'Legions', 'Dynasties', 'Kingdoms of the Nile'], answer: 2, explanation: 'A dynasty is a series of rulers from the same family; Chinese history is divided into dynasties.' },
  { id: 'y7-hum-188', q: 'A "dynasty" is best described as:', choices: ['A single king who rules once', 'A type of Chinese coin', 'A mountain range', 'A ruling family line across generations'], answer: 3, explanation: 'A dynasty is a line of rulers from one family, passing power down through generations.' },
  { id: 'y7-hum-189', q: 'The huge mountain range on China’s edge that limited contact with others is the:', choices: ['Himalayas', 'Alps', 'Andes', 'Great Dividing Range'], answer: 0, explanation: 'The Himalayas and other ranges protected China and made contact with other peoples difficult.' },
  { id: 'y7-hum-190', q: 'How did China’s mountains and seas affect its early development?', choices: ['They joined China to Europe', 'They protected China and limited outside contact', 'They caused constant flooding of cities', 'They provided most of China’s gold'], answer: 1, explanation: 'Natural barriers like mountains and seas protected China and reduced contact with other societies.' },
  { id: 'y7-hum-191', q: 'Ancient Chinese society was based on a:', choices: ['System with no classes', 'Single family of equals', 'Strict social hierarchy', 'Yearly lottery for rulers'], answer: 2, explanation: 'Chinese society had a strict hierarchy, reinforced by the teachings of Confucius.' },
  { id: 'y7-hum-192', q: 'The teacher whose ideas shaped Chinese society and stressed order and respect was:', choices: ['Herodotus', 'Ramses II', 'Pericles', 'Confucius'], answer: 3, explanation: 'Confucius taught that a successful society needed order, discipline and respect.' },
  { id: 'y7-hum-193', q: 'Confucius lived during which years?', choices: ['551–479 BCE', '1279–1213 BCE', '100–200 CE', '1901–1945 CE'], answer: 0, explanation: 'Confucius, the Chinese philosopher and teacher, lived from 551 to 479 BCE.' },
  { id: 'y7-hum-194', q: 'The "Mandate of Heaven" was the belief that a ruler:', choices: ['Was elected by popular vote', 'Had divine approval to rule, which could be lost', 'Owned every piece of land forever', 'Could never be replaced'], answer: 1, explanation: 'The Mandate of Heaven gave rulers divine approval, which could be lost through disasters or bad rule.' },
  { id: 'y7-hum-195', q: 'In ancient China, older people were:', choices: ['Sent away from the community', 'Banned from speaking', 'Greatly respected for their wisdom', 'Made to fight in wars'], answer: 2, explanation: 'The Chinese strongly valued the wisdom of elders, so older people were greatly respected.' },
  { id: 'y7-hum-196', q: 'Which was a major belief system in ancient China?', choices: ['Democracy', 'The Via Romana', 'The Book of the Dead', 'Confucianism'], answer: 3, explanation: 'Confucianism, Daoism (Taoism) and Buddhism were major belief systems in ancient China.' },
  { id: 'y7-hum-197', q: 'According to the course, Confucianism was mostly about:', choices: ['Behaviour and how people should treat each other', 'Worshipping many war gods', 'Building pyramids', 'Sailing warships'], answer: 0, explanation: 'The course describes Confucianism as concerned with behaviour and relationships, more than religion.' },
  { id: 'y7-hum-198', q: 'Which belief system began in India and later spread to China?', choices: ['Confucianism', 'Buddhism', 'Daoism', 'Roman religion'], answer: 1, explanation: 'Buddhism originated in India and spread to China, unlike Confucianism and Daoism which began in China.' },
  { id: 'y7-hum-199', q: 'Qin Shi Huang is remembered as:', choices: ['A Greek philosopher', 'An Egyptian queen', 'A significant early Chinese emperor', 'A Roman general'], answer: 2, explanation: 'Qin Shi Huang was a significant ruler in early imperial China.' },
  { id: 'y7-hum-200', q: 'Wu Zetian is significant in Chinese history as:', choices: ['A Roman emperor', 'A Greek warrior', 'An Egyptian scribe', 'A woman who ruled as empress'], answer: 3, explanation: 'Wu Zetian was a significant Chinese ruler, notable as a woman who held supreme power.' },
  { id: 'y7-hum-201', q: 'Daoism (Taoism) in ancient China is described as more:', choices: ['Religious in nature', 'A system of maths', 'A military tactic', 'A farming method'], answer: 0, explanation: 'The course contrasts religious Daoism with Confucianism, which focused on behaviour.' },
  { id: 'y7-hum-202', q: 'Long rivers helped ancient Chinese society mainly by:', choices: ['Blocking all travel', 'Supporting farming and providing water', 'Cooling the deserts', 'Producing gold coins'], answer: 1, explanation: 'China’s long rivers supplied water and fertile land that supported farming and settlement.' },
  { id: 'y7-hum-203', q: 'Ancient China was located on which side of the Asian continent?', choices: ['The far western side', 'The southern tip of Africa', 'The eastern side', 'The centre of Europe'], answer: 2, explanation: 'Ancient China lay on the eastern side of Asia, bordered by seas and mountains.' },
  { id: 'y7-hum-204', q: 'Which statement about a dynasty is accurate?', choices: ['It is one king who rules for one day', 'It is a kind of Chinese temple', 'It is a river in China', 'It is a family line of rulers, not a single person'], answer: 3, explanation: 'A dynasty is a ruling family whose power passes across generations, not a single ruler.' },
  { id: 'y7-hum-205', q: 'Confucius taught that a stable society needed:', choices: ['Order, respect and clear social roles', 'No leaders or rules', 'Constant warfare', 'Everyone to rule at once'], answer: 0, explanation: 'Confucius argued society needed order, discipline and respect for social roles.' },
  { id: 'y7-hum-206', q: 'The Mandate of Heaven could be lost if a ruler:', choices: ['Won a war', 'Ruled badly or faced disasters', 'Built a new temple', 'Lived a long life'], answer: 1, explanation: 'Natural disasters, rebellion or poor rule were signs a ruler had lost the Mandate of Heaven.' },
  { id: 'y7-hum-207', q: 'Which correctly matches a Chinese belief system with its focus?', choices: ['Buddhism — Roman law', 'Daoism — building pyramids', 'Confucianism — proper behaviour and respect', 'Confucianism — sea trading rules'], answer: 2, explanation: 'Confucianism focused on behaviour and respect; the other pairings are wrong.' },
  { id: 'y7-hum-208', q: 'A common misconception is that the Himalayas helped China by:', choices: ['Protecting it from invaders', 'Limiting outside contact', 'Acting as a natural barrier', 'Making trade with neighbours easy'], answer: 3, explanation: 'The Himalayas actually limited contact and protected China — they did not make trade easy.' },
  { id: 'y7-hum-209', q: 'The role of women in ancient China was shaped by:', choices: ['Beliefs and traditions that limited their status', 'Laws making them army generals', 'A rule that only women could rule', 'Complete equality with men'], answer: 0, explanation: 'Traditions and beliefs shaped and often limited women’s roles in ancient Chinese society.' },
  { id: 'y7-hum-210', q: 'Which historical concept helps compare ancient Chinese society with today?', choices: ['Evaporation', 'Continuity and change', 'Multiplication', 'Bearing'], answer: 1, explanation: 'Continuity and change compares how ancient Chinese society is similar to and different from modern society.' },
  { id: 'y7-hum-211', q: 'The Chinese respected elders because they believed elders had:', choices: ['The most money', 'The largest armies', 'Wisdom worth listening to', 'Magic powers over rivers'], answer: 2, explanation: 'Elders were respected for their wisdom and experience.' },
  { id: 'y7-hum-212', q: 'To study a significant Chinese individual, students should use:', choices: ['Personal guesswork', 'A weather forecast', 'A shopping list', 'Primary sources as evidence'], answer: 3, explanation: 'Primary sources provide evidence of a figure’s historical significance.' },
  { id: 'y7-hum-213', q: 'Which of these is a belief system that began IN China?', choices: ['Daoism', 'Buddhism', 'Roman religion', 'Greek mythology'], answer: 0, explanation: 'Daoism and Confucianism began in China; Buddhism came from India.' },
  { id: 'y7-hum-214', q: 'Ancient Chinese dynasties are studied in the unit in which order?', choices: ['Early imperial China before any dynasties', 'Pre-imperial dynasties before early imperial China', 'Roman before Chinese periods', 'There were no dynasties'], answer: 1, explanation: 'The unit orders pre-imperial dynasties before the early imperial period of China.' },
  { id: 'y7-hum-215', q: 'A mild climate in parts of ancient China helped by:', choices: ['Freezing all the rivers', 'Preventing any crops', 'Supporting farming and settlement', 'Blocking the sunlight'], answer: 2, explanation: 'A mild climate, together with rivers, supported the farming that Chinese society relied on.' },
  { id: 'y7-hum-216', q: 'Confucius is best described as a:', choices: ['War general', 'Sea captain', 'Pyramid builder', 'Philosopher and teacher'], answer: 3, explanation: 'Confucius was a philosopher and teacher whose ideas shaped Chinese culture.' },
  { id: 'y7-hum-217', q: 'The idea of the Mandate of Heaven helped explain:', choices: ['Why dynasties rose and fell', 'How to build boats', 'The path of the Nile', 'Greek democracy'], answer: 0, explanation: 'When a dynasty fell, people believed it had lost the Mandate of Heaven, and a new one gained it.' },
  { id: 'y7-hum-218', q: 'Which of these is a Chinese belief system?', choices: ['Democracy', 'Confucianism', 'Federation', 'The phalanx'], answer: 1, explanation: 'Confucianism is a Chinese belief system; the others are unrelated ideas.' },
  { id: 'y7-hum-219', q: 'Physical features like rivers and mountains gave ancient China:', choices: ['Problems but no real benefits', 'A link straight to Rome', 'Both protection and useful resources', 'Constant snow all year'], answer: 2, explanation: 'Rivers gave water and farmland while mountains and seas offered protection.' },
  { id: 'y7-hum-220', q: 'Which statement about Confucianism and Daoism is accurate?', choices: ['Both were about building pyramids', 'Both came from ancient Rome', 'Neither existed in China', 'Confucianism focused on behaviour; Daoism was more religious'], answer: 3, explanation: 'The course describes Confucianism as about behaviour and Daoism as more religious.' },
  { id: 'y7-hum-221', q: 'Social order in ancient China was strongly reinforced by the ideas of:', choices: ['Confucius', 'Julius Caesar', 'Herodotus', 'Ramses II'], answer: 0, explanation: 'Confucius’s teachings on order and respect strongly shaped Chinese social structure.' },
  { id: 'y7-hum-222', q: 'Rulers of ancient China believed their right to rule came from:', choices: ['Winning an election', 'Heaven (the Mandate of Heaven)', 'The Roman Senate', 'The Greek gods'], answer: 1, explanation: 'Chinese rulers claimed the Mandate of Heaven — divine approval — as their right to rule.' },
  { id: 'y7-hum-223', q: 'Which of these individuals is from ancient China?', choices: ['Leonidas', 'Augustus', 'Wu Zetian', 'Tutankhamun'], answer: 2, explanation: 'Wu Zetian was a Chinese ruler; the others belong to Greece, Rome and Egypt.' },
  { id: 'y7-hum-224', q: 'One reason ancient China had limited contact with distant societies was its:', choices: ['Lack of any rivers', 'Refusal to farm', 'Very small population', 'Mountains, deserts and seas acting as barriers'], answer: 3, explanation: 'Natural barriers like the Himalayas, deserts and seas limited China’s contact with far-off peoples.' },
  // ── Geography Skills (y7-hum-225 to y7-hum-246) ──
  { id: 'y7-hum-225', q: 'Geographers use the letters BOLTSS to remember the parts of a:', choices: ['Map', 'Timeline', 'Poem', 'Recipe'], answer: 0, explanation: 'BOLTSS lists the features every good map should include.' },
  { id: 'y7-hum-226', q: 'In BOLTSS, the "L" stands for:', choices: ['Latitude', 'Legend', 'Length', 'Location'], answer: 1, explanation: 'The legend (or key) explains what the symbols on a map mean.' },
  { id: 'y7-hum-227', q: 'A map’s "legend" (or key) is used to:', choices: ['Show the map’s title only', 'Give the date the map was drawn', 'Explain what the symbols mean', 'List the mapmaker’s name'], answer: 2, explanation: 'The legend tells the reader what each symbol and colour on the map represents.' },
  { id: 'y7-hum-228', q: 'The "scale" on a map tells you:', choices: ['Which way is north', 'Who drew the map', 'The title of the map', 'How map distance relates to real distance'], answer: 3, explanation: 'Scale shows how a distance on the map compares to the real distance on the ground.' },
  { id: 'y7-hum-229', q: 'The compass directions north, south, east and west help show a map’s:', choices: ['Orientation', 'Scale', 'Legend', 'Title'], answer: 0, explanation: 'Orientation (often a north arrow) shows which way the map is turned.' },
  { id: 'y7-hum-230', q: 'The geographical concept method SPICESS helps geographers:', choices: ['Date ancient bones', 'Examine places and issues in a holistic way', 'Write history paragraphs', 'Mummify bodies'], answer: 1, explanation: 'SPICESS lists key geographical concepts used to investigate places and issues.' },
  { id: 'y7-hum-231', q: 'The PQE method is used to describe:', choices: ['The age of fossils', 'The rules of Roman law', 'Patterns in data on maps and graphs', 'Egyptian gods'], answer: 2, explanation: 'PQE (Pattern, Quantification, Exception) helps describe distributions shown in data.' },
  { id: 'y7-hum-232', q: 'In PQE, the "P" stands for:', choices: ['Place', 'Population', 'Purpose', 'Pattern'], answer: 3, explanation: 'PQE begins by describing the overall Pattern in the data.' },
  { id: 'y7-hum-233', q: 'In PQE, the "E" stands for:', choices: ['Exception', 'Evaporation', 'Elevation', 'Estimate'], answer: 0, explanation: 'The "E" in PQE is the Exception — a place or value that does not fit the pattern.' },
  { id: 'y7-hum-234', q: 'A grid reference on a map is used to:', choices: ['Show the map’s legend', 'Describe the location of a feature', 'Give the map a title', 'Colour in the oceans'], answer: 1, explanation: 'Grid references use numbered lines to pinpoint a location on a map.' },
  { id: 'y7-hum-235', q: 'To find direction on a map, a geographer uses a:', choices: ['Calculator', 'Microscope', 'Compass', 'Thermometer'], answer: 2, explanation: 'A compass shows direction, helping read a map’s orientation.' },
  { id: 'y7-hum-236', q: 'Which is one of the SPICESS geographical concepts?', choices: ['Evaporation', 'Empathy', 'Equation', 'Environment'], answer: 3, explanation: 'Environment is one of the SPICESS concepts geographers use to study the world.' },
  { id: 'y7-hum-237', q: 'The "S" for scale in geography can mean looking at an issue at different:', choices: ['Levels, from local to global', 'Colours', 'Temperatures', 'Languages'], answer: 0, explanation: 'Scale means studying an issue at different levels, such as local, national or global.' },
  { id: 'y7-hum-238', q: 'The "interconnection" concept in geography looks at how:', choices: ['Ancient rock layers are dated by scientists', 'Places and people are linked and affect each other', 'Maps are coloured in by hand', 'Historical timelines are drawn up'], answer: 1, explanation: 'Interconnection examines how places, people and environments are linked and influence one another.' },
  { id: 'y7-hum-239', q: 'A map’s "title" tells the reader:', choices: ['How far north it points', 'What the symbols mean', 'What the map is about', 'The map’s exact scale'], answer: 2, explanation: 'The title states the subject or area the map shows.' },
  { id: 'y7-hum-240', q: 'The "source" on a map shows:', choices: ['Which way is north', 'The size of the oceans', 'The map’s legend', 'Where the map’s information came from'], answer: 3, explanation: 'The source credits where the data or information for the map came from.' },
  { id: 'y7-hum-241', q: 'Which correctly matches a BOLTSS letter to its meaning?', choices: ['S — Scale', 'B — Legend', 'O — Title', 'L — Border'], answer: 0, explanation: 'S stands for Scale; the other pairings are mismatched.' },
  { id: 'y7-hum-242', q: 'When describing data, "quantification" (the Q in PQE) means using:', choices: ['Colours and shapes', 'Numbers and figures', 'Compass directions', 'Ancient dates'], answer: 1, explanation: 'Quantification uses numbers and data to describe how much or how many.' },
  { id: 'y7-hum-243', q: 'A geographer noticing that most people cluster near the coast is describing a:', choices: ['Legend', 'Title', 'Pattern', 'Scale'], answer: 2, explanation: 'Describing where features cluster or spread is identifying a pattern (the P in PQE).' },
  { id: 'y7-hum-244', q: 'Which of these is a key part of thinking like a geographer?', choices: ['Memorising Roman emperors', 'Dating fossils', 'Reciting Egyptian gods', 'Asking where things are and why they are there'], answer: 3, explanation: 'Geographers ask where things are located and why, using concepts and skills.' },
  { id: 'y7-hum-245', q: 'The "B" in BOLTSS stands for:', choices: ['Border', 'Bearing', 'Boundary line only', 'Base'], answer: 0, explanation: 'The Border (or frame) neatly encloses the mapped area.' },
  { id: 'y7-hum-246', q: 'Reading a grid reference in the wrong order could cause a geographer to:', choices: ['Change the map’s title', 'Point to the wrong location', 'Alter the legend', 'Redraw the border'], answer: 1, explanation: 'Grid references must be read in the correct order or they point to the wrong place.' },
  // ── Water in the World (y7-hum-247 to y7-hum-274) ──
  { id: 'y7-hum-247', q: 'Water is described as a renewable resource because it:', choices: ['Can never run out anywhere', 'Is made in factories', 'Is replenished by the water cycle', 'Never moves or changes'], answer: 2, explanation: 'The water cycle continually replenishes water, making it a renewable resource, though supplies vary.' },
  { id: 'y7-hum-248', q: 'In the water cycle, evaporation is when water:', choices: ['Falls from clouds as rain', 'Freezes into ice', 'Soaks into the ground', 'Changes from liquid into vapour'], answer: 3, explanation: 'Evaporation turns liquid water into water vapour that rises into the air.' },
  { id: 'y7-hum-249', q: 'In the water cycle, condensation is when water vapour:', choices: ['Cools and turns back into liquid', 'Heats up and disappears', 'Runs along the ground', 'Sinks deep underground'], answer: 0, explanation: 'Condensation is water vapour cooling and turning back into liquid droplets, forming clouds.' },
  { id: 'y7-hum-250', q: 'Precipitation in the water cycle means:', choices: ['Water turning into vapour', 'Water falling as rain, hail or snow', 'Water soaking into soil', 'Water flowing in a river'], answer: 1, explanation: 'Precipitation is water falling from clouds as rain, hail, sleet or snow.' },
  { id: 'y7-hum-251', q: '"Runoff" in the water cycle is water that:', choices: ['Evaporates into the sky', 'Freezes at the poles', 'Flows over the land into rivers and seas', 'Stays inside clouds'], answer: 2, explanation: 'Runoff is water that flows across the land’s surface into streams, rivers and the sea.' },
  { id: 'y7-hum-252', q: '"Groundwater" is best described as water:', choices: ['Floating inside clouds', 'Flowing over a waterfall', 'Sitting on top of the ocean', 'Held in the spaces of soil and rock'], answer: 3, explanation: 'Groundwater is stored underground in the pores and gaps of soil and rock.' },
  { id: 'y7-hum-253', q: 'A non-renewable resource is one that:', choices: ['Cannot be replaced once it is used up', 'Is replaced quickly by nature', 'Is always available like sunlight', 'Falls freely as rain'], answer: 0, explanation: 'Non-renewable resources, such as coal or oil, cannot be replaced within a human lifetime once used.' },
  { id: 'y7-hum-254', q: 'A "continuous" resource, such as sunlight or wind, is one that:', choices: ['Runs out after a single use', 'Is always available no matter what we do', 'Must be dug up from the ground', 'Comes from underground mines'], answer: 1, explanation: 'Continuous resources like solar and wind energy are always available and cannot be used up.' },
  { id: 'y7-hum-255', q: 'Which is an example of using water for recreation?', choices: ['Generating electricity', 'Watering crops', 'Swimming and water skiing', 'Shipping cargo'], answer: 2, explanation: 'Recreational uses of water include swimming, boating and other leisure activities.' },
  { id: 'y7-hum-256', q: 'Water used to generate electricity in a dam is an example of a(n):', choices: ['Recreational use of water', 'Health use of water', 'Decorative use of water', 'Energy use of water'], answer: 3, explanation: 'Dams use flowing water to generate hydroelectric power — an energy use of water.' },
  { id: 'y7-hum-257', q: 'For Aboriginal and Torres Strait Islander peoples, water also holds:', choices: ['Spiritual and cultural value', 'No importance at all', 'A purely financial value', 'A value just for washing'], answer: 0, explanation: 'First Nations peoples value water spiritually and artistically, expressed through symbols and creation stories.' },
  { id: 'y7-hum-258', q: '"Water scarcity" means:', choices: ['Too much rain everywhere', 'A shortage of usable fresh water', 'Water that is always clean', 'A type of ocean current'], answer: 1, explanation: 'Water scarcity is a shortage of enough safe, usable fresh water for people’s needs.' },
  { id: 'y7-hum-259', q: 'Which of these can cause water scarcity?', choices: ['Building more libraries', 'Planting more flowers', 'Inefficient irrigation and population growth', 'Drawing more maps'], answer: 2, explanation: 'Wasteful irrigation, growing populations and old infrastructure can all lead to water scarcity.' },
  { id: 'y7-hum-260', q: 'Desalination is a water strategy that:', choices: ['Freezes rivers solid', 'Adds salt to fresh water', 'Stops all rainfall', 'Removes salt from seawater to make it drinkable'], answer: 3, explanation: 'Desalination removes salt from seawater, but it is expensive and uses a lot of energy.' },
  { id: 'y7-hum-261', q: 'Water recycling helps manage scarcity by:', choices: ['Treating used water so it can be used again', 'Pouring water into the sea', 'Banning all water use', 'Turning water into oil'], answer: 0, explanation: 'Recycling treats wastewater so it can be reused, helping stretch limited water supplies.' },
  { id: 'y7-hum-262', q: 'The documentary case study of water scarcity in the unit focused on:', choices: ['Iceland', 'Iran', 'Ireland', 'Indonesia'], answer: 1, explanation: 'The unit uses the water crisis in Iran as a case study of causes and impacts of scarcity.' },
  { id: 'y7-hum-263', q: 'A "water hazard" studied in the unit is:', choices: ['A calm garden pond', 'A glass of water', 'River flooding', 'A water slide'], answer: 2, explanation: 'Water hazards include river flooding and river pollution, which have serious impacts.' },
  { id: 'y7-hum-264', q: 'Which is a correct statement about water as a resource?', choices: ['It is non-renewable and cannot return', 'It never moves through the environment', 'It only exists in oceans', 'It is renewable but its availability varies'], answer: 3, explanation: 'Water is renewable through the cycle, but how much is available differs across time and place.' },
  { id: 'y7-hum-265', q: 'Which correctly orders part of the water cycle?', choices: ['Evaporation, then condensation, then precipitation', 'Precipitation, then evaporation, then groundwater', 'Runoff, then evaporation, then rain first', 'Condensation, then evaporation, then vapour'], answer: 0, explanation: 'Water evaporates, condenses into clouds, then falls as precipitation.' },
  { id: 'y7-hum-266', q: 'Which of these is a common misconception about water?', choices: ['That the water cycle replenishes water', 'That water is a non-renewable resource', 'That water can be used for energy', 'That water has spiritual value to First Nations peoples'], answer: 1, explanation: 'Water is renewable, not non-renewable — the water cycle keeps replenishing it.' },
  { id: 'y7-hum-267', q: 'A place where different water uses compete might have to choose between water for:', choices: ['Rain and for snow', 'The past and the future', 'Farming and for drinking', 'Maps and for legends'], answer: 2, explanation: 'Uses such as agriculture, industry and drinking can compete for the same limited water.' },
  { id: 'y7-hum-268', q: 'The Three Gorges Dam is used in the unit as an example related to:', choices: ['Ancient Egypt', 'Roman law', 'Greek democracy', 'Water uses'], answer: 3, explanation: 'The unit lists the Three Gorges Dam among locations for studying different water uses.' },
  { id: 'y7-hum-269', q: 'Impacts of water scarcity can be social, economic, political and:', choices: ['Environmental', 'Imaginary', 'Musical', 'Historical only'], answer: 0, explanation: 'Water scarcity affects society, the economy, politics and the environment.' },
  { id: 'y7-hum-270', q: 'Which is a health-related use of water?', choices: ['Racing speedboats', 'Drinking and staying clean', 'Generating hydroelectric power', 'Shipping containers overseas'], answer: 1, explanation: 'Clean water for drinking and hygiene is a vital health use of water.' },
  { id: 'y7-hum-271', q: 'River pollution is a water hazard because it can:', choices: ['Make water safer to drink', 'Increase clean water supplies', 'Harm people, animals and the environment', 'Stop rivers from flowing'], answer: 2, explanation: 'Polluted rivers damage ecosystems and threaten the health of people and wildlife.' },
  { id: 'y7-hum-272', q: 'One reason desalination is not used everywhere is that it:', choices: ['Makes water taste like salt', 'Works best in cold weather', 'Creates too much fresh water', 'Is expensive and uses lots of energy'], answer: 3, explanation: 'Desalination is costly and energy-intensive, so it is only one of several strategies.' },
  { id: 'y7-hum-273', q: 'Which best explains why water availability "varies across space"?', choices: ['Some places have far more fresh water than others', 'All places have exactly the same water', 'Water only exists at the poles', 'Water never moves between places'], answer: 0, explanation: 'Fresh water is spread unevenly, so some regions have plenty and others face shortage.' },
  { id: 'y7-hum-274', q: 'Managing a water hazard well usually involves:', choices: ['Ignoring the problem', 'Planning strategies to reduce its impacts', 'Removing all rivers', 'Waiting for it to disappear'], answer: 1, explanation: 'Good management uses strategies to reduce the causes and impacts of a water hazard.' },
  // ── Place and Liveability (y7-hum-275 to y7-hum-302) ──
  { id: 'y7-hum-275', q: '"Liveability" is best defined as:', choices: ['How many people a city can hold', 'The height of a city’s buildings', 'How suitable and pleasant a place is to live in', 'The age of a town'], answer: 2, explanation: 'Liveability is an assessment of what a place is like to live in.' },
  { id: 'y7-hum-276', q: 'People’s ideas about what makes a place liveable can depend on their:', choices: ['Shoe size', 'Favourite colour', 'Height alone', 'Age, income and culture'], answer: 3, explanation: 'What people value in a place depends on factors like age, income, culture, lifestyle and beliefs.' },
  { id: 'y7-hum-277', q: 'An "objective" liveability measure is one that:', choices: ['Can be measured in numbers', 'Is just a personal opinion', 'Depends on your mood', 'Cannot be compared'], answer: 0, explanation: 'Objective measures are numerical and can be compared between places.' },
  { id: 'y7-hum-278', q: 'A "subjective" liveability measure is based on:', choices: ['Exact numbers', 'Personal opinion and feelings', 'Official statistics', 'Map scales'], answer: 1, explanation: 'Subjective measures reflect personal judgement, which can differ from person to person.' },
  { id: 'y7-hum-279', q: 'Which of these is an objective liveability factor?', choices: ['How pretty someone finds a view', 'A person’s favourite café', 'Access to healthcare and education', 'Feeling at home somewhere'], answer: 2, explanation: 'Access to services like healthcare and education can be measured, making it objective.' },
  { id: 'y7-hum-280', q: 'Which is generally used as a liveability criterion?', choices: ['Number of pets', 'Colour of the houses', 'Age of the mayor', 'Safety and stability'], answer: 3, explanation: 'Criteria include climate, environmental quality, safety, healthcare, education and infrastructure.' },
  { id: 'y7-hum-281', q: '"Infrastructure" that affects liveability includes things like:', choices: ['Roads, water and power supplies', 'Personal opinions', 'Ancient ruins only', 'The weather forecast'], answer: 0, explanation: 'Infrastructure — roads, transport, water and power — strongly affects how liveable a place is.' },
  { id: 'y7-hum-282', q: 'The unit uses which city as a case study of measuring liveability?', choices: ['Cairo', 'Melbourne', 'Athens', 'Rome'], answer: 1, explanation: 'The unit analyses Melbourne’s liveability using index data.' },
  { id: 'y7-hum-283', q: 'A common misconception is that the most liveable cities are always the:', choices: ['Cleanest and safest', 'Ones with good healthcare', 'Biggest and most famous', 'Ones with reliable transport'], answer: 2, explanation: 'The largest, most famous cities are not automatically the most liveable — indices weigh many factors.' },
  { id: 'y7-hum-284', q: 'The Victorian "20-minute neighbourhood" idea means being able to meet daily needs within a:', choices: ['20-minute drive on the freeway', '20-minute flight', '20-minute train to another city', '20-minute return walk from home'], answer: 3, explanation: 'The 20-minute neighbourhood means "living locally" — meeting daily needs within a 20-minute walk there and back.' },
  { id: 'y7-hum-285', q: 'Which problem can lower a city’s liveability?', choices: ['Traffic congestion', 'Clean air', 'Good schools', 'Reliable power'], answer: 0, explanation: 'Traffic congestion, along with inequality and environmental issues, can reduce liveability.' },
  { id: 'y7-hum-286', q: 'The PQE method could help describe the distribution of the world’s:', choices: ['Ancient Roman emperors', 'Most and least liveable cities', 'Egyptian gods', 'Chinese dynasties'], answer: 1, explanation: 'PQE helps describe where the most and least liveable cities are located.' },
  { id: 'y7-hum-287', q: 'Comparing "urban, rural and remote" areas is about differences in:', choices: ['The age of the Earth', 'Ancient history', 'How and where people live', 'The water cycle'], answer: 2, explanation: 'These terms compare living in cities, the countryside and isolated areas.' },
  { id: 'y7-hum-288', q: 'An "urban" area is best described as:', choices: ['An empty desert', 'A remote outback station', 'An ocean', 'A city or built-up town'], answer: 3, explanation: 'Urban areas are cities and towns with denser population and more built-up land.' },
  { id: 'y7-hum-289', q: '"Remote" areas are places that are:', choices: ['Far from cities and services', 'In the centre of a city', 'Always by the beach', 'Always the most liveable'], answer: 0, explanation: 'Remote areas are far from urban centres, often with more limited access to services.' },
  { id: 'y7-hum-290', q: 'A misconception is that rural and remote places are:', choices: ['Sometimes valued for other qualities', 'Automatically unliveable', 'Different in service access', 'Home to some communities'], answer: 1, explanation: 'Rural and remote areas are not automatically unliveable — they can have other valued qualities.' },
  { id: 'y7-hum-291', q: 'Sustainable improvements to liveability try to meet people’s needs while:', choices: ['Ignoring future generations', 'Using up all resources quickly', 'Protecting the environment for the future', 'Removing all services'], answer: 2, explanation: 'Sustainability means enhancing liveability without harming the environment for future generations.' },
  { id: 'y7-hum-292', q: 'Which is a correct statement about liveability?', choices: ['It means exactly the same to everyone', 'It only depends on city size', 'It cannot be measured at all', 'It can be judged with both objective and subjective measures'], answer: 3, explanation: 'Liveability uses both measurable (objective) and opinion-based (subjective) criteria, and varies by person.' },
  { id: 'y7-hum-293', q: '"Environmental quality" as a liveability factor includes:', choices: ['Clean air, land and water', 'The city’s population size', 'The mayor’s age', 'The number of shops'], answer: 0, explanation: 'Environmental quality covers clean air, land and water, plus green space and pleasant surroundings.' },
  { id: 'y7-hum-294', q: 'One aim of the 20-minute neighbourhood is to:', choices: ['Force everyone to drive further', 'Let people meet daily needs close to home', 'Ban walking in cities', 'Remove local shops'], answer: 1, explanation: 'The plan supports "living locally", reducing the need to travel far for daily needs.' },
  { id: 'y7-hum-295', q: 'Social inequality can affect liveability by:', choices: ['Making all services free', 'Improving every neighbourhood equally', 'Giving some groups poorer access to services', 'Removing all traffic'], answer: 2, explanation: 'Social inequality means some groups have less access to services, lowering their liveability.' },
  { id: 'y7-hum-296', q: 'Urban planners regularly assess liveability so they can:', choices: ['Stop cities from ever changing', 'Ignore what residents want', 'Make maps only', 'Meet the changing needs of communities'], answer: 3, explanation: 'Cities change and needs evolve, so planners assess liveability to keep meeting community needs.' },
  { id: 'y7-hum-297', q: 'Which of these is a subjective reason someone might find a place liveable?', choices: ['They feel a strong sense of belonging there', 'It has measured low crime rates', 'It has a counted number of hospitals', 'It has a recorded average rainfall'], answer: 0, explanation: 'A personal sense of belonging is subjective; the others are measurable, objective factors.' },
  { id: 'y7-hum-298', q: 'Access to healthcare and education are examples of liveability factors that are:', choices: ['Purely a matter of taste', 'Measurable and objective', 'Impossible to compare', 'Always the same everywhere'], answer: 1, explanation: 'Access to services can be counted and compared, making it objective.' },
  { id: 'y7-hum-299', q: 'Cultural connection to a place can influence a person’s:', choices: ['Exact height in centimetres', 'The shoe size they wear', 'Identity and sense of belonging', 'The year they were born'], answer: 2, explanation: 'Cultural connectedness shapes identity, belonging and how people perceive a place.' },
  { id: 'y7-hum-300', q: 'Sustainability in city planning is about balancing:', choices: ['Protecting the environment', 'Making a profit', 'The daily weather', 'Social, economic and environmental needs'], answer: 3, explanation: 'Sustainability considers social, economic and environmental dimensions together, not just one.' },
  { id: 'y7-hum-301', q: 'Which best describes why liveability rankings can differ between people?', choices: ['People value different things in a place', 'Everyone measures it the same way', 'Rankings are chosen at random', 'The size of the city'], answer: 0, explanation: 'Because people value different qualities, their judgements of liveability can differ.' },
  { id: 'y7-hum-302', q: 'A strategy to improve a city’s liveability might be to:', choices: ['Increase traffic congestion', 'Improve public transport and green spaces', 'Reduce access to healthcare', 'Remove all schools'], answer: 1, explanation: 'Better transport, services and green space are common strategies to enhance liveability.' },
  // Y7_HUM_MCQ_END
];

// ============================================================
//  Year 8 Humanities — HRS-anchored (302 items). Units: Medieval
//  Europe, Japan under the Shoguns, historical concepts/skills,
//  landscapes & processes, coasts, cities & urbanisation, geo
//  skills. Source: HRS Canvas unit pages + lesson decks 2026.
// ============================================================
const Y8_HUMANITIES: MCQ[] = [
  // -- Medieval Europe 1: Feudalism (1–14) --
  { id: 'y8-hum-1', q: 'Under feudalism, a lord granted a vassal land in exchange for:', choices: ['a share of church tithes', 'a written constitution', 'loyalty and military support', 'weekly market taxes'], answer: 2, explanation: 'The fief-for-loyalty exchange between lords and vassals was the core of the feudal system.' },
  { id: 'y8-hum-2', q: 'The plot of land a vassal received from a lord was called a:', choices: ['tithe', 'fief', 'manor house', 'sanctuary'], answer: 1, explanation: 'A fief was usually land, granted in return for the vassal’s loyal support.' },
  { id: 'y8-hum-3', q: 'At the very top of the medieval social hierarchy sat the:', choices: ['nobles', 'knights', 'serfs', 'monarch'], answer: 3, explanation: 'The monarch owned the land, administered the country and planned wars; everyone else ranked below.' },
  { id: 'y8-hum-4', q: 'The largest group in medieval society was the:', choices: ['peasants', 'nobles', 'knights', 'clergy'], answer: 0, explanation: 'Peasants did the bulk of the physical work, most of it farming, and far outnumbered every other group.' },
  { id: 'y8-hum-5', q: 'A serf was best described as:', choices: ['a travelling wool merchant', 'a peasant who worked a lord’s manor', 'a knight in training', 'a junior church official'], answer: 1, explanation: 'Serfs were peasants bound to a manor — not slaves who could be bought and sold, but not free to leave either.' },
  { id: 'y8-hum-6', q: 'Under feudalism, the person who received a fief and owed loyalty to a lord was the:', choices: ['serf', 'vassal', 'bishop', 'bailiff'], answer: 1, explanation: 'A vassal — usually a noble or knight, not a peasant — swore loyalty and service in return for protection and a fief.' },
  { id: 'y8-hum-7', q: 'Feudalism developed in Europe after the collapse of:', choices: ['the Byzantine Empire', 'the First Crusade', 'the Western Roman Empire', 'the Viking kingdoms'], answer: 2, explanation: 'After the Western Roman Empire fell in the 5th century CE, feudalism replaced Roman law as the way society was organised.' },
  { id: 'y8-hum-8', q: 'On the feudal hierarchy, knights ranked:', choices: ['above the monarch', 'below the peasants', 'alongside the clergy at the top', 'between the nobles and the peasants'], answer: 3, explanation: 'The order ran monarch, then nobles and church officials, then knights, then peasants and serfs.' },
  { id: 'y8-hum-9', q: 'Nobles lived on land granted to them, usually in:', choices: ['castle dungeons', 'manor houses', 'monastery cells', 'city apartments'], answer: 1, explanation: 'Nobles held fiefs from the monarch and lived in large manor houses on that land.' },
  { id: 'y8-hum-10', q: 'The relationship at the heart of feudalism was between:', choices: ['popes and emperors', 'merchants and guilds', 'lords and vassals', 'knights and squires'], answer: 2, explanation: 'Feudalism was a set of legal and military customs built on the lord–vassal bond.' },
  { id: 'y8-hum-11', q: 'Which task most likely filled a peasant’s day on a medieval manor?', choices: ['Farming the lord’s fields', 'Illuminating manuscripts', 'Leading cavalry charges', 'Judging court cases'], answer: 0, explanation: 'Most peasant work related to farming; manuscripts belonged to clergy, fighting to knights and justice to lords.' },
  { id: 'y8-hum-12', q: 'In a diagram of the feudal system, the arrows between lord and vassal would show:', choices: ['money flowing only upward', 'land one way, loyalty the other', 'everyone owning land equally', 'the Church outside the system'], answer: 1, explanation: 'Lords granted land downward; vassals returned loyalty, service and military support.' },
  { id: 'y8-hum-13', q: 'A medieval manor was:', choices: ['a lord’s estate with farmland and workers', 'a type of grand cathedral', 'a travelling market fair', 'a knight’s tournament ground'], answer: 0, explanation: 'The manor was the estate where a lord lived and serfs worked the land.' },
  { id: 'y8-hum-14', q: 'Who owned the land that was granted out as fiefs?', choices: ['The peasants who farmed it', 'The knights who defended it', 'The Church, in every case', 'The monarch'], answer: 3, explanation: 'The monarch owned the land on which they ruled and granted its use down the hierarchy.' },
  // -- Medieval Europe 2: Everyday life, law and order (15–30) --
  { id: 'y8-hum-15', q: 'Being locked in the stocks or pillory punished criminals through:', choices: ['public humiliation', 'permanent exile', 'loss of their land', 'trial by combat'], answer: 0, explanation: 'The stocks and pillory held offenders in public view so the community could witness their shame.' },
  { id: 'y8-hum-16', q: 'In medieval law, treason was a crime against:', choices: ['the village priest', 'the crown', 'a trade guild', 'a foreign king'], answer: 1, explanation: 'Treason was betrayal of one’s ruler; heresy was the equivalent offence against Church teaching.' },
  { id: 'y8-hum-17', q: 'Heresy was the medieval crime of:', choices: ['stealing silver from a church altar', 'refusing to pay the king’s taxes', 'beliefs that clashed with Church teaching', 'hunting deer on the lord’s land'], answer: 2, explanation: 'Heresy meant saying or doing things in serious conflict with Catholic teaching — a religious offence, not theft.' },
  { id: 'y8-hum-18', q: 'A criminal who reached a church could claim protection known as:', choices: ['chivalry', 'repentance', 'a fief', 'sanctuary'], answer: 3, explanation: 'Sanctuary applied specifically inside a church — not just any hiding place.' },
  { id: 'y8-hum-19', q: 'Trial by ordeal decided guilt through:', choices: ['a vote of twelve villagers', 'a painful test read as God’s judgement', 'the accused paying a fine', 'a written appeal to the king'], answer: 1, explanation: 'Ordeals such as hot iron or water were believed to reveal divine judgement — very different from a jury.' },
  { id: 'y8-hum-20', q: 'The knights’ code of conduct was called:', choices: ['bushido', 'canon law', 'chivalry', 'the ritsuryo'], answer: 2, explanation: 'Chivalry set out how knights should behave; bushido was the samurai equivalent in Japan.' },
  { id: 'y8-hum-21', q: 'The usual path to becoming a knight ran:', choices: ['page, then squire, then knight', 'squire, then page, then knight', 'monk, then squire, then knight', 'peasant, then knight, then lord'], answer: 0, explanation: 'Boys served as pages, then squires assisting a knight, before being knighted themselves.' },
  { id: 'y8-hum-22', q: 'Castles mattered in medieval Europe mainly as:', choices: ['hospitals for the poor', 'public schools', 'trading warehouses', 'centres of power and defence'], answer: 3, explanation: 'Castles projected a lord’s authority and defended territory — sieges were designed to break them.' },
  { id: 'y8-hum-23', q: 'Which castle feature was designed for defence?', choices: ['the moat and drawbridge', 'the tithe barn', 'the village green', 'the manor’s open fields'], answer: 0, explanation: 'Moats, drawbridges and battlements defended castles; sieges answered with trebuchets and battering rams.' },
  { id: 'y8-hum-24', q: 'Witchcraft accusations in medieval Europe were treated as:', choices: ['a private family matter', 'a paid entertainment', 'a crime tied to religious belief', 'a duty of every peasant'], answer: 2, explanation: 'Witchcraft was punished as a religious offence, reflecting the Church’s role in law and order.' },
  { id: 'y8-hum-25', q: 'Punishments were often carried out in public because:', choices: ['prisons held only nobles', 'kings enjoyed festivals', 'the Church banned private trials', 'shaming offenders warned onlookers'], answer: 3, explanation: 'Public punishment aimed to deter others by making an example of the offender.' },
  { id: 'y8-hum-26', q: 'Flogging as a medieval punishment meant:', choices: ['being whipped', 'paying one-tenth of earnings', 'exile from the kingdom', 'losing your land'], answer: 0, explanation: 'Flogging was whipping; banishment covered exile, and the tithe was a church payment, not a punishment.' },
  { id: 'y8-hum-27', q: 'Banishment punished a criminal by:', choices: ['forcing them on a crusade', 'branding their hand', 'expelling them from the community', 'binding them as a serf'], answer: 2, explanation: 'Banishment cast the offender out of the village or kingdom.' },
  { id: 'y8-hum-28', q: 'A repentant criminal was one who:', choices: ['escaped to another manor', 'showed sorrow and sought forgiveness', 'refused to attend church', 'paid a double fine'], answer: 1, explanation: 'Repentance — genuine remorse — could soften how Church-influenced justice treated an offender.' },
  { id: 'y8-hum-29', q: 'The purpose of chivalry included:', choices: ['loyal service and protecting the weak', 'maximising ransom profits', 'avoiding all combat', 'replacing Church teachings'], answer: 0, explanation: 'Chivalry bound knights to loyalty, bravery and protection — far more than courtly romance.' },
  { id: 'y8-hum-30', q: 'Which pair matches the crime with its target?', choices: ['heresy: an offence against the Church', 'treason: an offence against a neighbour', 'theft: an offence against the crown only', 'trespass: an offence against the Church'], answer: 0, explanation: 'Heresy offended Church teaching, treason the crown — the two most serious categories.' },
  // -- Medieval Europe 3: The Catholic Church (31–42) --
  { id: 'y8-hum-31', q: 'The tithe was:', choices: ['a tax collected by knights', 'a fee for using the lord’s mill', 'a voluntary donation at festivals', 'one-tenth of earnings paid to the Church'], answer: 3, explanation: 'The tithe supported the Church and clergy — set at one-tenth of produce or earnings, and not optional.' },
  { id: 'y8-hum-32', q: 'Excommunication cut a person off from:', choices: ['their family’s manor', 'the church community and its sacraments', 'the king’s court', 'paid work in towns'], answer: 1, explanation: 'The excommunicated lost communion, confession and — people believed — entry to heaven. It was not execution.' },
  { id: 'y8-hum-33', q: 'Canon law was the law of:', choices: ['the king’s court', 'the trade guilds', 'the Catholic Church', 'the village council'], answer: 2, explanation: 'Canon law was laid down by papal pronouncements, separate from royal law.' },
  { id: 'y8-hum-34', q: 'People "ordained for religious duties" in medieval Europe were the:', choices: ['clergy', 'vassals', 'serfs', 'guild masters'], answer: 0, explanation: 'The clergy — from the Pope down to parish priests — were ordained for religious duties.' },
  { id: 'y8-hum-35', q: 'The medieval Church kept its influence over daily life partly through:', choices: ['controlling the silk trade', 'electing every monarch', 'sacraments, sins and the tithe', 'commanding the feudal armies'], answer: 2, explanation: 'Sacraments, teaching on the deadly sins and the tithe kept the Church at the centre of everyday life.' },
  { id: 'y8-hum-36', q: 'Which shows the Church’s ECONOMIC power?', choices: ['crowning kings', 'preaching sermons', 'writing hymns', 'collecting tithes and owning land'], answer: 3, explanation: 'Tithes and vast landholdings made the Church wealthy; crowning kings was political power.' },
  { id: 'y8-hum-37', q: 'The Church helped unify medieval Europe because:', choices: ['almost everyone shared its religion', 'it commanded every royal army', 'it printed the daily news', 'it owned every castle'], answer: 0, explanation: 'Christianity was the dominant religion — kings, lords, knights and peasants were all affected by Church rulings.' },
  { id: 'y8-hum-38', q: 'The COMA method is used in class to analyse:', choices: ['graph scales', 'historical sources', 'coastal landforms', 'population pyramids'], answer: 1, explanation: 'COMA scaffolds source analysis — used on sources such as the Genpei battle screens and Church documents.' },
  { id: 'y8-hum-39', q: 'The seven deadly sins mattered in medieval life because they:', choices: ['listed crimes against the king', 'set trading rules for guilds', 'described siege tactics', 'guided the Church’s moral teaching'], answer: 3, explanation: 'The sins were part of how the Church shaped everyday behaviour and belief.' },
  { id: 'y8-hum-40', q: 'A person excommunicated by the medieval Church would most fear:', choices: ['losing skill at arms', 'paying double tithes forever', 'losing entry to heaven', 'being made a vassal'], answer: 2, explanation: 'Cut off from the sacraments, the excommunicated believed their soul was in danger.' },
  { id: 'y8-hum-41', q: 'According to the unit, the Church often maintained its authority through:', choices: ['wealth and fear', 'elections and debates', 'trade and exploration', 'science and medicine'], answer: 0, explanation: 'The COMA task examines how wealth and fear underpinned the medieval Church’s power.' },
  { id: 'y8-hum-42', q: 'At the head of the medieval Catholic Church stood:', choices: ['the Holy Roman Emperor', 'the Pope', 'the Archbishop of Paris', 'the King of England'], answer: 1, explanation: 'Papal pronouncements set canon law; the Pope led the clergy hierarchy.' },
  // -- Medieval Europe 4: The Crusades (43–54) --
  { id: 'y8-hum-43', q: 'The Crusades were wars fought between:', choices: ['England and France over the throne', 'popes and emperors over taxes', 'knights and peasants over land', 'Christians and Muslims over the Holy Land'], answer: 3, explanation: 'The Crusades (1096–1291) were fought for control of the Holy Land.' },
  { id: 'y8-hum-44', q: 'The Crusades took place between:', choices: ['1096 and 1291', '1347 and 1351', '1180 and 1185', '966 and 1066'], answer: 0, explanation: 'The Crusades ran 1096–1291; 1347–1351 is the Black Death and 1180–1185 the Genpei War in Japan.' },
  { id: 'y8-hum-45', q: 'The Holy Land fought over in the Crusades is mostly in:', choices: ['today’s Spain and Portugal', 'today’s France and Belgium', 'today’s Israel and Palestine', 'today’s Turkey and Greece'], answer: 2, explanation: 'The Holy Land sits in the Middle East, in territory now mostly made up of Israel and Palestine.' },
  { id: 'y8-hum-46', q: 'Who called for the First Crusade?', choices: ['Tokugawa Ieyasu', 'Pope Urban II', 'William the Conqueror', 'Emperor Constantine'], answer: 1, explanation: 'Pope Urban II called for the crusade and encouraged people to join — though he did not lead it in battle.' },
  { id: 'y8-hum-47', q: 'The outcome of the First Crusade (1096–1099) was:', choices: ['Muslim forces captured Rome', 'a lasting peace treaty', 'the fall of Constantinople', 'Christian forces took Jerusalem'], answer: 3, explanation: 'The First Crusade was the most successful — Jerusalem was taken, at a massive human cost.' },
  { id: 'y8-hum-48', q: 'Which best describes who joined the Crusades?', choices: ['people from many social classes', 'knights and nobles only', 'clergy only', 'convicted criminals only'], answer: 0, explanation: 'People of many classes joined — for salvation, land, wealth or adventure.' },
  { id: 'y8-hum-49', q: 'A pilgrimage is:', choices: ['a holy war', 'a church tax', 'a journey to a sacred place', 'a knight’s oath'], answer: 2, explanation: 'Pilgrimages to the Holy Land came first; the unit traces how holy wars followed.' },
  { id: 'y8-hum-50', q: 'Compared with later Crusades, the First Crusade was:', choices: ['the least organised failure', 'the most successful for the Christians', 'the only one without fighting', 'the last one fought'], answer: 1, explanation: 'Later campaigns fared worse; the First achieved its goal of taking Jerusalem.' },
  { id: 'y8-hum-51', q: 'One long-term consequence of the Crusades was:', choices: ['the end of Christianity in Europe', 'the immediate collapse of feudalism', 'permanent Christian rule of Jerusalem', 'increased trade between Europe and the East'], answer: 3, explanation: 'Contact with the East boosted trade and the growth of towns; Jerusalem did not stay in Christian hands.' },
  { id: 'y8-hum-52', q: 'In the short term, the Crusades tended to STRENGTHEN:', choices: ['the power of the Catholic Church', 'the power of serfs', 'Viking raiders', 'the Roman Empire'], answer: 0, explanation: 'The unit examines the Crusades’ role in strengthening the Church’s power and influence.' },
  { id: 'y8-hum-53', q: 'Which is an ECONOMIC consequence of the Crusades?', choices: ['new alliances between kings', 'changed religious attitudes', 'growth in trade between East and West', 'stories of knightly heroism'], answer: 2, explanation: 'The unit sorts consequences into political, economic and social — trade growth is economic.' },
  { id: 'y8-hum-54', q: 'Pope Urban II raised a crusading army partly by promising:', choices: ['a wage for every soldier', 'spiritual reward for joining', 'free land in France', 'an end to the tithe'], answer: 1, explanation: 'Crusaders believed joining earned religious merit — a key reason so many people took part.' },
  // -- Medieval Europe 5: The Black Death (55–66) --
  { id: 'y8-hum-55', q: 'The Black Death swept through Europe in:', choices: ['1096–1099', '1156–1160', '1600–1603', '1347–1351'], answer: 3, explanation: 'The plague years were 1347–1351; 1096–1099 is the First Crusade and 1156–1160 covers Japan’s Hogen and Heiji rebellions.' },
  { id: 'y8-hum-56', q: 'The Black Death killed roughly what share of Europe’s population?', choices: ['one-third', 'one-tenth', 'nine-tenths', 'one-hundredth'], answer: 0, explanation: 'An estimated one in three Europeans died between 1347 and 1351.' },
  { id: 'y8-hum-57', q: 'The Black Death was caused by:', choices: ['poisoned town wells', 'the bacterium Yersinia pestis', 'bad air from swamps', 'a curse on trade ships'], answer: 1, explanation: 'People at the time blamed bad air or divine punishment, but the cause was the bacterium Yersinia pestis.' },
  { id: 'y8-hum-58', q: 'The plague spread quickly through Europe mainly along:', choices: ['mountain hiking paths', 'crusader castle walls', 'trade routes and crowded towns', 'royal hunting forests'], answer: 2, explanation: 'Trade routes carried the plague between regions; crowded, unsanitary towns let it spread fast.' },
  { id: 'y8-hum-59', q: 'Buboes were:', choices: ['the doctors who treated plague', 'prayers said for the dead', 'the ships that carried plague', 'swellings that marked bubonic plague'], answer: 3, explanation: 'Buboes were the painful swellings of bubonic plague — the disease’s most famous symptom.' },
  { id: 'y8-hum-60', q: 'Which lists the three forms of plague studied in the unit?', choices: ['bubonic, pneumonic, septicemic', 'bubonic, malaria, cholera', 'pneumonic, typhoid, leprosy', 'septicemic, smallpox, measles'], answer: 0, explanation: 'The plague took bubonic, pneumonic and septicemic forms; the other diseases are unrelated.' },
  { id: 'y8-hum-61', q: 'Flagellants responded to the Black Death by:', choices: ['burning infected houses', 'whipping themselves to seek God’s forgiveness', 'opening quarantine hospitals', 'fleeing to mountain monasteries'], answer: 1, explanation: 'Flagellants were radical Christians who whipped themselves, hoping to atone for the sins they believed caused the plague.' },
  { id: 'y8-hum-62', q: 'With no understanding of germs, medieval responses to plague included:', choices: ['antibiotics and vaccination', 'boiling all drinking water by law', 'religious rituals, remedies and quarantine', 'closing every port permanently'], answer: 2, explanation: 'People relied on religious rituals, folk remedies and quarantine measures.' },
  { id: 'y8-hum-63', q: 'One major effect of the Black Death on feudalism was:', choices: ['serfs became more tightly bound', 'lords gained extra workers', 'a new class joined the hierarchy', 'labour shortages weakened the system'], answer: 3, explanation: 'With workers scarce, survivors could demand better conditions — helping to weaken the feudal system.' },
  { id: 'y8-hum-64', q: 'How did the Black Death affect the Catholic Church?', choices: ['It gained unquestioned authority', 'Its legitimacy was weakened', 'It was abolished across Europe', 'It first introduced the tithe'], answer: 1, explanation: 'Prayers and rituals failed to stop the plague, damaging the Church’s standing.' },
  { id: 'y8-hum-65', q: 'Medieval towns were vulnerable to plague because of:', choices: ['their thick stone walls', 'too many hospitals', 'crowding and poor living conditions', 'unusually low populations'], answer: 2, explanation: 'Population growth and poor living conditions in cities helped the plague spread rapidly.' },
  { id: 'y8-hum-66', q: 'Which statement about the Black Death’s spread is accurate?', choices: ['It stayed inside Europe only', 'It affected only England', 'It spread only after 1400', 'It moved through Asia, Europe and Africa'], answer: 3, explanation: 'The unit notes the pandemic spread through Asia, Europe and Africa.' },
  // -- Japan 1: Geography and early beliefs (67–78) --
  { id: 'y8-hum-67', q: 'Japan is an archipelago, meaning:', choices: ['a mountain range', 'a walled empire', 'a chain of islands', 'a frozen plain'], answer: 2, explanation: 'Japan is a chain of over 3000 islands in the Pacific, formed from underwater mountain peaks.' },
  { id: 'y8-hum-68', q: 'The four main islands of Japan are Honshu, Shikoku, Kyushu and:', choices: ['Hokkaido', 'Okinawa', 'Taiwan', 'Sakhalin'], answer: 0, explanation: 'Most people have always lived on the four main islands: Honshu, Shikoku, Kyushu and Hokkaido.' },
  { id: 'y8-hum-69', q: 'About how much of Japan is covered by mountains and steep hills?', choices: ['15%', '25%', '50%', '75%'], answer: 3, explanation: 'Roughly three-quarters of Japan is mountainous — and only about 15% can be farmed.' },
  { id: 'y8-hum-70', q: 'Because farmland was scarce, early Japanese communities mostly settled:', choices: ['on high mountain ridges', 'in coastal plains and river valleys', 'deep in inland forests', 'on the northern ice fields'], answer: 1, explanation: 'Flatter land in valleys and coastal plains — like the Kanto and Kansai plains — suited farming and settlement.' },
  { id: 'y8-hum-71', q: 'Japan sits on the Ring of Fire, making it prone to:', choices: ['droughts and dust storms', 'blizzards and avalanches', 'earthquakes and tsunamis', 'cyclones and floods only'], answer: 2, explanation: 'The plate boundary brings earthquakes, volcanic eruptions and tsunamis — the 2011 Tohoku disaster is a modern example.' },
  { id: 'y8-hum-72', q: 'The word "shogun" combines Japanese words meaning:', choices: ['commander and troops', 'emperor and palace', 'island and sea', 'sword and honour'], answer: 0, explanation: 'Sho means commander and gun means troops — fitting for Japan’s military rulers.' },
  { id: 'y8-hum-73', q: 'In Shinto belief, kami are:', choices: ['a single all-powerful god', 'the emperor’s tax officials', 'written legal codes', 'spirits linked to nature and ancestors'], answer: 3, explanation: 'Kami are the many spiritual beings of rivers, mountains, trees and ancestors — not one god.' },
  { id: 'y8-hum-74', q: 'In Japan’s creation story, the islands were formed by:', choices: ['Amaterasu hurling stones from heaven', 'Izanagi and Izanami with a jewelled spear', 'a giant catfish stirring the sea', 'Buddha raising the ocean floor'], answer: 1, explanation: 'Drops falling from the divine siblings’ spear formed Onogoro-shima, the first island of the archipelago.' },
  { id: 'y8-hum-75', q: 'The imperial family claimed descent from:', choices: ['Amaterasu, the sun goddess', 'Izanami, the moon goddess', 'the first shogun', 'Confucius'], answer: 0, explanation: 'The Yamato clan claimed descent from sun goddess Amaterasu, giving emperors a sacred status.' },
  { id: 'y8-hum-76', q: 'The sea around Japan shaped its development by:', choices: ['preventing any contact with Asia', 'making farming impossible', 'allowing selective adoption of foreign ideas', 'forcing constant emigration'], answer: 2, explanation: 'The sea barrier let Japan choose which Chinese and Korean ideas to adopt while staying protected from invasion.' },
  { id: 'y8-hum-77', q: 'Which set of ideas reached Japan from China and Korea?', choices: ['gunpowder, banks and printing presses', 'democracy, coins and law courts', 'castles, knights and tithes', 'rice farming, writing and Buddhism'], answer: 3, explanation: 'Korean kingdoms such as Baekje and Silla introduced Buddhism and Chinese writing; wet-rice farming and iron tools also crossed the sea.' },
  { id: 'y8-hum-78', q: 'Buddhism officially arrived in Japan around:', choices: ['1192 CE', '552 CE', '30,000 BCE', '1868 CE'], answer: 1, explanation: 'Buddhism entered Japan around 552 CE via Korea; 1192 is Yoritomo’s shogun title and 1868 the Meiji Restoration.' },
  // -- Japan 2: Nara and Heian periods (79–92) --
  { id: 'y8-hum-79', q: 'Japan’s first permanent capital, established in 710 CE, was:', choices: ['Nara', 'Edo', 'Kamakura', 'Osaka'], answer: 0, explanation: 'The Nara period (710–794) began when the court settled its first permanent capital at Nara.' },
  { id: 'y8-hum-80', q: 'Nara’s city layout was modelled on:', choices: ['the Roman city of Pompeii', 'the Korean capital at Silla', 'the Chinese capital Chang’an', 'the temple city of Angkor'], answer: 2, explanation: 'Nara was designed to reflect the orderly layout of Tang China’s capital, Chang’an.' },
  { id: 'y8-hum-81', q: 'In 794 CE the capital moved to Heian-kyo, known today as:', choices: ['Tokyo', 'Hiroshima', 'Nagasaki', 'Kyoto'], answer: 3, explanation: 'Heian-kyo is modern Kyoto; Edo is the older name for Tokyo.' },
  { id: 'y8-hum-82', q: 'A key reason the capital moved to Heian-kyo was to:', choices: ['escape repeated earthquakes', 'reduce the influence of Nara’s Buddhist monasteries', 'move closer to China for trade', 'avoid Mongol invasions'], answer: 1, explanation: 'The relocation aimed to reduce the political influence of the powerful Buddhist monasteries in Nara.' },
  { id: 'y8-hum-83', q: 'Todai-ji, completed in 752 CE, housed:', choices: ['the emperor’s throne room', 'Japan’s first library', 'a massive bronze statue of the Buddha', 'the shogun’s army barracks'], answer: 2, explanation: 'Emperor Shomu ordered the great temple; its Daibutsu symbolised the unity of state and religion.' },
  { id: 'y8-hum-84', q: 'The Fujiwara clan controlled Heian government mainly through:', choices: ['marriage politics and acting as regents', 'winning naval battles', 'leading Buddhist monasteries', 'commanding samurai armies'], answer: 0, explanation: 'The Fujiwara married into the imperial family and ruled as regents rather than taking the throne.' },
  { id: 'y8-hum-85', q: 'In 858 CE, Fujiwara no Yoshifusa became the first:', choices: ['shogun', 'emperor from outside the imperial line', 'Buddhist abbot at court', 'non-imperial regent'], answer: 3, explanation: 'Yoshifusa acted on behalf of a child emperor — the first regent not from the imperial family.' },
  { id: 'y8-hum-86', q: 'The Tale of Genji (c. 1008) is often called:', choices: ['Japan’s first legal code', 'the world’s first novel', 'a manual for samurai', 'a map of the Silk Road'], answer: 1, explanation: 'Murasaki Shikibu’s tale of court life is often described as the world’s first novel.' },
  { id: 'y8-hum-87', q: 'The Tale of Genji was written by:', choices: ['a Buddhist monk', 'Emperor Shomu', 'Murasaki Shikibu, a noblewoman', 'a Chinese ambassador'], answer: 2, explanation: 'The noblewoman Murasaki Shikibu completed it around 1008 CE, capturing Heian court values.' },
  { id: 'y8-hum-88', q: 'The kana script, developed in the early 900s:', choices: ['let Japanese literature flourish', 'replaced spoken Japanese', 'was used only for tax records', 'was banned at court'], answer: 0, explanation: 'Kana adapted Chinese characters into a phonetic system, opening the way for works like The Tale of Genji.' },
  { id: 'y8-hum-89', q: 'The Kojiki (712) and Nihon Shoki (720) recorded:', choices: ['samurai battle tactics', 'rules for rice farming', 'collections of Chinese poetry', 'Shinto myths and imperial divine origins'], answer: 3, explanation: 'These early records documented Shinto myths and the imperial family’s divine descent, strengthening its authority.' },
  { id: 'y8-hum-90', q: 'Prince Shotoku’s constitution of 604 CE drew on:', choices: ['Roman law', 'the code of chivalry', 'Confucian ideals from China', 'Viking assembly customs'], answer: 2, explanation: 'Shotoku’s constitution laid the groundwork for a Chinese-style bureaucracy inspired by Confucian ideals.' },
  { id: 'y8-hum-91', q: 'During the Heian period, real political power sat with:', choices: ['the emperor alone', 'the aristocracy, especially the Fujiwara', 'peasant councils', 'foreign governors'], answer: 1, explanation: 'The emperor stayed a spiritual figure while aristocratic families — above all the Fujiwara — ran government.' },
  { id: 'y8-hum-92', q: 'Heian court culture is best described as:', choices: ['military, harsh and frugal', 'seafaring and commercial', 'nomadic and tribal', 'refined, poetic and ceremonial'], answer: 3, explanation: 'Court nobles prized elegance, poetry and ritual — while paying little attention to the provinces.' },
  // -- Japan 3: The Genpei War and the Kamakura Shogunate (93–104) --
  { id: 'y8-hum-93', q: 'Shoen were:', choices: ['large private estates owned by nobles', 'imperial warships', 'Buddhist temple bells', 'samurai training schools'], answer: 0, explanation: 'Nobles grew wealthy collecting taxes from peasants on their shoen estates.' },
  { id: 'y8-hum-94', q: 'Noble families built private armies because:', choices: ['the emperor ordered them to', 'China threatened invasion', 'the court neglected the provinces', 'monks demanded protection'], answer: 2, explanation: 'With the court absorbed in Heian-kyo, provincial nobles protected their own estates — their armies were led by generals with samurai soldiers.' },
  { id: 'y8-hum-95', q: 'The Genpei War (1180–1185) was fought between:', choices: ['Japan and Korea', 'the Taira and Minamoto clans', 'samurai and peasants', 'Buddhists and Shintoists'], answer: 1, explanation: 'The two great clans fought for control of the imperial court across land and sea.' },
  { id: 'y8-hum-96', q: 'The Genpei War is best classified as:', choices: ['a foreign invasion', 'a religious crusade', 'a peasant revolt', 'a civil war'], answer: 3, explanation: 'It was a conflict between groups within the same country fighting for power — a civil war.' },
  { id: 'y8-hum-97', q: 'The decisive final battle of the Genpei War, Dan-no-ura, was fought:', choices: ['at sea', 'on a mountain pass', 'inside Heian-kyo', 'on the Kanto plain'], answer: 0, explanation: 'Dan-no-ura was a naval battle — it ended the war and the Taira clan.' },
  { id: 'y8-hum-98', q: 'Who won the Genpei War?', choices: ['the Taira clan', 'the Fujiwara clan', 'the Minamoto clan', 'the Soga clan'], answer: 2, explanation: 'The Minamoto victory ended Taira power and led to the Kamakura Shogunate.' },
  { id: 'y8-hum-99', q: 'In 1192, Emperor Go-Toba granted Minamoto no Yoritomo the title:', choices: ['Daimyo of Kyoto', 'Sei-i Taishogun', 'Emperor of Japan', 'Regent of Nara'], answer: 1, explanation: 'Go-Toba, who had supported the Minamoto, made Yoritomo Sei-i Taishogun — with legal authority to rule on the emperor’s behalf.' },
  { id: 'y8-hum-100', q: 'Sei-i Taishogun translates roughly as:', choices: ['Divine Wind Admiral', 'Protector of Temples', 'Lord of the Rice Lands', 'Barbarian-subduing Great General'], answer: 3, explanation: 'The grand title gave Yoritomo the power to govern in the emperor’s name.' },
  { id: 'y8-hum-101', q: 'Yoritomo’s new government was called the:', choices: ['Ashikaga Shogunate', 'Tokugawa Shogunate', 'Kamakura Shogunate', 'Meiji Government'], answer: 2, explanation: 'The Kamakura Shogunate (from 1192) was Japan’s first military government.' },
  { id: 'y8-hum-102', q: 'After 1192, the emperor’s role became:', choices: ['commander of all armies', 'chief tax collector', 'head of the merchant class', 'ceremonial and spiritual figurehead'], answer: 3, explanation: 'The emperor still existed but real power passed to the shogun.' },
  { id: 'y8-hum-103', q: 'Under the shoguns, Japan’s government shifted from:', choices: ['feudal rule to elected assemblies', 'centralised imperial rule to feudal rule', 'clan rule to direct Chinese control', 'military rule back to court rule'], answer: 1, explanation: 'The Chinese-inspired centralised system of Nara and Heian gave way to a decentralised feudal system.' },
  { id: 'y8-hum-104', q: 'Why was the Genpei War a turning point?', choices: ['military rulers replaced the imperial court', 'China conquered and ruled Japan', 'the emperor gained absolute power', 'Buddhism was banned across Japan'], answer: 0, explanation: 'Power moved from the imperial court to a military government, elevating the samurai class.' },
  // -- Japan 4: Feudal structure and the shogunate (105–114) --
  { id: 'y8-hum-105', q: 'In Japan’s feudal hierarchy, the daimyo were:', choices: ['powerful lords, vassals to the shogun', 'travelling rice merchants', 'the emperor’s priests', 'the lowest-ranked soldiers'], answer: 0, explanation: 'Daimyo held land and power under the shogun; samurai served the daimyo — not the other way around.' },
  { id: 'y8-hum-106', q: 'Samurai served:', choices: ['the merchant guilds', 'their daimyo', 'foreign traders', 'the peasants'], answer: 1, explanation: 'Samurai were loyal to their daimyo, living by the code of bushido.' },
  { id: 'y8-hum-107', q: 'Who held REAL power in shogunate Japan?', choices: ['the emperor', 'the merchants', 'the Fujiwara regents', 'the shogun'], answer: 3, explanation: 'The emperor kept only symbolic power; the shogun ruled in his name.' },
  { id: 'y8-hum-108', q: 'Which pairing correctly matches Japan with Europe?', choices: ['samurai and serfs', 'shogun and peasants', 'daimyo and noble lords', 'ronin and monarchs'], answer: 2, explanation: 'Daimyo were the great landholding lords, like Europe’s nobles; samurai are compared with knights.' },
  { id: 'y8-hum-109', q: 'Women of the samurai class were expected to:', choices: ['manage households and uphold family honour', 'fight in every battle', 'run market stalls', 'serve in the imperial bureaucracy'], answer: 0, explanation: 'Noble and samurai wives managed households and honour; some were also trained in martial skills to defend their homes.' },
  { id: 'y8-hum-110', q: 'Peasant women in shogunate Japan typically:', choices: ['lived inside castle towers', 'worked the fields alongside men', 'trained as samurai', 'owned large shoen estates'], answer: 1, explanation: 'Peasant women worked the fields, raised children and contributed to household income.' },
  { id: 'y8-hum-111', q: 'The Ashikaga Shogunate collapsed in:', choices: ['1185', '1868', '1573', '1600'], answer: 2, explanation: 'The Ashikaga (Muromachi) Shogunate fell in 1573; 1600 is Sekigahara and 1868 the Meiji Restoration.' },
  { id: 'y8-hum-112', q: 'The Ashikaga Shogunate is also known as the:', choices: ['Kamakura Shogunate', 'Edo Shogunate', 'Heian Shogunate', 'Muromachi Shogunate'], answer: 3, explanation: 'Ashikaga and Muromachi are two names for the same shogunate.' },
  { id: 'y8-hum-113', q: 'A leading explanation for the Ashikaga Shogunate’s collapse is:', choices: ['a Chinese invasion fleet', 'daimyo acting independently of the shogun', 'the banning of samurai', 'a court ruling from Nara'], answer: 1, explanation: 'The unit’s investigation weighs the daimyo’s growing independence against weak leadership, economic unrest and uprisings.' },
  { id: 'y8-hum-114', q: 'Which lists the shogunate’s military hierarchy from the top down?', choices: ['shogun, daimyo, samurai', 'daimyo, shogun, samurai', 'samurai, daimyo, shogun', 'shogun, samurai, daimyo'], answer: 0, explanation: 'The shogun commanded the daimyo lords, whose warriors were the samurai.' },
  // -- Japan 5: Samurai and Bushido (115–126) --
  { id: 'y8-hum-115', q: 'Bushido was the samurai’s:', choices: ['curved sword', 'battle armour', 'code of behaviour', 'family shrine'], answer: 2, explanation: 'Bushido was a code of conduct, not a fighting style or weapon.' },
  { id: 'y8-hum-116', q: 'Bushido demanded honour, martial skill, thrift and above all:', choices: ['growing personal wealth', 'writing court poetry', 'travelling to China', 'loyalty, even to death'], answer: 3, explanation: 'Loyalty to one’s daimyo — even at the cost of life — sat at the heart of bushido.' },
  { id: 'y8-hum-117', q: 'Beyond fighting, samurai were expected to be educated in:', choices: ['shipbuilding and navigation', 'writing, poetry and philosophy', 'banking and bookkeeping', 'farming and irrigation'], answer: 1, explanation: 'Samurai trained in martial arts but were also expected to be cultured and educated.' },
  { id: 'y8-hum-118', q: 'Seppuku was:', choices: ['ritual suicide after dishonour', 'execution by the daimyo', 'exile to a distant island', 'a purification rite before battle'], answer: 0, explanation: 'A dishonoured samurai might choose seppuku — death over disgrace — rather than live with shame.' },
  { id: 'y8-hum-119', q: 'A ronin was a samurai who:', choices: ['ruled a province', 'became a monk', 'had no master', 'guarded the emperor'], answer: 2, explanation: 'Ronin were masterless samurai.' },
  { id: 'y8-hum-120', q: 'The Tale of the Heike tells the story of:', choices: ['the Meiji Restoration', 'the building of Todai-ji', 'the Mongol invasions', 'the Genpei War'], answer: 3, explanation: 'The epic recounts the Taira–Minamoto war and the rise and fall of powerful families.' },
  { id: 'y8-hum-121', q: 'The Tale of the Heike was first passed on by:', choices: ['Buddhist monks reciting it aloud', 'printed newspapers', 'court painters', 'Chinese merchants'], answer: 0, explanation: 'It was an oral tradition carried by monks and later written down in the 13th century.' },
  { id: 'y8-hum-122', q: 'The Tale of the Heike explores themes of:', choices: ['romance at the Heian court', 'honour, loyalty and downfall', 'the four seasons of farming', 'trade voyages to the Dutch'], answer: 1, explanation: 'Its themes are loyalty, honour, bravery and the fall of the powerful — a mirror of samurai values.' },
  { id: 'y8-hum-123', q: 'Samurai are most often compared with which European group?', choices: ['serfs', 'clergy', 'guild merchants', 'knights'], answer: 3, explanation: 'The unit sets samurai beside medieval knights — warrior classes bound by codes of honour.' },
  { id: 'y8-hum-124', q: 'One similarity between bushido and chivalry is that both:', choices: ['required warriors to vow poverty', 'were written down by monarchs', 'bound warriors to loyalty and honour', 'applied mainly to farm workers'], answer: 2, explanation: 'Both codes tied a warrior class to ideals of loyalty, bravery and honour.' },
  { id: 'y8-hum-125', q: '"Death over disgrace" summarises:', choices: ['the samurai attitude to honour', 'a merchant’s trading motto', 'the peasants’ tax slogan', 'the emperor’s coronation oath'], answer: 0, explanation: 'Bushido made a dishonourable life worse than death — hence seppuku.' },
  { id: 'y8-hum-126', q: 'Choosing seppuku over capture shows bushido valued:', choices: ['wealth above family', 'honour above life itself', 'victory above loyalty', 'comfort above duty'], answer: 1, explanation: 'Honour outranked survival in the samurai code.' },
  // -- Japan 6: The Tokugawa Shogunate and Edo (127–138) --
  { id: 'y8-hum-127', q: 'Tokugawa Ieyasu rose to power after winning the Battle of:', choices: ['Dan-no-ura (1185)', 'Nara (1573)', 'Sekigahara (1600)', 'Osaka (1868)'], answer: 2, explanation: 'Victory at Sekigahara in 1600 let Ieyasu unify Japan; he took the shogun title in 1603.' },
  { id: 'y8-hum-128', q: 'Ieyasu was granted the title of shogun in:', choices: ['1603', '1600', '1868', '1192'], answer: 0, explanation: 'The battle was 1600; the formal title came in 1603 — the unit uses both dates for the start of Tokugawa rule.' },
  { id: 'y8-hum-129', q: 'The Tokugawa Shogunate gave Japan:', choices: ['constant civil war', 'rule by foreign governors', 'a powerless shogun', 'over 250 years of stability'], answer: 3, explanation: 'Strict controls created order and stability for more than 250 years.' },
  { id: 'y8-hum-130', q: 'Sankin-kotai required daimyo to:', choices: ['pay a yearly tax of rice to Edo', 'attend the shogun in alternate periods', 'convert their households to Buddhism', 'disband their samurai armies'], answer: 1, explanation: 'Alternate attendance kept daimyo close to the shogun and their wealth drained by travel — a control measure, not a tax.' },
  { id: 'y8-hum-131', q: 'Sakoku was the Tokugawa policy of:', choices: ['promoting foreign trade', 'compulsory schooling', 'isolation from the outside world', 'building coastal castles'], answer: 2, explanation: 'Sakoku (1633–1853) forbade Japanese people leaving and foreigners entering Japan.' },
  { id: 'y8-hum-132', q: 'Under sakoku, the penalty for leaving or entering Japan was:', choices: ['death', 'a small fine', 'exile to Hokkaido', 'loss of samurai rank'], answer: 0, explanation: 'The isolation policy carried the death penalty — contact with the outside world was heavily restricted.' },
  { id: 'y8-hum-133', q: 'The official Tokugawa class order, from top to bottom, ran:', choices: ['merchants, samurai, peasants, artisans', 'samurai, merchants, peasants, artisans', 'peasants, samurai, artisans, merchants', 'samurai, peasants, artisans, merchants'], answer: 3, explanation: 'Samurai ranked first, then peasants as food producers, then artisans, with merchants officially last.' },
  { id: 'y8-hum-134', q: 'Merchants ranked lowest in Tokugawa society because:', choices: ['they were the poorest class', 'they were seen as producing nothing', 'they refused to pay taxes', 'they came from foreign lands'], answer: 1, explanation: 'Status followed ideas about production, not wealth — many merchants were in fact rich.' },
  { id: 'y8-hum-135', q: 'Edo, the shogunate’s bustling centre, is modern-day:', choices: ['Kyoto', 'Nara', 'Tokyo', 'Osaka'], answer: 2, explanation: 'Edo became Tokyo; Heian-kyo is modern Kyoto.' },
  { id: 'y8-hum-136', q: 'Which cultural forms flourished in the Edo period?', choices: ['kabuki, ukiyo-e and haiku', 'opera, sonnets and oil painting', 'mosaics, frescoes and chariot races', 'stained glass, tapestries and plainsong'], answer: 0, explanation: 'Edo’s peace let kabuki theatre, woodblock prints, haiku, Noh and bonsai flourish.' },
  { id: 'y8-hum-137', q: 'Ukiyo-e were:', choices: ['tea ceremonies', 'castle gardens', 'sword-fighting schools', 'woodblock prints'], answer: 3, explanation: 'Ukiyo-e woodblock prints were a signature art form of Edo culture.' },
  { id: 'y8-hum-138', q: 'The Tokugawa edicts aimed to:', choices: ['encourage foreign settlement', 'fix each class’s role to keep order', 'abolish the samurai', 'hand power back to the emperor'], answer: 1, explanation: 'The edicts controlled all social classes and curbed the daimyo — creating order, and protecting Tokugawa power.' },
  // -- Japan 7: Fall of the Shogunate and the Meiji Restoration (139–144) --
  { id: 'y8-hum-139', q: 'Japan’s isolation period ended after the arrival of:', choices: ['a Mongol invasion force', 'Portuguese missionaries', 'a Russian army', 'an American fleet'], answer: 3, explanation: 'The American fleet’s arrival was the short-term trigger that forced Japan open.' },
  { id: 'y8-hum-140', q: 'A long-term INTERNAL cause of the shogunate’s fall was:', choices: ['repeated volcanic eruptions', 'a single failed rice harvest', 'a rigid class system blocking mobility', 'a losing war with Korea'], answer: 2, explanation: 'Lack of social mobility brought social and economic stagnation — pressure that built for decades.' },
  { id: 'y8-hum-141', q: 'The Meiji Restoration (1868) restored power to:', choices: ['the emperor', 'the shogun', 'the daimyo', 'the samurai'], answer: 0, explanation: 'The Restoration ended the shogunate and returned the emperor to the head of government.' },
  { id: 'y8-hum-142', q: 'After the Meiji Restoration, Japan pursued:', choices: ['deeper isolation', 'rule by the Tokugawa again', 'a return to Heian court life', 'westernisation and modernisation'], answer: 3, explanation: 'Meiji Japan modernised and westernised its economy, politics and society.' },
  { id: 'y8-hum-143', q: 'The Meiji Restoration is dated to:', choices: ['1853', '1573', '1868', '1600'], answer: 2, explanation: '1868 marks the Restoration; 1853 ends sakoku’s span, 1573 is the Ashikaga collapse and 1600 Sekigahara.' },
  { id: 'y8-hum-144', q: 'Which was a consequence of the Meiji Restoration?', choices: ['new power for the samurai class', 'rapid modernisation of economy and society', 'borders closed for another century', 'the capital returned to Nara'], answer: 1, explanation: 'The Restoration brought sweeping economic, political and social change.' },
  // -- Historical concepts and skills (145–158) --
  { id: 'y8-hum-145', q: 'The concept of continuity and change recognises that:', choices: ['some things change while others persist', 'everything changes completely over time', 'nothing truly changes', 'only rulers ever change'], answer: 0, explanation: 'Many things change — some drastically — while others continue, even in modified forms.' },
  { id: 'y8-hum-146', q: 'Historical empathy means:', choices: ['feeling sorry for people in the past', 'agreeing with past decisions', 'judging the past by modern rules', 'seeing events as people at the time did'], answer: 3, explanation: 'Empathy is understanding the past from the perspective of those living then — not sympathy or agreement.' },
  { id: 'y8-hum-147', q: 'An event has historical SIGNIFICANCE if it:', choices: ['brought deep, lasting change for many', 'is famous and often filmed today', 'happened an extremely long time ago', 'involved a king, queen or emperor'], answer: 0, explanation: 'Significance means deep consequences for many people over a long period, and/or being revealing about the past.' },
  { id: 'y8-hum-148', q: 'Contestability in history means:', choices: ['historians can never be trusted', 'interpretations stay open to debate', 'all sources are secretly fake', 'only one version can ever be right'], answer: 1, explanation: 'Interpretations may be challenged because of limited evidence or different perspectives — that is normal scholarship.' },
  { id: 'y8-hum-149', q: 'The concept of cause and effect links:', choices: ['maps to their scales', 'artefacts to museums', 'motives and actions to outcomes', 'dates to centuries'], answer: 2, explanation: 'It connects what causes an action — or motivates someone — with the outcome of that action.' },
  { id: 'y8-hum-150', q: 'A person’s historical perspective is shaped by:', choices: ['their age, beliefs and position', 'the calendar system they used', 'the length of the source', 'the printing method used'], answer: 0, explanation: 'Perspectives reflect prejudices, fears, age, gender and education.' },
  { id: 'y8-hum-151', q: 'Evidence, as a historical concept, is:', choices: ['any object older than a century', 'information gained by questioning sources', 'a historian’s personal opinion', 'the label beside a museum display'], answer: 1, explanation: 'Evidence is the information or clues discovered by asking specific questions about a source.' },
  { id: 'y8-hum-152', q: 'A COMA analysis in Year 8 history is applied to:', choices: ['a climate graph', 'a maths problem', 'a fitness test', 'a historical source'], answer: 3, explanation: 'COMA scaffolds source analysis — from the Genpei battle screens to Church documents.' },
  { id: 'y8-hum-153', q: 'TEEAL is used in this class to structure:', choices: ['a source citation', 'a bibliography', 'an analytical paragraph', 'a mind map'], answer: 2, explanation: 'TEEAL paragraphs are the standard extended-writing scaffold across the history units.' },
  { id: 'y8-hum-154', q: 'Which is a PRIMARY source for shogunate Japan?', choices: ['a 2024 documentary', 'a Muromachi-period painted screen', 'a modern textbook chapter', 'a website about samurai'], answer: 1, explanation: 'A primary source comes from the period studied — like the Genpei battle screen painted in the Muromachi period.' },
  { id: 'y8-hum-155', q: 'Which is a SECONDARY source about the Black Death?', choices: ['a modern documentary about the plague', 'a 1349 town record of burials', 'a plague doctor’s letter from 1350', 'a medieval chronicle entry'], answer: 0, explanation: 'Secondary sources are made after the time studied; the other three come from the plague years themselves.' },
  { id: 'y8-hum-156', q: 'Placing the Nara, Heian, Kamakura and Tokugawa periods in order tests:', choices: ['empathy', 'contestability', 'chronology', 'quantification'], answer: 2, explanation: 'Chronology is sequencing events and periods in time order.' },
  { id: 'y8-hum-157', q: 'When two chronicles disagree about the Ashikaga collapse, a historian should:', choices: ['discard both accounts as useless', 'always trust the older account', 'always trust the shorter account', 'weigh each one’s evidence and viewpoint'], answer: 3, explanation: 'Disagreement calls for evaluating evidence and perspective, not automatic rules.' },
  { id: 'y8-hum-158', q: 'Comparing samurai with medieval knights is an exercise in examining:', choices: ['cause and effect within one society', 'similarity and difference across societies', 'the reliability of a single source', 'scientific dating of artefacts'], answer: 1, explanation: 'The comparison task looks at similarities and differences between two feudal societies.' },
  // -- Landscapes and processes (159–188) --
  { id: 'y8-hum-159', q: 'A landscape is best defined as:', choices: ['a single hill or valley', 'any photograph of nature', 'an area’s visible features formed over time', 'a hand-drawn map'], answer: 2, explanation: 'A landscape is part of Earth’s surface with characteristic features built up over time; a landform is one feature within it.' },
  { id: 'y8-hum-160', q: 'A landform is:', choices: ['a single surface feature such as a dune', 'the weather of a region', 'a country’s borders', 'a type of vegetation'], answer: 0, explanation: 'Landforms are individual features — dunes, plateaus, beaches, valleys — identified by their shape.' },
  { id: 'y8-hum-161', q: 'Which of the following is a NATURAL landscape type?', choices: ['human', 'urban', 'industrial', 'karst'], answer: 3, explanation: 'The unit’s seven types are mountain, coastal, riverine, desert, karst, tropical rainforest and human — karst is the natural one here.' },
  { id: 'y8-hum-162', q: 'Human landscapes are also called:', choices: ['karst landscapes', 'cultural landscapes', 'riverine landscapes', 'coastal landscapes'], answer: 1, explanation: 'Landscapes created and modified by people are sometimes called cultural landscapes.' },
  { id: 'y8-hum-163', q: 'Mountain landscapes form when:', choices: ['waves erode the coastline', 'rivers deposit silt', 'tectonic plates push against each other', 'wind builds up dunes'], answer: 2, explanation: 'Plate movement pushes land upward over time, forming mountains, ranges and ridges.' },
  { id: 'y8-hum-164', q: 'Riverine landscapes are valuable for farming because:', choices: ['the land is rich and fertile', 'they never flood', 'they contain little water', 'the soil is mostly sand'], answer: 0, explanation: 'Riverine land is fertile — excellent for agriculture and growing food.' },
  { id: 'y8-hum-165', q: 'A desert is defined by its:', choices: ['high temperatures', 'sandy surface', 'lack of any life', 'very low rainfall'], answer: 3, explanation: 'Deserts are defined by rainfall, not heat — cold deserts exist, and desert surfaces can be rock and gravel.' },
  { id: 'y8-hum-166', q: 'Cold deserts are found:', choices: ['along the Equator', 'near the Arctic and Antarctic Circles', 'only in central Australia', 'beside warm tropical seas'], answer: 1, explanation: 'Hot deserts sit along the tropics; cold deserts lie closer to the polar circles.' },
  { id: 'y8-hum-167', q: 'Deserts cover about what share of Earth’s land?', choices: ['one-third', 'one-tenth', 'three-quarters', 'one-hundredth'], answer: 0, explanation: 'About a third of Earth’s land surface is desert — including some of the most uninhabitable regions on Earth.' },
  { id: 'y8-hum-168', q: 'Karst landscapes form when:', choices: ['glaciers carve deep valleys', 'wind polishes granite domes', 'acidic water dissolves rock such as limestone', 'volcanoes build steep cones'], answer: 2, explanation: 'Slightly acidic water wears away dissolvable bedrock, creating caves, stalactites, springs and sinkholes.' },
  { id: 'y8-hum-169', q: 'Features of karst landscapes include:', choices: ['spits, bars and tombolos', 'dunes, beaches and lagoons', 'gorges, deltas and floodplains', 'caves, sinkholes and stalactites'], answer: 3, explanation: 'Caves, stalactites, springs and sinkholes mark karst country; the other sets are coastal or river features.' },
  { id: 'y8-hum-170', q: 'Sinkholes form when:', choices: ['a river suddenly changes course', 'eroded rock below lets the surface collapse', 'waves undercut a coastal cliff', 'tree roots force boulders apart'], answer: 1, explanation: 'When rock beneath the surface erodes away, sections of land above can collapse — sometimes swallowing cars and buildings.' },
  { id: 'y8-hum-171', q: 'Tropical rainforests receive at least:', choices: ['25 mm of rain a year', '150 mm of rain a year', '1500 mm of rain a year', '15,000 mm of rain a year'], answer: 2, explanation: 'Rainforests get abundant rain (1500 mm or more) and sunlight, so vegetation grows rapidly.' },
  { id: 'y8-hum-172', q: 'Rainforests cover about 6% of Earth’s surface yet contain:', choices: ['50–70% of all species', 'under 5% of all species', 'exactly 25% of all species', 'no species found elsewhere'], answer: 0, explanation: 'Rainforest ecosystems are home to roughly 50 to 70 per cent of all species on Earth.' },
  { id: 'y8-hum-173', q: 'Weathering is the process that:', choices: ['moves sediment along coasts', 'breaks rocks down in the same place', 'deposits sand on beaches', 'creates waves at sea'], answer: 1, explanation: 'Weathering breaks rock apart without moving it — erosion is what transports the pieces.' },
  { id: 'y8-hum-174', q: 'The key difference between weathering and erosion is that:', choices: ['weathering is always faster', 'erosion only happens at sea', 'weathering needs living things', 'erosion moves material; weathering does not'], answer: 3, explanation: 'Weathering weakens and breaks rock in place; erosion transports the material away.' },
  { id: 'y8-hum-175', q: 'Water freezing and expanding in rock cracks is:', choices: ['physical weathering', 'chemical weathering', 'biological weathering', 'deposition'], answer: 0, explanation: 'Freeze–thaw is physical weathering — the rock is broken without changing its chemistry.' },
  { id: 'y8-hum-176', q: 'Slightly acidic rainwater dissolving limestone is:', choices: ['physical weathering', 'biological weathering', 'chemical weathering', 'longshore drift'], answer: 2, explanation: 'Chemical weathering changes or dissolves the rock itself — common in limestone country.' },
  { id: 'y8-hum-177', q: 'Tree roots growing into cracks and splitting rock is:', choices: ['chemical weathering', 'physical weathering', 'deposition', 'biological weathering'], answer: 3, explanation: 'Living things — roots, burrowing animals, moss — cause biological weathering.' },
  { id: 'y8-hum-178', q: 'The split boulders at the Devils Marbles were caused by:', choices: ['water freezing and expanding in cracks', 'acid rain dissolving the rock', 'burrowing desert animals', 'ocean waves in ancient times'], answer: 0, explanation: 'Cold desert nights freeze water in cracks; the expansion slowly splits the rock — physical weathering.' },
  { id: 'y8-hum-179', q: 'Erosion is defined as:', choices: ['rock breaking down in place', 'the movement of weathered material', 'sediment settling in new places', 'water evaporating from lakes'], answer: 1, explanation: 'Erosion is transportation — wind, water and waves carry weathered material across landscapes.' },
  { id: 'y8-hum-180', q: 'Deposition happens when:', choices: ['rocks first crack apart', 'plants colonise a dune', 'wind or water loses energy and drops sediment', 'the tide rises at dusk'], answer: 2, explanation: 'When the transporting force loses energy, the sediment it carries settles and builds up landforms.' },
  { id: 'y8-hum-181', q: 'Which sequence turns rock into a beach?', choices: ['deposition, then weathering, then erosion', 'erosion, then weathering, then deposition', 'weathering, then deposition, then erosion', 'weathering, then erosion, then deposition'], answer: 3, explanation: 'Rock is broken down, the pieces are transported, then dropped where energy is lost — in that order.' },
  { id: 'y8-hum-182', q: 'Which is an example of deposition?', choices: ['a cliff face collapsing into the sea', 'sand settling to build up a beach', 'rainwater dissolving limestone', 'waves cutting a notch in a headland'], answer: 1, explanation: 'Deposition builds — beaches and dunes grow where sediment settles.' },
  { id: 'y8-hum-183', q: 'Weathering prepares rock for erosion by:', choices: ['weakening and breaking it into pieces', 'carrying it out to sea', 'cementing it back together', 'instantly turning it to soil'], answer: 0, explanation: 'Weathered, broken rock is what erosion can then pick up and move.' },
  { id: 'y8-hum-184', q: 'Desert rocks crack after hot days and cold nights because the rock:', choices: ['melts and refreezes', 'dissolves and reforms', 'expands and contracts', 'floats and settles'], answer: 2, explanation: 'Repeated expansion and contraction stresses the rock until cracks form — physical weathering.' },
  { id: 'y8-hum-185', q: 'Moss growing across a rock surface causes:', choices: ['chemical erosion', 'physical deposition', 'coastal drift', 'biological weathering'], answer: 3, explanation: 'Moss and plants breaking down rock surfaces are biological weathering.' },
  { id: 'y8-hum-186', q: 'Which process happens WITHOUT the rock being moved?', choices: ['erosion', 'longshore drift', 'deposition', 'weathering'], answer: 3, explanation: 'Weathering happens in place; erosion and drift transport material, and deposition drops it somewhere new.' },
  { id: 'y8-hum-187', q: 'The three processes constantly reshaping landscapes are:', choices: ['swash, backwash and drift', 'weathering, erosion and deposition', 'pattern, quantify and exception', 'push, pull and migration'], answer: 1, explanation: 'Weathering, erosion and deposition drive landscape change; the other trios are coastal terms, PQE and migration factors.' },
  { id: 'y8-hum-188', q: 'Erosion’s transport agents include:', choices: ['moss, roots and burrowing animals', 'freezing, heating and cooling', 'water, wind and waves', 'settling, sinking and cementing'], answer: 2, explanation: 'Water, wind and waves move material; the first two sets cause weathering and the last describes deposition.' },
  // -- Coasts 1: Waves, swash and longshore drift (189–204) --
  { id: 'y8-hum-189', q: 'The coast is defined as:', choices: ['where a land mass meets the sea', 'any sandy area near water', 'the mouth of a river', 'water deeper than ten metres'], answer: 0, explanation: 'The coast is the meeting line of land and sea — constantly reshaped by wind and waves.' },
  { id: 'y8-hum-190', q: 'Coastal landscapes are shaped mainly by:', choices: ['ice and snowfall', 'wind and waves', 'earthquakes alone', 'human buildings alone'], answer: 1, explanation: 'The unit’s two geomorphic forces are wind and waves, which erode or construct the coast.' },
  { id: 'y8-hum-191', q: 'Waves begin at sea when:', choices: ['the Moon pulls the tide', 'rivers push into the ocean', 'wind blows across the water surface', 'fish disturb the surface'], answer: 2, explanation: 'Wind drags the surface up while gravity pulls it down, creating the orbit we see as a wave.' },
  { id: 'y8-hum-192', q: 'A wave’s circular orbit comes from wind drag competing with:', choices: ['salinity', 'temperature', 'magnetism', 'gravity'], answer: 3, explanation: 'The tug-of-war between the drag of the wind and the pull of gravity creates the orbital motion of water.' },
  { id: 'y8-hum-193', q: 'Swash is the movement of water:', choices: ['up the beach after a wave breaks', 'down the beach to the sea', 'parallel to the horizon', 'beneath the sand'], answer: 0, explanation: 'Swash runs up the beach; backwash returns down it.' },
  { id: 'y8-hum-194', q: 'Backwash is the movement of water:', choices: ['up the beach after breaking', 'down the beach back to the sea', 'along the beach in a zigzag', 'straight up as spray'], answer: 1, explanation: 'Backwash is the water running back down the beach to the ocean after a wave breaks.' },
  { id: 'y8-hum-195', q: 'Constructive waves:', choices: ['strip beaches during storms', 'never reach the shore', 'deposit material and build beaches', 'always carry no sand'], answer: 2, explanation: 'Constructive waves are gentler, calm-weather waves that deposit material and build up beaches.' },
  { id: 'y8-hum-196', q: 'Destructive waves occur:', choices: ['in calm weather', 'only in summer', 'where there is no wind', 'in storm conditions with high energy'], answer: 3, explanation: 'Destructive waves are storm waves created by strong winds that have blown for a long time.' },
  { id: 'y8-hum-197', q: 'In a constructive wave:', choices: ['backwash is stronger than swash', 'swash is stronger than backwash', 'swash and backwash are equal', 'there is no backwash at all'], answer: 1, explanation: 'Stronger swash pushes material up the beach — building it.' },
  { id: 'y8-hum-198', q: 'In a destructive wave:', choices: ['swash is stronger than backwash', 'neither swash nor backwash occurs', 'backwash is stronger than swash', 'the wave carries no energy'], answer: 2, explanation: 'Stronger backwash drags material off the beach — eroding it.' },
  { id: 'y8-hum-199', q: 'Destructive waves are associated with:', choices: ['erosion of the coast', 'building up beaches', 'depositing spits', 'calming the sea'], answer: 0, explanation: 'They remove material from the coast; constructive waves deposit it.' },
  { id: 'y8-hum-200', q: 'Longshore drift moves sediment:', choices: ['straight out to deep water', 'vertically up cliff faces', 'only during low tide', 'in a zigzag along the beach'], answer: 3, explanation: 'Angled swash and straight backwash shift material sideways along the coast.' },
  { id: 'y8-hum-201', q: 'Waves approach the shore at an angle because of:', choices: ['the pull of the Moon', 'the prevailing wind direction', 'the shape of the sea floor alone', 'boat traffic offshore'], answer: 1, explanation: 'The prevailing wind sets the angle waves travel toward the coast — the driver of longshore drift.' },
  { id: 'y8-hum-202', q: 'In longshore drift, the backwash runs:', choices: ['at the same angle as the swash', 'along the beach horizontally', 'straight down the beach slope', 'upward against gravity'], answer: 2, explanation: 'Swash pushes material up at an angle; backwash takes the shortest path straight back down.' },
  { id: 'y8-hum-203', q: 'A beach with strong longshore drift will:', choices: ['have sand carried steadily along the shore', 'keep its sand fixed in one place', 'gradually harden into rock', 'sink below sea level'], answer: 0, explanation: 'Drift moves beach material sideways along the coast — the reason groynes exist.' },
  { id: 'y8-hum-204', q: 'Which conditions produce destructive waves?', choices: ['gentle breezes on a calm day', 'a completely windless week', 'icebergs drifting offshore', 'strong winds blowing for a long time'], answer: 3, explanation: 'High energy comes from strong, sustained wind and waves that have travelled a long way.' },
  // -- Coasts 2: Coastal landforms (205–222) --
  { id: 'y8-hum-205', q: 'Coastal landforms fall into two categories:', choices: ['natural and artificial', 'erosional and depositional', 'wet and dry', 'ancient and modern'], answer: 1, explanation: 'Every coastal landform is built by deposition or carved by erosion.' },
  { id: 'y8-hum-206', q: 'Bays form where:', choices: ['rivers meet the sea', 'sand builds over reefs', 'softer rock erodes faster than harder rock', 'volcanoes collapse into the sea'], answer: 2, explanation: 'Alternating rock bands erode unevenly — soft rock becomes the bay, hard rock the headland.' },
  { id: 'y8-hum-207', q: 'A headland is:', choices: ['a sheltered sandy inlet', 'a sunken sea cave', 'an offshore sandbar', 'hard rock jutting out into the sea'], answer: 3, explanation: 'Headlands are the resistant rock left protruding as softer neighbours erode into bays.' },
  { id: 'y8-hum-208', q: 'The correct order of headland erosion is:', choices: ['cave, arch, stack, stump', 'stump, stack, arch, cave', 'arch, cave, stump, stack', 'stack, arch, cave, stump'], answer: 0, explanation: 'A crack widens to a cave, cuts through as an arch, collapses to a stack, then wears down to a stump.' },
  { id: 'y8-hum-209', q: 'A stack forms when:', choices: ['a spit joins an island', 'an arch roof collapses', 'sand piles above the tide line', 'a river deposits silt'], answer: 1, explanation: 'When the arch can no longer support its roof, it collapses, leaving an isolated stack.' },
  { id: 'y8-hum-210', q: 'Waves erode headlands on three sides because of:', choices: ['longshore drift', 'tidal pull', 'wave refraction', 'wind shear'], answer: 2, explanation: 'Refraction bends waves around headlands, concentrating erosion on them.' },
  { id: 'y8-hum-211', q: 'Erosion of cracks and joints in headlands is mainly driven by:', choices: ['the growth of moss and algae', 'quarrying by early settlers', 'heat from direct sunlight', 'hydraulic pressure from waves'], answer: 3, explanation: 'Waves attack weaknesses in the rock; hydraulic pressure is the main erosive force.' },
  { id: 'y8-hum-212', q: 'A blowhole forms when:', choices: ['wind hollows out the back of a beach', 'waves erode a crack up through the headland', 'a sand dune collapses inward', 'a river tunnels beneath the cliffs'], answer: 1, explanation: 'If the sea erodes upward along a large crack to the headland’s top, a blowhole is created.' },
  { id: 'y8-hum-213', q: 'A wave-cut platform is:', choices: ['a wooden platform for fishing', 'a zone reserved for surfing', 'bare rock left as a cliff retreats', 'a forest drowned by rising seas'], answer: 2, explanation: 'As collapse after collapse moves the cliff back, an expanse of bare rock is left at its base.' },
  { id: 'y8-hum-214', q: 'Wave-cut platforms are visible:', choices: ['at low tide', 'at high tide', 'only from the air', 'only after storms'], answer: 0, explanation: 'High tide covers the platform; it emerges as the water drops.' },
  { id: 'y8-hum-215', q: 'Cliffs collapse and retreat because waves erode:', choices: ['the top of the cliff first', 'the middle band only', 'the beach behind them', 'the base of the cliff at high tide'], answer: 3, explanation: 'Undercutting at the base leaves the cliff unsupported, so it collapses and the coastline retreats.' },
  { id: 'y8-hum-216', q: 'Beaches are made of:', choices: ['clay and mud only', 'sand, shingle or pebbles', 'coral fragments only', 'solid rock slabs'], answer: 1, explanation: 'Beach material accumulates between the lowest and highest spring tides.' },
  { id: 'y8-hum-217', q: 'Beach material comes from longshore drift, constructive waves, cliff erosion and:', choices: ['volcanic ash falls', 'melting glaciers', 'river discharge', 'deep ocean trenches'], answer: 2, explanation: 'Rivers deliver sediment to the coast — the fourth source the unit lists.' },
  { id: 'y8-hum-218', q: 'Sand dunes form when:', choices: ['wind piles dried sand inland', 'waves compress wet sand into ridges', 'rivers dump gravel at the shore', 'high tides freeze the beach'], answer: 0, explanation: 'Wind picks up dry sand and blows it inland, where it piles into dunes held together by plants.' },
  { id: 'y8-hum-219', q: 'Plants matter to sand dunes because they:', choices: ['draw tourists to the foreshore', 'add nutrients that darken the sand', 'block the tide from coming in', 'hold the dune’s sand in place'], answer: 3, explanation: 'Vegetation like Spinifex binds sand with its roots — remove it and dunes can migrate inland.' },
  { id: 'y8-hum-220', q: 'A blowout dune is one that:', choices: ['erupts from built-up gas pressure', 'forms entirely under water', 'moves inland after losing its plants', 'was planted by local councils'], answer: 2, explanation: 'Without vegetation, whole dunes can gradually move inland, burying roads and paddocks.' },
  { id: 'y8-hum-221', q: 'A spit is:', choices: ['an island of bare solid rock', 'a sand ridge tied to land at one end', 'a concrete wall built by engineers', 'a deep channel cut by the tide'], answer: 1, explanation: 'Spits grow from longshore drift; secondary winds often curve their free end into a hook.' },
  { id: 'y8-hum-222', q: 'A tombolo connects:', choices: ['two rivers into one mouth', 'two coastal towns by bridge', 'a sea cave to its stack', 'an island to the mainland'], answer: 3, explanation: 'A tombolo is a spit that reaches an island; a bar closes off a bay, forming a lagoon behind it.' },
  // -- Coasts 3: Valuing coastal landscapes (223–234) --
  { id: 'y8-hum-223', q: 'The five ways of valuing landscapes in the unit are aesthetic, spiritual, economic, environmental and:', choices: ['cultural', 'financial', 'political', 'industrial'], answer: 0, explanation: 'Cultural value covers identity, belonging, customs and art connected to a landscape.' },
  { id: 'y8-hum-224', q: 'Aesthetic value refers to a landscape’s:', choices: ['income from resources', 'beauty and the feelings it inspires', 'sacred Dreaming stories', 'endangered species'], answer: 1, explanation: 'Aesthetic value is about scenery, awe, freedom and wellbeing.' },
  { id: 'y8-hum-225', q: 'In Australia, the spiritual value of coastal places is often linked to:', choices: ['tourism income and employment', 'scenic beauty and photography', 'habitat for migratory birds', 'Dreaming stories and Country'], answer: 3, explanation: 'Spiritual value is often tied to Dreaming stories, ancestors, sacred meaning and connection to Country.' },
  { id: 'y8-hum-226', q: 'Income from tourism and fishing shows a landscape’s:', choices: ['economic value', 'aesthetic value', 'spiritual value', 'cultural value'], answer: 0, explanation: 'Economic value covers income from tourism, resources, services and employment.' },
  { id: 'y8-hum-227', q: 'Ecosystems, habitats and biodiversity represent which value type?', choices: ['economic', 'aesthetic', 'environmental', 'cultural'], answer: 2, explanation: 'Environmental value is the landscape’s role in supporting life.' },
  { id: 'y8-hum-228', q: '"Use" differs from "value" because value explains:', choices: ['what people do at a place', 'why a place matters', 'how large a place is', 'when a place formed'], answer: 1, explanation: 'Uses are context clues; value is why the location matters to a group.' },
  { id: 'y8-hum-229', q: 'The Traditional Owners of the Darwin region are the:', choices: ['Larrakia people', 'Butchulla people', 'Wurundjeri people', 'Noongar people'], answer: 0, explanation: 'The Larrakia people hold an enduring cultural and spiritual relationship with Darwin Harbour Country.' },
  { id: 'y8-hum-230', q: 'Darwin Harbour’s ecosystems include mangroves, mudflats, coral communities and:', choices: ['kelp forests', 'alpine bogs', 'red gum floodplains', 'seagrass meadows'], answer: 3, explanation: 'Its mangroves, mudflats, seagrass meadows and coral support hundreds of species.' },
  { id: 'y8-hum-231', q: 'For the Larrakia people, Darwin Harbour is above all:', choices: ['a strategic naval location', 'a drawcard for cruise tourists', 'part of an enduring connection to Country', 'an industrial shipping hub'], answer: 2, explanation: 'The harbour forms part of a cultural and spiritual relationship developed over thousands of years.' },
  { id: 'y8-hum-232', q: 'Economic uses of Darwin Harbour include shipping, tourism, fishing and:', choices: ['defence operations', 'ski resorts', 'wheat farming', 'opal mining'], answer: 0, explanation: 'Commercial shipping, defence, tourism, recreational fishing and resource industries all rely on the harbour.' },
  { id: 'y8-hum-233', q: 'Tension over Darwin Harbour arises because:', choices: ['no group actually uses the harbour', 'different groups value it in different ways', 'its natural features have been lost', 'all development there is illegal'], answer: 1, explanation: 'Development, conservation and cultural priorities can compete — the heart of the case study.' },
  { id: 'y8-hum-234', q: 'The same coastal landscape can hold spiritual AND economic value:', choices: ['only once it has been developed', 'only within large coastal cities', 'at the same time, for different groups', 'only if a court divides its uses'], answer: 2, explanation: 'Darwin Harbour shows one landscape carrying several values at once — which is why decisions get contested.' },
  // -- Coasts 4: Coastal management (235–250) --
  { id: 'y8-hum-235', q: 'Coastal management is best defined as attempts to:', choices: ['halt the movement of the tides', 'keep visitors away from beaches', 'freeze the coastline exactly as it is', 'keep coastal features useful to people'], answer: 3, explanation: 'Management aims to maintain the coast’s natural features for people’s advantage.' },
  { id: 'y8-hum-236', q: 'Hard engineering uses:', choices: ['heavy human-made structures', 'planted grasses and drifting sand', 'storm forecasts and warnings', 'insurance and planning laws'], answer: 0, explanation: 'Hard engineering builds physical barriers — sea walls, groynes, rock armour, breakwaters.' },
  { id: 'y8-hum-237', q: 'Compared with hard engineering, soft engineering is usually:', choices: ['dearer but completely permanent', 'cheaper and more sustainable', 'banned along Australian coasts', 'restricted to offshore reefs'], answer: 1, explanation: 'Soft engineering works with natural processes — often cheaper, longer-term and gentler on environments.' },
  { id: 'y8-hum-238', q: 'Groynes are built:', choices: ['parallel to the shoreline', 'underwater on reefs', 'at a right angle to the beach', 'on top of coastal cliffs'], answer: 2, explanation: 'Groynes run perpendicular to the shore, out into the sea.' },
  { id: 'y8-hum-239', q: 'Groynes work by:', choices: ['bouncing wave energy back to sea', 'sheltering seaweed and shellfish beds', 'warming the sand for beach users', 'trapping sand moved by longshore drift'], answer: 3, explanation: 'Acting like a dam for sand, they interrupt longshore drift and widen the up-drift beach.' },
  { id: 'y8-hum-240', q: 'A key downside of groynes is that:', choices: ['beaches down-drift are starved of sand', 'they draw sharks closer to shore', 'they soften and sag in summer heat', 'they make fishing illegal nearby'], answer: 0, explanation: 'Sand trapped on one side means less sediment travels on — down-drift beaches shrink.' },
  { id: 'y8-hum-241', q: 'Sea walls often fail over time because:', choices: ['they attract too many tourists', 'wave scouring undermines their base', 'sand buries them completely', 'they float away in storms'], answer: 1, explanation: 'Reflected wave energy scours away sand at the base, eventually undermining the wall.' },
  { id: 'y8-hum-242', q: 'Unlike beaches, sea walls:', choices: ['soak up wave energy like a sponge', 'generate new sand as they erode', 'reflect wave energy back to sea', 'give seabirds safe nesting ledges'], answer: 2, explanation: 'Beaches absorb energy; walls concentrate and reflect it — which is why they take maximum impact.' },
  { id: 'y8-hum-243', q: 'Rock armour (rip rap) reduces erosion by:', choices: ['turning waves back with a smooth face', 'damming the rivers that feed the coast', 'trapping warm water close to shore', 'absorbing wave energy between its boulders'], answer: 3, explanation: 'The gaps between boulders dissipate wave energy, so rip rap avoids the scour that afflicts sea walls.' },
  { id: 'y8-hum-244', q: 'Compared with sea walls, rip rap is:', choices: ['cheaper and longer-lasting', 'costlier to build and maintain', 'less permeable to moving water', 'hidden entirely beneath the waves'], answer: 0, explanation: 'Boulder masses cost less and last longer — though they can look industrial and limit beach access.' },
  { id: 'y8-hum-245', q: 'Training walls are built:', choices: ['across bay mouths to form lagoons', 'at river mouths to direct the flow', 'in rings around lighthouse bases', 'behind dunes to stop sand drifting'], answer: 1, explanation: 'Training walls keep river entrances navigable — and block depositional landforms like spits from forming.' },
  { id: 'y8-hum-246', q: 'The Tweed River sand bypassing project became necessary because training walls:', choices: ['made the river flood nearby farmland', 'drew whales into the river mouth', 'blocked sand flowing north to the Gold Coast', 'collapsed during a storm in 1990'], answer: 2, explanation: 'The walls stopped the natural northward sand flow; groynes at Kingscliff now help hold the shoreline.' },
  { id: 'y8-hum-247', q: 'Beach nourishment involves:', choices: ['planting rows of palms for shade', 'building concrete access steps', 'closing beaches to swimmers', 'adding dredged sand to eroding beaches'], answer: 3, explanation: 'Sand is dredged offshore or trucked in — used at the Gold Coast, Adelaide and Miami Beach.' },
  { id: 'y8-hum-248', q: 'A weakness of beach nourishment is that:', choices: ['the new sand poisons local fish', 'one big storm can wash the sand away', 'it always ruins the beach’s look', 'the dredging triggers earthquakes'], answer: 1, explanation: 'A single severe storm can remove vast amounts of the expensive sand, so nourishment must be repeated.' },
  { id: 'y8-hum-249', q: 'Middle Park Beach in Melbourne was rebuilt using:', choices: ['about 35,000 cubic metres of dredged sand', 'a three-kilometre concrete sea wall', 'coral reefs imported from Queensland', 'a line of floating wave-energy farms'], answer: 0, explanation: 'Over 35,000 cubic metres of sand rebuilt the most eroded section to at least 35 metres wide (2014 to 2015).' },
  { id: 'y8-hum-250', q: 'Managed retreat means:', choices: ['stationing guards along the foreshore', 'the tide pulling back before a tsunami', 'closing coastal roads during storms', 'moving development back from the coast'], answer: 3, explanation: 'A controversial strategy: relocate buildings and infrastructure and let the coast erode and change naturally.' },
  // -- Cities and urbanisation (251–284) --
  { id: 'y8-hum-251', q: 'Urbanisation is:', choices: ['a rising share of people living in cities', 'the growth of the world’s population', 'the building of taller skyscrapers', 'migration between countries'], answer: 0, explanation: 'Urbanisation is an increase in the proportion of people living in urban areas — not population growth itself.' },
  { id: 'y8-hum-252', q: 'A megacity has a population of over:', choices: ['1 million', '10 million', '5 million', '100 million'], answer: 1, explanation: 'Megacities top ten million people; there were 34 of them by 2021.' },
  { id: 'y8-hum-253', q: 'In 1950 the world’s largest city was:', choices: ['Tokyo', 'London', 'New York', 'Shanghai'], answer: 2, explanation: 'New York led with about 12 million people in 1950; Tokyo took the crown later.' },
  { id: 'y8-hum-254', q: 'By 2021 the world’s largest city was:', choices: ['Tokyo, at about 37 million', 'New York, at about 12 million', 'Melbourne, at about 5 million', 'Cairo, at about 10 million'], answer: 0, explanation: 'Tokyo reached about 37.3 million; New York’s 12 million led the world back in 1950.' },
  { id: 'y8-hum-255', q: 'Between 1950 and 2021, the number of megacities grew to about:', choices: ['3', '7', '100', '34'], answer: 3, explanation: 'In 1950 only seven cities topped even 5 million; by 2021 there were 34 cities of over 10 million.' },
  { id: 'y8-hum-256', q: 'By 2050, more than two-thirds of the world’s population is expected to live:', choices: ['in urban areas', 'in rural areas', 'in megacities specifically', 'outside Asia'], answer: 0, explanation: 'The estimate is that over two-thirds of people will live in urban areas by 2050.' },
  { id: 'y8-hum-257', q: 'The fastest urban growth to 2050 is expected in:', choices: ['Europe and North America', 'Africa and Asia', 'Australia and New Zealand', 'South America and Europe'], answer: 1, explanation: 'Rapid urban growth is concentrated in developing countries, with Africa and Asia growing fastest.' },
  { id: 'y8-hum-258', q: 'World population in 1950 was about 2.5 billion; by 2021 it was about:', choices: ['4.2 billion', '12.5 billion', '7.9 billion', '3.1 billion'], answer: 2, explanation: 'The urban explosion happened alongside global population growth from 2.5 to 7.9 billion.' },
  { id: 'y8-hum-259', q: 'The rapid growth of cities over the past 80 years is called:', choices: ['the urban explosion', 'the green revolution', 'gentrification', 'managed retreat'], answer: 0, explanation: 'The unit calls the leap from seven big cities (1950) to 34 megacities (2021) the urban explosion.' },
  { id: 'y8-hum-260', q: 'Historically, cities have tended to grow up near:', choices: ['deserts and ice sheets', 'volcano rims', 'mountain summits', 'rivers, harbours and trade routes'], answer: 3, explanation: 'Water access and trade links explain why cities are located where they are.' },
  { id: 'y8-hum-261', q: 'The CBD of a city is its:', choices: ['largest housing estate', 'commercial and business centre', 'industrial port zone', 'green parkland belt'], answer: 1, explanation: 'The Central Business District is the busiest commercial core — sometimes called downtown.' },
  { id: 'y8-hum-262', q: 'CBD buildings are tall because:', choices: ['bedrock there supports extra weight', 'planning laws forbid low buildings', 'high land prices push building upward', 'tourists prefer visiting towers'], answer: 2, explanation: 'Competition for space makes CBD land expensive, so developers build up to maximise it.' },
  { id: 'y8-hum-263', q: 'The largest area of any city is usually its:', choices: ['residential zones', 'central business district', 'industrial zones', 'green zones'], answer: 0, explanation: 'Residential zones — housing plus local facilities like schools and hospitals — cover the most area.' },
  { id: 'y8-hum-264', q: 'Commercial zones are usually located:', choices: ['in the middle of parkland', 'on islands away from customers', 'underground beneath the CBD', 'along major roads'], answer: 3, explanation: 'Retail and hospitality businesses cluster along major roads — from big centres to local strips.' },
  { id: 'y8-hum-265', q: 'Industrial zones sit near ports, freeways and rail lines because factories need:', choices: ['views to attract workers', 'good transport for goods', 'quiet residential neighbours', 'the tallest buildings available'], answer: 1, explanation: 'Industry locates near transport links — and as far from residential areas as possible.' },
  { id: 'y8-hum-266', q: 'Industrial zones are usually placed:', choices: ['far from residential areas', 'inside shopping strips', 'next to primary schools', 'in the exact city centre'], answer: 0, explanation: 'Factories, mills and warehouses are kept away from housing but close to transport.' },
  { id: 'y8-hum-267', q: 'Green zones benefit cities by providing recreation and:', choices: ['cheap land for future factories', 'overflow parking for commuters', 'habitat for native plants and animals', 'space for high-rise expansion'], answer: 2, explanation: 'Parkland offers sport and recreation and keeps native plant and animal populations healthy.' },
  { id: 'y8-hum-268', q: 'The Multiple Nuclei Model was proposed by:', choices: ['Burgess in 1925', 'Hoyt in 1939', 'Le Corbusier in 1952', 'Harris and Ullman in 1945'], answer: 3, explanation: 'Harris and Ullman presented the model in 1945 to explain how cities develop their shapes.' },
  { id: 'y8-hum-269', q: 'The Multiple Nuclei Model argues that cities:', choices: ['grow around one centre forever', 'develop several scattered centres over time', 'expand only in perfect rings', 'push all industry outside city limits'], answer: 1, explanation: 'Key activities scatter from the original CBD into smaller nuclei that grow and shape the areas around them.' },
  { id: 'y8-hum-270', q: 'The postcode of Melbourne’s CBD is:', choices: ['3000', '2000', '3121', '8001'], answer: 0, explanation: 'Melbourne CBD is postcode 3000 — 2000 is Sydney’s.' },
  { id: 'y8-hum-271', q: 'Migration within the same country is called:', choices: ['international migration', 'immigration', 'internal migration', 'emigration'], answer: 2, explanation: 'Moving to the next town or another state is internal; crossing between countries is international.' },
  { id: 'y8-hum-272', q: 'To emigrate means to:', choices: ['arrive in a new country to live', 'leave your country to live in another', 'move within your city', 'travel abroad for a holiday'], answer: 1, explanation: 'Emigrate is to exit your country; immigrate is to come into another.' },
  { id: 'y8-hum-273', q: 'To immigrate means to:', choices: ['leave a country permanently', 'move house within a suburb', 'commute across a border daily', 'come into a country to live permanently'], answer: 3, explanation: 'Immigration is arriving in a new country to live.' },
  { id: 'y8-hum-274', q: 'War, persecution and a lack of jobs are examples of:', choices: ['push factors', 'pull factors', 'urban dynamics', 'exceptions'], answer: 0, explanation: 'Push factors drive people away from their home region.' },
  { id: 'y8-hum-275', q: 'Better jobs and access to education in cities are:', choices: ['push factors', 'green zones', 'pull factors', 'quantifications'], answer: 2, explanation: 'Pull factors attract people to a destination.' },
  { id: 'y8-hum-276', q: 'Push and pull factors tend to be strongest in:', choices: ['high-income countries (HICs)', 'low-income countries (LICs)', 'small island nations', 'countries with cold climates'], answer: 1, explanation: 'The unit notes these factors may be stronger in LICs than in HICs.' },
  { id: 'y8-hum-277', q: 'A drought forcing farmers off their land is which type of push factor?', choices: ['environmental', 'political', 'social', 'economic'], answer: 0, explanation: 'Migration factors are categorised political, social, economic and environmental — drought is environmental.' },
  { id: 'y8-hum-278', q: 'Urban sprawl is:', choices: ['high-rise growth in the CBD', 'the decline of inner-city factories', 'wealthy renovation of old suburbs', 'low-density expansion at a city’s edges'], answer: 3, explanation: 'Sprawl spreads a city outward with low-density housing and increased car reliance.' },
  { id: 'y8-hum-279', q: 'The unit’s example of urban sprawl is:', choices: ['Detroit', 'New York', 'Melbourne', 'Tokyo'], answer: 2, explanation: 'Melbourne’s outward growth illustrates sprawl; New York shows gentrification and Detroit decay.' },
  { id: 'y8-hum-280', q: 'Gentrification is when:', choices: ['factories close and buildings decay', 'wealthier arrivals change a poorer area', 'a city builds a second CBD', 'parkland replaces housing'], answer: 1, explanation: 'Wealthier people move in, improve housing and attract new businesses — often displacing residents.' },
  { id: 'y8-hum-281', q: 'A common negative effect of gentrification is:', choices: ['displacement of existing residents', 'falling house prices everywhere', 'the loss of all local businesses', 'lower land values in the CBD'], answer: 0, explanation: 'As an area gentrifies, current inhabitants are often priced out.' },
  { id: 'y8-hum-282', q: 'The unit’s example of gentrification changing shopfronts is:', choices: ['Melbourne', 'Detroit', 'Kyoto', 'New York'], answer: 3, explanation: 'New York’s changing shopfronts illustrate gentrification.' },
  { id: 'y8-hum-283', q: 'Urban decay in Detroit followed:', choices: ['a volcanic eruption', 'the growth of tourism', 'the decline of car manufacturing', 'rising farm prices'], answer: 2, explanation: 'Detroit’s decay tracked the closure of car manufacturing — infrastructure fell into disrepair.' },
  { id: 'y8-hum-284', q: 'Urban renewal means:', choices: ['demolishing all pre-war buildings', 'redeveloping unused city land', 'relocating the CBD to the suburbs', 'banning new apartment towers'], answer: 1, explanation: 'Renewal takes land in a city that is no longer being used and redevelops it.' },
  // -- Geography skills (285–302) --
  { id: 'y8-hum-285', q: 'BOLTSS is the checklist for a complete:', choices: ['graph', 'map', 'field sketch', 'photograph'], answer: 1, explanation: 'Maps use BOLTSS; graphs use SALTS.' },
  { id: 'y8-hum-286', q: 'The Prime Meridian is the line of:', choices: ['0 degrees longitude', '0 degrees latitude', 'the Tropic of Capricorn', 'the Antarctic Circle'], answer: 0, explanation: 'The Prime Meridian is 0° longitude; the Equator is 0° latitude.' },
  { id: 'y8-hum-287', q: 'The Equator is:', choices: ['a line joining the two poles', 'the official boundary of Asia', '0 degrees latitude around Earth’s middle', 'an ancient sea trade route'], answer: 2, explanation: 'The Equator circles Earth’s middle at 0° latitude, dividing the hemispheres.' },
  { id: 'y8-hum-288', q: 'Which is one of Earth’s five oceans?', choices: ['the Mediterranean Ocean', 'the Caspian Ocean', 'the Coral Ocean', 'the Southern Ocean'], answer: 3, explanation: 'The five are the Pacific, Atlantic, Indian, Arctic and Southern; the others named here are seas.' },
  { id: 'y8-hum-289', q: 'Sub-Saharan Africa, the Caribbean and South-East Asia are examples of:', choices: ['world regions', 'continents', 'countries', 'hemispheres'], answer: 0, explanation: 'The mapping deck has students annotate world regions — groupings within or across continents.' },
  { id: 'y8-hum-290', q: 'PQE stands for:', choices: ['Place, Quantity, Environment', 'Pattern, Quantification, Exception', 'Pattern, Question, Explanation', 'Point, Quote, Evaluate'], answer: 1, explanation: 'PQE is the method for describing map and graph data: Pattern, Quantification, Exception.' },
  { id: 'y8-hum-291', q: 'In PQE, quantifying the pattern means:', choices: ['describing it with adjectives', 'drawing it as a sketch', 'backing it with numerical data', 'finding who made the map'], answer: 2, explanation: 'Quantification uses numbers from the legend, scale or graph as evidence for the pattern.' },
  { id: 'y8-hum-292', q: 'In PQE, an exception is:', choices: ['an error the mapmaker made', 'the map’s missing legend', 'the largest value shown', 'data that does not fit the main pattern'], answer: 3, explanation: 'An exception is a real trend outside the pattern — like the high-rainfall pocket in south-west Australia.' },
  { id: 'y8-hum-293', q: 'Words like "clustered", "uneven" and "fluctuate" are used to describe:', choices: ['patterns in maps and graphs', 'the reliability of sources', 'wave energy at coasts', 'social classes in Japan'], answer: 0, explanation: 'These are the unit’s pattern-describing words for the P in PQE.' },
  { id: 'y8-hum-294', q: 'SALTS is the checklist for constructing:', choices: ['maps', 'essays', 'graphs', 'timelines'], answer: 2, explanation: 'SALTS — Scale, Axis, Legend, Title, Source — applies to graphs.' },
  { id: 'y8-hum-295', q: 'In SALTS, the L stands for:', choices: ['latitude', 'legend', 'label', 'line'], answer: 1, explanation: 'A legend explains the colours, shading, lines or symbols used on the graph.' },
  { id: 'y8-hum-296', q: '"Uluru is 3.6 km long" is an example of:', choices: ['quantitative data', 'qualitative data', 'an exception', 'a pull factor'], answer: 0, explanation: 'Quantitative data is numerical; qualitative data is recorded in words.' },
  { id: 'y8-hum-297', q: '"Uluru is a very large rock" is an example of:', choices: ['quantitative data', 'primary data', 'a push factor', 'qualitative data'], answer: 3, explanation: 'Descriptive statements in words are qualitative data.' },
  { id: 'y8-hum-298', q: 'An oblique aerial photo is taken:', choices: ['straight down from an aircraft', 'from a satellite in orbit', 'at an angle from a high point', 'at ground level looking up'], answer: 2, explanation: 'Oblique photos angle the camera — covering more ground and showing feature heights.' },
  { id: 'y8-hum-299', q: 'Vertical aerial photos suit measuring distances because:', choices: ['their colours print more brightly', 'their scale is nearly uniform throughout', 'they always include the horizon', 'they make tall objects look taller'], answer: 1, explanation: 'Near-uniform scale keeps measurements accurate — over flat terrain they can even be used like a map.' },
  { id: 'y8-hum-300', q: 'Satellite images are especially useful for:', choices: ['measuring one building precisely', 'reading individual street names', 'judging the height of a single hill', 'tracking change in land cover over time'], answer: 3, explanation: 'Satellites circle constantly — geographers compare images over time, like Amazon deforestation 2001 to 2019.' },
  { id: 'y8-hum-301', q: 'In a good field sketch, the horizon sits:', choices: ['exactly across the middle', 'along the bottom edge', 'wherever looks most artistic', 'about one-third from the top'], answer: 3, explanation: 'Step 2 of the sketching guide places the horizon about a third from the top of the frame.' },
  { id: 'y8-hum-302', q: 'The final step of a field sketch is adding:', choices: ['an extra layer of shading', 'a photograph for comparison', 'the location and date', 'a small graph of the scenery'], answer: 2, explanation: 'Sketches finish with labels for the most important parts, then the location and date.' },
  // Y8_HUM_MCQ_END
];

